insert into public.questions (
  language_id, topic_id, slug, question, answer, example, code, code_language, difficulty, tags, is_frequently_asked, display_order
)
select l.id, t.id, v.slug, v.question, v.answer, v.example, v.code, v.code_language, v.difficulty, v.tags, v.is_frequently_asked, v.display_order
from (values
('javascript','async-javascript','javascript-async-javascript-101','How do you create a Promise manually using the Promise constructor?','You pass an executor function to new Promise((resolve, reject) => {...}); call resolve(value) when the async operation succeeds, or reject(error) when it fails. The executor runs synchronously and immediately, but resolve/reject are typically called later, once some asynchronous work (like a timer or I/O callback) completes.',null,'const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
await wait(1000);','javascript','easy',ARRAY['javascript','async']::text[],true,101),
('javascript','async-javascript','javascript-async-javascript-102','What''s a common pitfall when chaining multiple .then() calls?','Forgetting to return a value (or a promise) from inside a .then() callback silently breaks the chain — subsequent .then() calls receive undefined instead of the expected data, since each .then() implicitly wraps whatever its callback returns in a resolved promise. Another common pitfall is nesting .then() calls instead of chaining them flatly, which recreates the callback-hell problem promises were meant to solve.',null,null,null,'medium',ARRAY['javascript','async','promises']::text[],false,102),
('javascript','async-javascript','javascript-async-javascript-103','Should you use try/catch or .catch() to handle errors in an async function?','Both work, but they suit different situations: try/catch around await calls handles errors the same way as synchronous code and is usually more readable for sequential logic. .catch() attached directly to a promise chain is useful when you want to handle errors for a specific async call without wrapping the whole function, or when working outside an async function entirely.',null,'async function load() {
  try {
    const data = await fetchData();
  } catch (err) {
    console.error(''failed'', err);
  }
}','javascript','medium',ARRAY['javascript','async','error-handling']::text[],true,103),
('javascript','async-javascript','javascript-async-javascript-104','What does Promise.any() do, and how does it differ from Promise.race()?','Promise.any() resolves as soon as any one of the input promises fulfills, and only rejects if all of them reject (with an AggregateError containing all the individual errors). Promise.race() settles on whichever promise finishes first, whether it fulfills or rejects — so race can reject even if a later promise would have succeeded, while any() specifically waits for a success.',null,null,null,'hard',ARRAY['javascript','async','promises']::text[],false,104),
('javascript','async-javascript','javascript-async-javascript-105','What is ''promisifying'' a callback-based function, and how would you do it manually?','Promisifying wraps an older Node-style callback API (fn(args, (err, result) => {...})) in a function that returns a Promise instead, so it can be used with async/await. You wrap the call in new Promise((resolve, reject) => {...}), calling reject(err) if the callback receives an error and resolve(result) otherwise.',null,'function promisify(fn) {
  return (...args) => new Promise((resolve, reject) => {
    fn(...args, (err, result) => err ? reject(err) : resolve(result));
  });
}','javascript','medium',ARRAY['javascript','async','node']::text[],false,105),
('javascript','async-javascript','javascript-async-javascript-106','What does for await...of do, and when do you need it instead of a regular for...of?','for await...of iterates over an async iterable (an object whose Symbol.asyncIterator returns items wrapped in promises), automatically awaiting each yielded value before the loop body runs. It''s needed when iterating over something like a paginated API, a readable stream, or an async generator, where each ''next'' value itself takes time to produce.',null,null,null,'hard',ARRAY['javascript','async','iterators']::text[],false,106),
('javascript','async-javascript','javascript-async-javascript-107','How were generators used to manage asynchronous flow before async/await existed?','Generator functions (function*) can pause execution at a yield and be resumed later, so libraries like co wrapped a generator in a driver function that would yield a promise, wait for it to resolve, then resume the generator with the resolved value — effectively hand-rolling what async/await now does natively. async/await is often described as syntactic sugar over this exact generator-plus-promise-driver pattern.',null,null,null,'hard',ARRAY['javascript','async','generators']::text[],false,107),
('javascript','async-javascript','javascript-async-javascript-108','What is the practical difference between setTimeout and setInterval?','setTimeout schedules a callback to run once after a delay. setInterval schedules a callback to run repeatedly every given interval until explicitly stopped with clearInterval — but if the callback itself takes longer than the interval, calls can queue up or overlap in confusing ways, which is why a self-rescheduling setTimeout is often preferred for reliable repeated polling.',null,null,null,'easy',ARRAY['javascript','async','timers']::text[],false,108),
('javascript','async-javascript','javascript-async-javascript-109','What does queueMicrotask() do?','queueMicrotask() schedules a callback to run in the microtask queue, the same queue used for resolved Promise .then() callbacks — meaning it runs after the current synchronous code finishes but before the next macrotask (like a setTimeout callback or UI render). It''s useful when you want promise-like ''run soon but not synchronously'' timing without actually creating a Promise object.',null,'queueMicrotask(() => console.log(''microtask''));
console.log(''sync''); // logs: sync, then microtask','javascript','medium',ARRAY['javascript','async','event-loop']::text[],false,109),
('javascript','async-javascript','javascript-async-javascript-110','What causes a race condition in async JavaScript code, and how can you guard against one?','A race condition occurs when multiple async operations that read/write shared state can complete in an unpredictable order, causing the final result to depend on timing rather than logic — a classic example is a search input firing multiple requests where an older, slower response overwrites a newer one. Guards include ignoring stale responses (tracking a request ID/token and discarding out-of-order results) or cancelling the previous request before starting a new one.',null,null,null,'hard',ARRAY['javascript','async']::text[],true,110),
('javascript','async-javascript','javascript-async-javascript-111','How do you cancel an in-flight fetch request?','Create an AbortController, pass its .signal to fetch''s options, and call controller.abort() to cancel the request — fetch then rejects with an AbortError. This is commonly used to cancel a previous request when a new one starts (e.g. in a search-as-you-type feature) to avoid race conditions and wasted bandwidth.',null,'const controller = new AbortController();
fetch(url, { signal: controller.signal });
controller.abort(); // cancels the request','javascript','medium',ARRAY['javascript','async','fetch']::text[],false,111),
('javascript','async-javascript','javascript-async-javascript-112','What''s the difference between running two async operations sequentially vs in parallel?','Sequential execution (await a(); await b();) waits for each to finish before starting the next, so total time is the sum of both — necessary when b depends on a''s result. Parallel execution (await Promise.all([a(), b()]), or starting both calls before awaiting either) runs them concurrently, so total time is roughly the slower of the two — appropriate when the operations are independent.',null,'// Sequential: slower
const a = await fetchA(); const b = await fetchB();
// Parallel: faster
const [a2, b2] = await Promise.all([fetchA(), fetchB()]);','javascript','medium',ARRAY['javascript','async']::text[],true,112),
('javascript','async-javascript','javascript-async-javascript-113','What does an async function actually return if you don''t write an explicit return statement?','An async function always returns a Promise, even without an explicit return — if there''s no return statement, it implicitly returns a Promise that resolves to undefined once the function body finishes executing. If you return a plain value, it''s automatically wrapped in a resolved Promise; if you return a promise, the outer promise adopts its state.',null,null,null,'easy',ARRAY['javascript','async']::text[],false,113),
('javascript','async-javascript','javascript-async-javascript-114','What is an ''unhandled promise rejection'' and why is it a problem?','It occurs when a Promise rejects but no .catch() handler (or try/catch around an await) is attached to observe the rejection, meaning the error is silently swallowed instead of surfacing. In Node.js this can even crash the process depending on version/configuration, and in browsers it logs a console warning — either way it usually indicates a missing error-handling path in the code.',null,null,null,'medium',ARRAY['javascript','async','error-handling']::text[],false,114),
('javascript','async-javascript','javascript-async-javascript-115','How does an error thrown deep inside an await chain propagate to the caller?','If any awaited call inside an async function throws (or its promise rejects), that rejection propagates up and effectively ''throws'' at the await point, which can be caught by a surrounding try/catch in that same function. If uncaught locally, the async function''s own returned promise rejects, and the error continues propagating to whatever calls that function and awaits (or catches) it.',null,null,null,'medium',ARRAY['javascript','async','error-handling']::text[],false,115),
('javascript','async-javascript','javascript-async-javascript-116','How would you limit the number of concurrent async requests running at once?','A common pattern is a simple concurrency-limited queue: maintain a counter of in-flight requests, and only start a new one from a work queue when the counter is below a max limit, decrementing and pulling the next item when one finishes. Libraries like p-limit implement this, but it can be hand-rolled with a loop of workers each pulling from a shared queue.',null,null,null,'medium',ARRAY['javascript','async','performance']::text[],false,116),
('javascript','async-javascript','javascript-async-javascript-117','How would you implement retry logic with exponential backoff for a flaky async call?','Wrap the call in a loop (or recursive function) that catches failures, and on each retry waits progressively longer (e.g. doubling the delay each time, often with some random jitter added) before trying again, up to a maximum number of attempts. This avoids hammering a struggling service with immediate retries while still recovering automatically from transient failures.',null,'async function retry(fn, attempts = 3, delay = 500) {
  for (let i = 0; i < attempts; i++) {
    try { return await fn(); }
    catch (err) { if (i === attempts - 1) throw err; await new Promise(r => setTimeout(r, delay * 2 ** i)); }
  }
}','javascript','hard',ARRAY['javascript','async','resilience']::text[],false,117),
('javascript','async-javascript','javascript-async-javascript-118','What do Promise.resolve() and Promise.reject() do?','Promise.resolve(value) returns a Promise that''s already fulfilled with the given value (or, if given a thenable/promise, adopts its eventual state). Promise.reject(error) returns a Promise that''s already rejected with the given error. They''re useful for normalizing a value into a Promise or short-circuiting a chain with an immediate outcome.',null,'Promise.resolve(42).then(v => console.log(v)); // 42
Promise.reject(''oops'').catch(e => console.log(e)); // oops','javascript','easy',ARRAY['javascript','async','promises']::text[],false,118),
('javascript','async-javascript','javascript-async-javascript-119','What does it mean to ''compose'' async functions, and how would you do it?','Composing async functions means chaining several async steps together so the output of one feeds into the next, typically written as a sequence of awaited calls inside a single async function, or via a reduce over an array of async functions that each await the previous result. It keeps multi-step async pipelines (validate, then transform, then save) readable as straight-line code instead of nested callbacks.',null,null,null,'medium',ARRAY['javascript','async']::text[],false,119),
('javascript','async-javascript','javascript-async-javascript-120','What''s the difference between blocking and non-blocking I/O, and where does JavaScript fit?','Blocking I/O halts the entire thread until an operation (like a file read or network call) completes, wasting time waiting. Non-blocking I/O lets the thread continue doing other work while the operation happens in the background, invoking a callback (or resolving a promise) when it''s done. JavaScript''s single-threaded runtime relies heavily on non-blocking I/O, via the event loop, to stay responsive despite having only one thread of execution.',null,null,null,'medium',ARRAY['javascript','async','event-loop']::text[],false,120),
('javascript','async-javascript','javascript-async-javascript-121','How do timers interact with the event loop''s phases?','A timer callback (from setTimeout/setInterval) isn''t guaranteed to run at exactly its specified delay — it''s only guaranteed to run no earlier than that delay, since it must wait for the call stack to be empty and for its turn in the timer phase of the event loop. If synchronous code or other queued work is still executing, a timer''s callback can fire noticeably later than requested.',null,null,null,'medium',ARRAY['javascript','async','event-loop']::text[],false,121),
('javascript','async-javascript','javascript-async-javascript-122','Why is requestAnimationFrame preferred over setTimeout for animations?','requestAnimationFrame schedules a callback to run right before the browser''s next repaint, syncing your updates with the display''s actual refresh rate (typically 60fps) and automatically pausing when the tab is inactive to save resources. setTimeout has no awareness of the rendering pipeline, so animations driven by it can appear janky or keep running (wasting battery) in a backgrounded tab.',null,null,null,'medium',ARRAY['javascript','async','performance']::text[],false,122),
('javascript','async-javascript','javascript-async-javascript-123','What problem do Web Workers solve, and what are their limitations?','Web Workers run JavaScript on a separate background thread, letting you offload CPU-intensive work (like heavy computation or data processing) without blocking the main thread and freezing the UI. Their main limitation is that they don''t share memory with the main thread — communication happens via message passing (postMessage), and they can''t directly access the DOM.',null,null,null,'hard',ARRAY['javascript','async','performance']::text[],false,123),
('javascript','async-javascript','javascript-async-javascript-124','Why doesn''t array.forEach(async (item) => { await doSomething(item); }) wait for all the async work to finish?','forEach doesn''t know or care what its callback returns — it calls the callback for each item and moves on immediately, ignoring the Promise each async callback returns. This means code after the forEach call runs before any of the async operations actually complete, which is a very common source of bugs; using a for...of loop with await, or Promise.all with map, are the correct alternatives.',null,'// Wrong: doesn''t wait
items.forEach(async (item) => await save(item));
// Correct: waits for all
await Promise.all(items.map(item => save(item)));','javascript','medium',ARRAY['javascript','async']::text[],true,124),
('javascript','async-javascript','javascript-async-javascript-125','When would you prefer explicit .then() chaining over async/await?','then() chaining can be more natural for simple, single-step transformations of a promise''s result, or in contexts that can''t be async functions. For anything with sequential logic, conditionals, or loops, async/await is almost always more readable since it lets asynchronous code be structured like ordinary synchronous code.',null,null,null,'easy',ARRAY['javascript','async']::text[],false,125),
('javascript','async-javascript','javascript-async-javascript-126','How can async code create a deadlock-like situation, even though JS is single-threaded?','It happens when two async operations end up waiting on each other in a cycle — for example, two mutually-dependent promises where each awaits a resolution that depends on the other completing first, or a lock/mutex-style pattern used to serialize access to a shared resource where a lock is acquired but never released due to an unhandled error path. It''s less common than true multi-threaded deadlocks but can still hang a specific async flow indefinitely.',null,null,null,'medium',ARRAY['javascript','async']::text[],false,126),
('javascript','async-javascript','javascript-async-javascript-127','Conceptually, how does streaming a response differ from awaiting the whole response at once?','Streaming processes data in chunks as they arrive (e.g. via a ReadableStream reader or an async iterator over response.body), letting you start working with the beginning of a large payload before the rest has finished downloading. Awaiting the whole response (like response.json()) buffers everything into memory first and only resolves once the entire payload has arrived, which is simpler but less memory-efficient for large responses.',null,null,null,'medium',ARRAY['javascript','async','streams']::text[],false,127),
('javascript','async-javascript','javascript-async-javascript-128','How would you implement a debounced async search that avoids showing stale results?','Debounce the trigger (wait for a pause in typing before firing the request) to avoid firing a request per keystroke, and separately guard against out-of-order responses — e.g. by tagging each request with an incrementing ID and only applying the response if its ID matches the latest request, or by aborting the previous request with AbortController before starting a new one.',null,'let latestId = 0;
async function search(query) {
  const id = ++latestId;
  const results = await fetchResults(query);
  if (id === latestId) render(results);
}','javascript','hard',ARRAY['javascript','async','performance']::text[],false,128),
('javascript','async-javascript','javascript-async-javascript-129','What is an async generator function and when would you use one?','An async generator (async function*) combines generators and promises — each yielded value can itself be awaited, and it''s consumed with for await...of. It''s useful for representing a sequence of asynchronously-produced values, like paginated API results fetched page by page on demand, without loading everything into memory up front.',null,'async function* fetchPages(url) {
  let next = url;
  while (next) {
    const res = await fetch(next).then(r => r.json());
    yield res.items;
    next = res.nextPageUrl;
  }
}','javascript','hard',ARRAY['javascript','async','generators']::text[],false,129),
('javascript','async-javascript','javascript-async-javascript-130','What is the fundamental difference between synchronous and asynchronous code execution in JavaScript?','Synchronous code executes immediately, line by line, blocking further execution until each statement completes. Asynchronous code initiates an operation (like a timer, network request, or file read) and continues executing subsequent code immediately, with the result of the async operation delivered later via a callback, promise, or await, without blocking the single JS thread in the meantime.',null,null,null,'easy',ARRAY['javascript','async']::text[],false,130),
('javascript','async-javascript','javascript-async-javascript-131','What happens if you await a value that isn''t a Promise?','await works on any value, not just promises — if the value isn''t a thenable, it''s simply wrapped in an already-resolved Promise and immediately returns that value on the next microtask tick. This means you can safely await a plain number, string, or object without an error; it just adds a tiny amount of asynchronous scheduling.',null,'async function f() {
  const x = await 5; // works fine, x === 5
}','javascript','easy',ARRAY['javascript','async']::text[],false,131),
('javascript','async-javascript','javascript-async-javascript-132','What are the three states of a Promise, and why can it only transition between them once?','A Promise is pending initially, then settles exactly once into either fulfilled (with a value) or rejected (with a reason) — once settled, its state and value are permanently locked and further calls to resolve/reject are no-ops. This ''settle once'' guarantee is what makes promises reliable to consume: any .then()/.catch() attached, even after settlement, always fires with the same, immutable outcome.',null,null,null,'medium',ARRAY['javascript','async','promises']::text[],false,132),
('javascript','async-javascript','javascript-async-javascript-133','What happens if a .then() callback returns another Promise instead of a plain value?','The chain automatically ''flattens'' — instead of resolving with a nested promise-within-a-promise, the outer chain waits for the returned inner promise to settle and adopts its eventual value or rejection. This auto-flattening is what makes sequential async operations chainable without ending up with deeply nested promise structures.',null,null,null,'medium',ARRAY['javascript','async','promises']::text[],false,133),
('javascript','async-javascript','javascript-async-javascript-134','Why does an async function''s promise resolve to undefined if it has no return statement, rather than never resolving?','Reaching the end of the function body (falling off the end) is treated exactly like an implicit return undefined; in regular JavaScript functions, and async functions inherit that behavior — completing execution, even without an explicit return, is what triggers the returned promise to fulfill, just with an undefined value rather than leaving it perpetually pending.',null,null,null,'medium',ARRAY['javascript','async']::text[],false,134),
('javascript','async-javascript','javascript-async-javascript-135','How do you kick off several independent async operations without letting a slow one block the others?','Start all the operations first (without awaiting each individually), collecting their promises, and only then await them together — either with Promise.all if you need all results and want to fail fast on any rejection, or Promise.allSettled if you want every outcome regardless of individual failures. Awaiting each one immediately in sequence would needlessly serialize otherwise-independent work.',null,null,null,'medium',ARRAY['javascript','async']::text[],false,135),
('javascript','async-javascript','javascript-async-javascript-136','How does a finally block behave inside an async function with try/catch?','The finally block runs after the try (and catch, if triggered) completes, regardless of whether the awaited code succeeded, threw, or even if a return happened inside try/catch — making it ideal for cleanup logic, like closing a connection or hiding a loading spinner, that must run no matter the outcome.',null,'async function load() {
  showSpinner();
  try { return await fetchData(); }
  finally { hideSpinner(); }
}','javascript','easy',ARRAY['javascript','async','error-handling']::text[],false,136),
('javascript','async-javascript','javascript-async-javascript-137','How do you cancel a pending setTimeout before it fires?','setTimeout returns an identifier (a number in browsers, a Timeout object in Node), which you pass to clearTimeout() to cancel the scheduled callback before it runs. This is commonly used to reset a debounce timer or clean up a pending timer when a component unmounts.',null,'const id = setTimeout(doThing, 1000);
clearTimeout(id); // cancels it before it fires','javascript','easy',ARRAY['javascript','async','timers']::text[],false,137),
('javascript','async-javascript','javascript-async-javascript-138','At a high level, how does an Observable-based approach like RxJS differ from Promise-based async code?','A Promise represents a single future value and can only resolve once, while an Observable represents a stream of zero, one, or many values over time and can be cancelled (unsubscribed) mid-stream. Observables are better suited to ongoing event sources, like user input, WebSocket messages, or periodic polling, whereas Promises are a natural fit for one-off async operations like a single API call.',null,null,null,'hard',ARRAY['javascript','async','rxjs']::text[],false,138),
('javascript','async-javascript','javascript-async-javascript-139','How do Promises solve the ''callback hell'' problem that plagued earlier asynchronous JavaScript?','Callback hell arises from deeply nesting callbacks for sequential async steps, each one indented inside the previous, making code hard to read and error handling inconsistent since each callback needs its own error check. Promises let you chain steps flatly with .then(), and centralize error handling in a single .catch() at the end of the chain, later improved further by async/await which reads like fully synchronous code.',null,'// Callback hell:
getUser(id, (user) => {
  getPosts(user, (posts) => {
    render(posts);
  });
});
// With async/await:
const user = await getUser(id);
const posts = await getPosts(user);
render(posts);','javascript','easy',ARRAY['javascript','async']::text[],true,139),
('javascript','async-javascript','javascript-async-javascript-140','Why is items.forEach(async item => await process(item)) a common bug, compared to a regular for loop?','The async arrow callback passed to forEach returns a Promise per call, but forEach''s implementation completely discards each callback''s return value and never awaits anything — so it fires off all iterations near-instantly without waiting for any of them, and any code following the forEach call runs before the async work finishes or even before errors within it are observable. A plain for or for...of loop with await inside genuinely pauses the loop itself at each iteration.',null,null,null,'medium',ARRAY['javascript','async']::text[],false,140),
('javascript','async-javascript','javascript-async-javascript-141','How would you await results into named variables when using Promise.all?','Promise.all returns an array of results in the same order as the input array of promises, so you can destructure that array directly into named variables in one line, which reads more clearly than accessing results[0], results[1], etc.',null,'const [user, posts] = await Promise.all([fetchUser(id), fetchPosts(id)]);','javascript','easy',ARRAY['javascript','async','promises']::text[],false,141),
('javascript','async-javascript','javascript-async-javascript-142','How would you add a timeout to a Promise that might otherwise hang indefinitely?','Use Promise.race() between the real operation and a second promise that rejects after a fixed delay via setTimeout — whichever settles first ''wins'', so if the real operation is too slow, the timeout promise rejects first and the overall race rejects with a timeout error.',null,'function withTimeout(promise, ms) {
  const timeout = new Promise((_, reject) => setTimeout(() => reject(new Error(''timeout'')), ms));
  return Promise.race([promise, timeout]);
}','javascript','medium',ARRAY['javascript','async','promises']::text[],false,142),
('javascript','async-javascript','javascript-async-javascript-143','What is a ''thenable'' and why does it matter for how Promises interoperate?','A thenable is any object with a .then(onFulfilled, onRejected) method, regardless of whether it''s a native Promise — the Promise spec is designed to treat any thenable as promise-like, so awaiting or chaining onto a thenable from a different library or a custom implementation still works correctly. This duck-typed interoperability is why different Promise implementations, including ones written before native Promises existed, can be mixed and awaited seamlessly.',null,null,null,'hard',ARRAY['javascript','async','promises']::text[],false,143),
('javascript','async-javascript','javascript-async-javascript-144','How does the microtask queue interact with multiple chained .then() calls versus a single setTimeout?','All queued microtasks, including every pending .then() callback, run to completion before the event loop moves on to the next macrotask, so a long or deeply chained sequence of .then() callbacks will all execute before a setTimeout(fn, 0) callback fires, even though the setTimeout was scheduled first. This is a common source of confusion when reasoning about the exact order operations run in.',null,null,null,'hard',ARRAY['javascript','async','event-loop']::text[],false,144),
('javascript','async-javascript','javascript-async-javascript-145','What''s a subtle bug that can occur from forgetting to return a promise chain inside another async function?','If an async function starts a nested async operation but doesn''t return (or await) its promise, the outer function''s own promise can resolve before the inner operation finishes — meaning any code awaiting the outer function proceeds too early, as if the nested work were already done when it might still be in flight. This is often called an accidental ''fire and forget'' bug.',null,'async function bad() {
  doAsyncThing(); // missing await/return
}
async function good() {
  return doAsyncThing(); // or: await doAsyncThing();
}','javascript','medium',ARRAY['javascript','async']::text[],false,145),
('javascript','async-javascript','javascript-async-javascript-146','How would you test that an async function correctly rejects with a specific error?','In most test frameworks you either await the call inside a try/catch and assert inside the catch block, failing the test if no error was thrown, or use the framework''s dedicated helper for rejection assertions, like Jest''s await expect(fn()).rejects.toThrow(''message''), which awaits the promise and asserts on its rejection reason directly.',null,null,null,'medium',ARRAY['javascript','async','testing']::text[],false,146),
('javascript','async-javascript','javascript-async-javascript-147','What''s a common cause of memory leaks in async/event-driven JavaScript code?','Forgetting to clear timers (clearTimeout/clearInterval) or remove event listeners/subscriptions when they''re no longer needed, such as when a component unmounts, keeps callbacks — and everything they close over — alive indefinitely, since the runtime can''t garbage-collect anything still referenced by an active timer or listener. This is especially common in single-page apps where components mount and unmount repeatedly.',null,null,null,'medium',ARRAY['javascript','async','memory']::text[],false,147),
('javascript','async-javascript','javascript-async-javascript-148','Why can returning a rejected promise from inside a .then() success callback still be caught by a later .catch()?','A .catch() is really just .then(undefined, onRejected) attached further down the chain, and any rejection — whether it comes from the original promise or is produced partway through the chain by a thrown error or an explicitly returned rejected promise — propagates forward past any intermediate .then() calls that don''t have a matching rejection handler, until it reaches the first one that does.',null,null,null,'hard',ARRAY['javascript','async','promises']::text[],false,148),
('javascript','async-javascript','javascript-async-javascript-149','When multiple .then() handlers are attached to the same promise, in what order do they run?','They run in the order they were attached, once the promise settles — each is scheduled as a separate microtask, so if a promise resolves and three .then() callbacks are attached to it, all three run, each as its own microtask, before any subsequently-scheduled macrotask, in registration order relative to each other.',null,null,null,'hard',ARRAY['javascript','async','promises']::text[],false,149),
('javascript','async-javascript','javascript-async-javascript-150','What does ''microtask queue starvation'' mean, and how can it happen?','It''s a situation where microtasks keep scheduling more microtasks, such as a .then() callback that recursively queues another .then(), faster than the queue can drain, which starves the event loop of the chance to reach the next macrotask phase — meaning rendering, timers, and I/O callbacks can be indefinitely delayed since the spec requires the entire microtask queue to empty before moving on. It''s a rare but real performance pitfall in recursive promise-based code.',null,null,null,'hard',ARRAY['javascript','async','event-loop']::text[],false,150),
('javascript','basics','javascript-basics-101','What is the difference between primitive and reference types in JavaScript?','Primitive types (string, number, boolean, null, undefined, symbol, bigint) are immutable and copied by value when assigned or passed to a function. Reference types (objects, arrays, functions) are copied by reference, so two variables can point to the same underlying object and mutations through one are visible through the other.',null,'let a = { x: 1 };
let b = a;
b.x = 2;
console.log(a.x); // 2, same object','javascript','easy',ARRAY['javascript','basics','types']::text[],true,101),
('javascript','basics','javascript-basics-102','What are truthy and falsy values in JavaScript?','A truthy value is any value that evaluates to true in a boolean context, and a falsy value evaluates to false. The only falsy values are false, 0, -0, 0n, "", null, undefined, and NaN — everything else, including empty objects and arrays, is truthy.',null,'if ([]) console.log(''arrays are truthy'');','javascript','easy',ARRAY['javascript','basics']::text[],true,102),
('javascript','basics','javascript-basics-103','Why does typeof NaN return "number"?','NaN (Not-a-Number) is technically a special numeric value defined by the IEEE 754 floating-point standard to represent an invalid or undefined arithmetic result, so JavaScript classifies it under the number type. It''s the only value in JavaScript that is not equal to itself, which is why Number.isNaN() exists to reliably detect it.',null,'typeof NaN === ''number''; // true','javascript','medium',ARRAY['javascript','basics','numbers']::text[],false,103),
('javascript','basics','javascript-basics-104','What is the difference between typeof and instanceof?','typeof returns a string describing the primitive type of a value (like "string", "number", "object", "function"), and is evaluated at the operand level without knowledge of the prototype chain. instanceof checks whether an object''s prototype chain contains a given constructor''s prototype, so it works for distinguishing between different object types like Array vs plain Object.',null,'[] instanceof Array; // true
typeof []; // ''object''','javascript','easy',ARRAY['javascript','basics']::text[],false,104),
('javascript','basics','javascript-basics-105','What is type coercion in JavaScript?','Type coercion is JavaScript''s automatic (implicit) conversion of a value from one type to another when an operator or context expects a different type, such as converting a number to a string during string concatenation with +. It can also be done explicitly using functions like Number(), String(), or Boolean().',null,'1 + ''2'' === ''12''; // number coerced to string','javascript','easy',ARRAY['javascript','basics','coercion']::text[],true,105),
('javascript','basics','javascript-basics-106','Why does 0.1 + 0.2 not equal 0.3 in JavaScript?','JavaScript stores numbers as IEEE 754 double-precision floating-point values, which cannot represent most decimal fractions exactly in binary. The tiny rounding error means 0.1 + 0.2 evaluates to 0.30000000000000004, so comparisons involving decimals should use a small tolerance (epsilon) instead of strict equality.',null,'Math.abs(0.1 + 0.2 - 0.3) < Number.EPSILON;','javascript','medium',ARRAY['javascript','basics','numbers']::text[],false,106),
('javascript','basics','javascript-basics-107','What is an IIFE (Immediately Invoked Function Expression)?','An IIFE is a function that is defined and executed immediately after its creation, typically wrapped in parentheses to force it to be parsed as an expression rather than a declaration. It was historically used to create a private scope and avoid polluting the global namespace before ES6 modules and block scoping existed.',null,'(function () {
  console.log(''runs immediately'');
})();','javascript','easy',ARRAY['javascript','basics','functions']::text[],false,107),
('javascript','basics','javascript-basics-108','What does "use strict" do in JavaScript?','"use strict" enables strict mode, which catches common coding mistakes by throwing errors instead of silently failing — for example, assigning to an undeclared variable, duplicating parameter names, or using reserved words as identifiers. It also disables some confusing features like the `with` statement and changes `this` to be undefined in plain function calls instead of the global object.',null,null,null,'medium',ARRAY['javascript','basics']::text[],false,108),
('javascript','basics','javascript-basics-109','What is the global object in JavaScript, and how do you access it?','The global object holds global variables and functions available everywhere in a JavaScript environment; in browsers it''s `window`, in Node.js it''s `global`. The `globalThis` keyword, introduced in ES2020, provides a standard way to access the global object regardless of the environment.',null,null,null,'easy',ARRAY['javascript','basics']::text[],false,109),
('javascript','basics','javascript-basics-110','What are Symbols in JavaScript and what are they used for?','A Symbol is a primitive type introduced in ES6 that creates a unique and immutable value, often used as a property key to avoid naming collisions with other properties, including ones added by other libraries. Symbols are not enumerable in for...in loops and are commonly used to implement well-known protocol hooks like Symbol.iterator.',null,'const id = Symbol(''id'');
const obj = { [id]: 123 };','javascript','medium',ARRAY['javascript','basics','es6']::text[],false,110),
('javascript','basics','javascript-basics-111','What is BigInt and when would you use it?','BigInt is a primitive type that can represent integers with arbitrary precision, beyond the safe integer limit of Number (2^53 - 1). It''s created by appending `n` to an integer literal or calling BigInt(), and is used when working with very large numbers such as cryptographic calculations or high-precision IDs.',null,'const big = 9007199254740993n;','javascript','medium',ARRAY['javascript','basics','numbers']::text[],false,111),
('javascript','basics','javascript-basics-112','What is the difference between JSON.parse and JSON.stringify?','JSON.stringify() converts a JavaScript value (object, array, primitive) into a JSON-formatted string, useful for sending data over the network or storing it. JSON.parse() does the reverse, converting a JSON string back into a JavaScript value — both throw errors on malformed input.',null,'const str = JSON.stringify({ a: 1 }); // ''{"a":1}''
const obj = JSON.parse(str); // { a: 1 }','javascript','easy',ARRAY['javascript','basics','json']::text[],true,112),
('javascript','basics','javascript-basics-113','Why is NaN !== NaN in JavaScript, and how do you check for it correctly?','Per the IEEE 754 standard, NaN is defined to never equal any value, including itself, since it represents an undefined or unrepresentable numeric result. To reliably check for NaN, use Number.isNaN(value), which — unlike the global isNaN() — does not coerce its argument first.',null,'NaN === NaN; // false
Number.isNaN(NaN); // true','javascript','medium',ARRAY['javascript','basics','numbers']::text[],false,113),
('javascript','basics','javascript-basics-114','What is the difference between block scope, function scope, and global scope?','Global scope is accessible everywhere in the program. Function scope means a variable is accessible anywhere within the function it was declared in, regardless of nested blocks (this is how `var` behaves). Block scope, used by `let` and `const`, restricts a variable''s visibility to the nearest enclosing pair of curly braces, such as an if block or loop.',null,null,null,'easy',ARRAY['javascript','basics','scope']::text[],false,114),
('javascript','basics','javascript-basics-115','What does the void operator do in JavaScript?','The void operator evaluates an expression and always returns undefined, discarding the expression''s result. It''s rarely needed in modern code but historically appeared in `javascript:void(0)` links to prevent page navigation while still executing the expression''s side effects.',null,'void 0; // undefined','javascript','hard',ARRAY['javascript','basics']::text[],false,115),
('javascript','basics','javascript-basics-116','What are labeled statements in JavaScript and when are they useful?','A labeled statement attaches an identifier to a loop or block so that `break` or `continue` can target that specific outer loop instead of just the innermost one. They''re rarely used in modern code because they can hurt readability, but they''re the standard way to break out of nested loops directly.',null,'outer: for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (j === 1) continue outer;
    console.log(i, j);
  }
}','javascript','hard',ARRAY['javascript','basics','loops']::text[],false,116),
('javascript','basics','javascript-basics-117','What does the comma operator do in JavaScript?','The comma operator evaluates each of its operands from left to right and returns the value of the last operand, discarding the results of the others. It''s most commonly seen in the update clause of a for loop where you need to perform multiple operations, such as `for (let i = 0, j = 10; i < j; i++, j--)`.',null,'const x = (1, 2, 3); // x is 3','javascript','hard',ARRAY['javascript','basics']::text[],false,117),
('javascript','basics','javascript-basics-118','What is Automatic Semicolon Insertion (ASI) and what problems can it cause?','ASI is a JavaScript engine mechanism that automatically inserts semicolons at the end of statements when they''re omitted, based on specific parsing rules. It can cause subtle bugs, most famously when a `return` statement is followed by a newline before the returned value — ASI inserts a semicolon right after `return`, causing the function to return undefined instead of the intended value.',null,'function getValue() {
  return
  {
    value: 1
  };
}
// returns undefined, not the object, due to ASI','javascript','hard',ARRAY['javascript','basics']::text[],true,118),
('javascript','basics','javascript-basics-119','What is short-circuit evaluation in JavaScript?','Short-circuit evaluation means logical operators && and || stop evaluating as soon as the result is determined: && returns the first falsy operand (or the last if all are truthy), and || returns the first truthy operand (or the last if all are falsy). This is commonly used to provide default values or to conditionally call a function.',null,'const name = user.name || ''Guest'';','javascript','easy',ARRAY['javascript','basics','operators']::text[],false,119),
('javascript','basics','javascript-basics-120','What is the difference between the nullish coalescing operator (??) and the logical OR operator (||)?','|| returns the right-hand operand if the left is any falsy value (0, '''', false, null, undefined, NaN), while ?? only falls back to the right-hand operand if the left is specifically null or undefined. This matters when 0 or an empty string are valid values you don''t want overridden.',null,'0 || ''default''; // ''default''
0 ?? ''default''; // 0','javascript','medium',ARRAY['javascript','basics','es6']::text[],true,120),
('javascript','basics','javascript-basics-121','What is optional chaining (?.) and what problem does it solve?','Optional chaining lets you safely access deeply nested object properties without manually checking each level for null or undefined — if any part of the chain is nullish, the whole expression short-circuits and returns undefined instead of throwing a TypeError.',null,'const city = user?.address?.city;','javascript','easy',ARRAY['javascript','basics','es6']::text[],false,121),
('javascript','basics','javascript-basics-122','What are tagged template literals?','A tagged template literal is a template string preceded by a function (the tag) that processes the string and its interpolated values before producing the final result, instead of the default string interpolation. The tag function receives the literal string parts as an array and the interpolated expressions as separate arguments, enabling custom formatting, sanitization, or i18n logic.',null,'function upper(strings, ...values) {
  return strings.reduce((acc, s, i) => acc + s + (values[i]?.toUpperCase() ?? ''''), '''');
}
upper`Hello ${''world''}`; // ''Hello WORLD''','javascript','hard',ARRAY['javascript','basics','es6']::text[],false,122),
('javascript','basics','javascript-basics-123','What is the difference between the in operator and hasOwnProperty()?','The `in` operator checks whether a property exists anywhere in an object''s own properties or its prototype chain. `hasOwnProperty()` checks only the object''s own properties, ignoring anything inherited from the prototype, which makes it more precise when you want to avoid false positives from inherited properties.',null,'''toString'' in {}; // true (inherited)
({}).hasOwnProperty(''toString''); // false','javascript','medium',ARRAY['javascript','basics','objects']::text[],false,123),
('javascript','basics','javascript-basics-124','What is the difference between an array-like object and an iterable in JavaScript?','An array-like object has a numeric `length` property and indexed elements (like `arguments` or a NodeList) but doesn''t have array methods like map or forEach unless converted. An iterable implements the Symbol.iterator protocol, allowing it to be used with for...of loops and the spread operator — arrays and strings are both iterable.',null,'Array.from(document.querySelectorAll(''div'')); // array-like to real array','javascript','hard',ARRAY['javascript','basics','arrays']::text[],false,124),
('javascript','basics','javascript-basics-125','How do you explicitly convert values between types in JavaScript?','Use Number(value) to convert to a number, String(value) to convert to a string, and Boolean(value) to convert to a boolean, all of which follow well-defined coercion rules. These are generally preferred over implicit coercion (like using + '''' to convert to a string) because the intent is clearer to readers.',null,'Number(''42''); // 42
String(42); // ''42''
Boolean(''''); // false','javascript','easy',ARRAY['javascript','basics','coercion']::text[],false,125),
('javascript','basics','javascript-basics-126','What is the difference between for...in and for...of loops?','for...in iterates over the enumerable property keys of an object, including inherited ones, and is typically used with plain objects. for...of iterates over the values of an iterable (arrays, strings, Maps, Sets), making it the preferred choice for looping over array elements directly.',null,'for (const key in {a:1}) {} // ''a''
for (const val of [1,2]) {} // 1, 2','javascript','easy',ARRAY['javascript','basics','loops']::text[],true,126),
('javascript','basics','javascript-basics-127','What are some common quirks of the switch statement in JavaScript?','switch uses strict equality (===) to compare the expression against each case, so type coercion never happens. Cases without a `break` statement will "fall through" and execute the next case''s code too, which is a common source of bugs, and a `default` case can be placed anywhere, not just at the end.',null,'switch (1) {
  case 1:
  case 2:
    console.log(''one or two'');
    break;
  default:
    console.log(''other'');
}','javascript','medium',ARRAY['javascript','basics']::text[],false,127),
('javascript','basics','javascript-basics-128','How does the ternary (conditional) operator work in JavaScript?','The ternary operator `condition ? valueIfTrue : valueIfFalse` is a compact, single-expression alternative to an if/else statement, and is the only operator in JavaScript that takes three operands. It''s commonly used for concise conditional assignment but should be avoided for complex nested logic since it hurts readability.',null,'const status = age >= 18 ? ''adult'' : ''minor'';','javascript','easy',ARRAY['javascript','basics','operators']::text[],false,128),
('javascript','basics','javascript-basics-129','What is the difference between Object.is() and the strict equality operator (===)?','Object.is() behaves like === for almost all values, but differs in two edge cases: Object.is(NaN, NaN) returns true (=== returns false), and Object.is(0, -0) returns false while 0 === -0 returns true. It''s mainly used internally by React and other libraries for precise value comparison.',null,'Object.is(NaN, NaN); // true
NaN === NaN; // false','javascript','hard',ARRAY['javascript','basics']::text[],false,129),
('javascript','basics','javascript-basics-130','Why is string immutability important in JavaScript?','Strings in JavaScript are immutable — methods like toUpperCase() or slice() always return a new string rather than modifying the original. This makes strings safe to share across different parts of a program without unexpected side effects, though it means repeated concatenation in a loop can be less efficient than using an array and join().',null,'let s = ''hi'';
s[0] = ''H''; // silently fails, s is still ''hi''','javascript','medium',ARRAY['javascript','basics','strings']::text[],false,130),
('javascript','basics','javascript-basics-131','How do you reliably check if a value is an array?','Array.isArray(value) is the reliable way to check if a value is an array, because typeof returns ''object'' for arrays just like plain objects. Array.isArray() correctly distinguishes arrays even across different execution contexts (like iframes), unlike an instanceof Array check.',null,'Array.isArray([1,2,3]); // true
typeof [1,2,3]; // ''object''','javascript','easy',ARRAY['javascript','basics','arrays']::text[],false,131),
('javascript','basics','javascript-basics-132','What is the difference between undeclared, undefined, and uninitialized variables?','An undeclared variable was never declared with var/let/const and referencing it throws a ReferenceError (or creates an implicit global in non-strict mode). A declared-but-unassigned variable holds the value undefined. A let/const variable that has been declared but not yet reached in execution order is ''uninitialized'' and sits in the temporal dead zone, throwing a ReferenceError if accessed.',null,null,null,'hard',ARRAY['javascript','basics','scope']::text[],false,132),
('javascript','basics','javascript-basics-133','What is the difference between mutable and immutable operations on arrays?','Mutable array methods like push, pop, splice, and sort modify the original array in place. Immutable operations like map, filter, concat, and the spread operator return a new array, leaving the original untouched — this distinction matters a lot in frameworks like React that rely on reference changes to detect updates.',null,'const sorted = [...arr].sort(); // doesn''t mutate arr','javascript','medium',ARRAY['javascript','basics','arrays']::text[],false,133),
('javascript','basics','javascript-basics-134','What is an accessor property versus a data property in a JavaScript object?','A data property simply stores a value directly. An accessor property is defined with get and/or set functions that compute a value on read or intercept an assignment on write, rather than storing the value directly — both are configured via Object.defineProperty() or object literal getter/setter syntax.',null,null,null,'hard',ARRAY['javascript','basics','objects']::text[],false,134),
('javascript','basics','javascript-basics-135','What is the difference between synchronous and asynchronous code execution in JavaScript at a basic level?','Synchronous code runs line by line, blocking further execution until the current operation completes. Asynchronous code (like setTimeout, fetch, or promises) is scheduled to run later without blocking the main thread, allowing the program to continue executing other code while waiting for the operation to finish.',null,null,null,'easy',ARRAY['javascript','basics','async']::text[],false,135),
('javascript','basics','javascript-basics-136','What does Number.isInteger() check, and how does it differ from Number.isSafeInteger()?','Number.isInteger() returns true if a value is a number with no fractional component, such as 5 or 5.0. Number.isSafeInteger() additionally checks that the value falls within the safe integer range (±(2^53 - 1)) where integers can be represented exactly without precision loss.',null,'Number.isInteger(5.0); // true
Number.isSafeInteger(2 ** 53); // false','javascript','medium',ARRAY['javascript','basics','numbers']::text[],false,136),
('javascript','basics','javascript-basics-137','What is the difference between == null and === null for checking null or undefined?','Because == performs type coercion and null == undefined evaluates to true (while null and undefined are not loosely equal to anything else), `value == null` is a common, concise idiom to check for both null and undefined at once. `value === null` only matches null exactly, requiring a separate check for undefined.',null,'null == undefined; // true
null === undefined; // false','javascript','medium',ARRAY['javascript','basics','operators']::text[],false,137),
('javascript','basics','javascript-basics-138','What is the difference between a shallow and a deep freeze of an object?','Object.freeze() only freezes the top-level properties of an object — nested objects remain mutable. A deep freeze recursively calls Object.freeze() on every nested object as well, which requires a custom recursive helper function since JavaScript has no built-in deepFreeze.',null,'function deepFreeze(obj) {
  Object.values(obj).forEach((v) => typeof v === ''object'' && v && deepFreeze(v));
  return Object.freeze(obj);
}','javascript','hard',ARRAY['javascript','basics','objects']::text[],false,138),
('javascript','basics','javascript-basics-139','What is the difference between Number.parseFloat and Number.parseInt?','parseInt parses a string and returns an integer, stopping at the first non-numeric character, and accepts an optional radix argument (base 2-36). parseFloat parses and returns a floating-point number, including decimal points, but doesn''t support a radix argument.',null,'parseInt(''3.14'', 10); // 3
parseFloat(''3.14''); // 3.14','javascript','easy',ARRAY['javascript','basics','numbers']::text[],false,139),
('javascript','basics','javascript-basics-140','Why should you always specify a radix when using parseInt?','Without an explicit radix, parseInt guesses the base from the string''s format, and historically strings starting with ''0'' were sometimes interpreted as octal in older engines, leading to unexpected results. Always passing 10 (or the intended base) avoids this ambiguity and makes the intent explicit.',null,'parseInt(''08''); // 8 in modern engines, but explicit radix avoids any doubt
parseInt(''08'', 10); // 8','javascript','medium',ARRAY['javascript','basics','numbers']::text[],false,140),
('javascript','basics','javascript-basics-141','What is the difference between a wrapper object and a primitive value in JavaScript?','Primitives like strings and numbers aren''t objects and have no methods of their own, but JavaScript automatically wraps them in a temporary wrapper object (like String or Number) whenever you call a method on them, such as ''hello''.toUpperCase(). The wrapper object is discarded immediately after the method call completes.',null,'typeof ''hi''; // ''string''
typeof new String(''hi''); // ''object''','javascript','hard',ARRAY['javascript','basics','types']::text[],false,141),
('javascript','basics','javascript-basics-142','What is the difference between let redeclaration errors and var redeclaration behavior?','Declaring the same variable name twice with var in the same scope is allowed and simply overwrites the previous binding without error. Doing the same with let or const throws a SyntaxError ("already declared"), because block-scoped declarations are stricter about preventing accidental redeclaration.',null,'var x = 1; var x = 2; // fine
let y = 1; let y = 2; // SyntaxError','javascript','medium',ARRAY['javascript','basics','scope']::text[],false,142),
('javascript','basics','javascript-basics-143','What is the difference between deep equality and reference equality for objects?','Reference equality (===) checks whether two variables point to the exact same object in memory. Deep equality checks whether two objects have the same structure and values, even if they are different objects — JavaScript has no built-in deep equality operator, so it requires a recursive comparison function or a library like lodash''s isEqual.',null,'{ a: 1 } === { a: 1 }; // false, different objects','javascript','medium',ARRAY['javascript','basics','objects']::text[],false,143),
('javascript','basics','javascript-basics-144','What is the with statement in JavaScript and why is it discouraged?','The with statement extends the scope chain for a block, letting you reference an object''s properties without prefixing them, but it makes code ambiguous and hard to optimize since the engine can''t statically determine whether an identifier refers to a variable or an object property. It''s forbidden entirely in strict mode.',null,'with (Math) { console.log(PI); } // avoid this','javascript','hard',ARRAY['javascript','basics']::text[],false,144),
('javascript','basics','javascript-basics-145','What is the difference between Number.MAX_SAFE_INTEGER and Number.MAX_VALUE?','Number.MAX_SAFE_INTEGER (2^53 - 1) is the largest integer that can be represented exactly without losing precision. Number.MAX_VALUE is the largest finite number JavaScript can represent at all, but numbers beyond MAX_SAFE_INTEGER lose integer precision even though they''re still within MAX_VALUE.',null,null,null,'hard',ARRAY['javascript','basics','numbers']::text[],false,145),
('javascript','basics','javascript-basics-146','How does JavaScript determine equality when using the includes() method on an array versus indexOf()?','Array.prototype.includes() uses the SameValueZero algorithm, which treats NaN as equal to itself, so it can correctly find NaN in an array. Array.prototype.indexOf() uses strict equality (===), so it can never find NaN because NaN === NaN is false.',null,'[NaN].includes(NaN); // true
[NaN].indexOf(NaN); // -1','javascript','hard',ARRAY['javascript','basics','arrays']::text[],false,146),
('javascript','basics','javascript-basics-147','What is destructuring with default values in JavaScript?','When destructuring an object or array, you can provide a default value for a property that assigns only if the extracted value is strictly undefined (not just falsy), which is useful for handling optional function parameters or config objects.',null,'const { retries = 3 } = options;','javascript','easy',ARRAY['javascript','basics','es6']::text[],false,147),
('javascript','basics','javascript-basics-148','What is the difference between an expression and a statement in JavaScript?','An expression produces a value and can be used wherever a value is expected, such as `2 + 2` or a function call. A statement performs an action and does not itself produce a usable value, such as an if block or a for loop — though some constructs, like function expressions, blur this line depending on context.',null,null,null,'medium',ARRAY['javascript','basics']::text[],false,148),
('javascript','basics','javascript-basics-149','What is variable shadowing in JavaScript?','Variable shadowing occurs when a variable declared in an inner scope has the same name as a variable in an outer scope, temporarily ''hiding'' the outer variable for the duration of the inner scope. It''s legal with let/const in nested blocks but can make code confusing if used carelessly.',null,'let x = 1;
{
  let x = 2; // shadows outer x
  console.log(x); // 2
}
console.log(x); // 1','javascript','medium',ARRAY['javascript','basics','scope']::text[],false,149),
('javascript','dom','javascript-dom-101','What is the difference between querySelector/querySelectorAll and getElementById/getElementsByClassName?','`querySelector`/`querySelectorAll` accept any CSS selector and give you far more flexibility (attribute selectors, combinators, pseudo-classes), while `getElementById`/`getElementsByClassName` only match by a single id or class name. The older methods also return live collections (that auto-update as the DOM changes) for `getElementsByClassName`, whereas `querySelectorAll` returns a static NodeList snapshot.',null,'document.querySelectorAll(''.item:not(.disabled)'');
document.getElementById(''main'');','javascript','easy',ARRAY['javascript','dom']::text[],false,101),
('javascript','dom','javascript-dom-102','What is the difference between a DOM node and a DOM element?','A node is the general base type in the DOM tree, covering elements, text, comments, and the document itself. An element is specifically a tag-based node (like `<div>` or `<p>`) — every element is a node, but not every node is an element, which is why APIs like `childNodes` (all nodes) and `children` (elements only) behave differently.',null,null,null,'easy',ARRAY['javascript','dom']::text[],false,102),
('javascript','dom','javascript-dom-103','How do you create and insert a new element into the DOM?','`document.createElement(tagName)` creates a detached element, which you then configure (set attributes, text, children) before attaching it to the tree with a method like `appendChild()`, `append()`, or `insertBefore()`. Nothing is visible on the page until the element is actually attached to a node that''s part of the document.',null,'const li = document.createElement(''li'');
li.textContent = ''New item'';
document.querySelector(''ul'').appendChild(li);','javascript','easy',ARRAY['javascript','dom']::text[],false,103),
('javascript','dom','javascript-dom-104','What do insertBefore() and replaceChild() do?','`parent.insertBefore(newNode, referenceNode)` inserts `newNode` into `parent` immediately before `referenceNode` (or at the end if `referenceNode` is `null`). `parent.replaceChild(newNode, oldNode)` swaps `oldNode` out for `newNode` in a single operation, removing the old node from the tree in the process.',null,'list.insertBefore(newItem, list.firstChild);
list.replaceChild(newItem, oldItem);','javascript','easy',ARRAY['javascript','dom']::text[],false,104),
('javascript','dom','javascript-dom-105','What is the classList API used for?','`element.classList` exposes a DOMTokenList with methods like `add()`, `remove()`, `toggle()`, `replace()`, and `contains()` for manipulating an element''s CSS classes individually, without needing to parse or rebuild the whole `className` string manually. `toggle()` is especially handy for show/hide or active-state UI patterns.',null,'el.classList.toggle(''active'');
el.classList.contains(''active''); // true/false','javascript','easy',ARRAY['javascript','dom']::text[],false,105),
('javascript','dom','javascript-dom-106','What is the dataset API and when would you use it?','`element.dataset` exposes an element''s `data-*` HTML attributes as a plain object with camelCase keys — `data-user-id` becomes `dataset.userId`. It''s a clean, standards-based way to attach custom metadata to DOM elements without inventing your own attribute scheme or relying on non-standard attributes.','<div data-user-id="42"></div>','el.dataset.userId; // ''42''
el.dataset.userId = ''43'';','javascript','easy',ARRAY['javascript','dom']::text[],false,106),
('javascript','dom','javascript-dom-107','What is the difference between event.target and event.currentTarget?','`event.target` is the actual element that triggered the event (e.g. the specific button clicked), while `event.currentTarget` is the element the listener is currently attached to and executing on. They differ whenever an event bubbles — a listener on a parent `<ul>` sees `target` as the clicked `<li>` but `currentTarget` as the `<ul>` itself.',null,'list.addEventListener(''click'', (e) => {
  console.log(e.target);        // the clicked <li>
  console.log(e.currentTarget); // the <ul>
});','javascript','medium',ARRAY['javascript','dom','events']::text[],true,107),
('javascript','dom','javascript-dom-108','How do you create and dispatch a custom event?','`new CustomEvent(name, { detail, bubbles })` creates an event carrying arbitrary payload data in `detail`, and `element.dispatchEvent(event)` fires it on that element as if it were a native event, triggering any matching listeners including delegated ones if `bubbles: true` is set. This is the standard way for independent pieces of UI code to communicate through the DOM without direct references to each other.',null,'const event = new CustomEvent(''item-added'', { detail: { id: 42 }, bubbles: true });
el.dispatchEvent(event);
document.addEventListener(''item-added'', (e) => console.log(e.detail.id));','javascript','medium',ARRAY['javascript','dom','events']::text[],false,108),
('javascript','dom','javascript-dom-109','What does the capture option in addEventListener do?','By default, `addEventListener` attaches a listener for the bubbling phase, running after the event has reached its target. Passing `{ capture: true }` (or just `true`) attaches it for the capturing phase instead, so it runs on the way down from the document root to the target, before any bubbling-phase listeners fire.',null,'el.addEventListener(''click'', handler, { capture: true });','javascript','medium',ARRAY['javascript','dom','events']::text[],false,109),
('javascript','dom','javascript-dom-110','What does the once option in addEventListener do?','`{ once: true }` makes the browser automatically remove the listener right after it fires for the first time, saving you from manually calling `removeEventListener` inside the handler. It''s a concise way to handle events you only care about a single occurrence of, like a one-time animation-end callback.','el.addEventListener(''animationend'', handler, { once: true });',null,null,'easy',ARRAY['javascript','dom','events']::text[],false,110),
('javascript','dom','javascript-dom-111','What does the passive option in addEventListener do, and why does it matter for scrolling?','`{ passive: true }` tells the browser the listener will never call `preventDefault()`, allowing the browser to start scrolling immediately instead of waiting to see if the handler cancels it. This is a meaningful performance improvement for high-frequency events like `touchstart`, `touchmove`, and `wheel`, which is why many browsers now default touch listeners to passive.',null,'window.addEventListener(''touchmove'', handler, { passive: true });','javascript','medium',ARRAY['javascript','dom','events','performance']::text[],false,111),
('javascript','dom','javascript-dom-112','Why must you keep a reference to a handler function to remove it later?','`removeEventListener` matches listeners by reference equality of the function (and the same capture/options), so passing a new inline arrow function to `removeEventListener` will never remove a listener added with a different (even identical-looking) function. To be able to remove a listener later, you must store the exact same function reference that was passed to `addEventListener`.',null,'const handler = () => console.log(''click'');
el.addEventListener(''click'', handler);
el.removeEventListener(''click'', handler); // works
// el.removeEventListener(''click'', () => console.log(''click'')); // does NOT work','javascript','medium',ARRAY['javascript','dom','events']::text[],false,112),
('javascript','dom','javascript-dom-113','What is the difference between the load and DOMContentLoaded events?','`DOMContentLoaded` fires once the HTML has been fully parsed and the DOM tree is built, without waiting for stylesheets, images, or other subresources to finish loading. `load` fires later, once the entire page — including all images, styles, and iframes — has fully loaded, so DOM-manipulation code usually only needs to wait for `DOMContentLoaded`.',null,null,null,'easy',ARRAY['javascript','dom','events']::text[],false,113),
('javascript','dom','javascript-dom-114','What is a MutationObserver used for?','`MutationObserver` lets you asynchronously watch a DOM subtree for changes — added/removed nodes, attribute changes, or text content changes — and run a callback with a batch of mutation records, instead of polling the DOM. It''s commonly used by libraries that need to react to DOM changes made by other code they don''t control, like browser extensions or rich text editors.',null,'const observer = new MutationObserver((mutations) => console.log(mutations));
observer.observe(document.body, { childList: true, subtree: true });','javascript','medium',ARRAY['javascript','dom','observers']::text[],false,114),
('javascript','dom','javascript-dom-115','How does IntersectionObserver help implement lazy loading?','`IntersectionObserver` asynchronously notifies you when an observed element enters or exits the browser''s viewport (or another ancestor element), without the performance cost of manually checking `getBoundingClientRect()` on every scroll event. Lazy-loading images use it to only set an `<img>`''s real `src` once the placeholder scrolls into view, deferring the network request until it''s actually needed.',null,'const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.src = entry.target.dataset.src;
      observer.unobserve(entry.target);
    }
  });
});
images.forEach(img => observer.observe(img));','javascript','medium',ARRAY['javascript','dom','performance','observers']::text[],true,115),
('javascript','dom','javascript-dom-116','What does ResizeObserver do?','`ResizeObserver` notifies you when an observed element''s content box (or border box) size changes, letting you react to layout changes caused by CSS, font loading, or a responsive container — without the inaccuracy and performance cost of listening to the window''s `resize` event and re-measuring elements manually.',null,'const ro = new ResizeObserver(entries => {
  entries.forEach(e => console.log(e.contentRect.width));
});
ro.observe(el);','javascript','medium',ARRAY['javascript','dom','observers']::text[],false,116),
('javascript','dom','javascript-dom-117','How does the browser''s built-in constraint validation API work on forms?','Form controls expose validity state through properties like `required`, `pattern`, and `min`/`max`, and the browser evaluates them automatically; `input.checkValidity()` returns whether the element currently satisfies its constraints, and `input.validity` gives a detailed `ValidityState` object (e.g. `valueMissing`, `patternMismatch`). `input.setCustomValidity(message)` lets you add custom validation logic that plugs into the same native error-reporting UI.',null,'if (!emailInput.checkValidity()) {
  console.log(emailInput.validationMessage);
}','javascript','medium',ARRAY['javascript','dom','forms']::text[],false,117),
('javascript','dom','javascript-dom-118','What is the FormData API used for?','`new FormData(formElement)` reads all the named fields of a form (including file inputs) into a key-value structure that can be sent directly as a `multipart/form-data` request body via `fetch`, without manually serializing each field. It supports the same `get`/`set`/`append`/`entries` style API as `Map` and `URLSearchParams`.',null,'const formData = new FormData(document.querySelector(''form''));
fetch(''/submit'', { method: ''POST'', body: formData });','javascript','easy',ARRAY['javascript','dom','forms']::text[],false,118),
('javascript','dom','javascript-dom-119','What is the difference between localStorage, sessionStorage, and cookies?','`localStorage` persists data with no expiration until explicitly cleared and is scoped per-origin across all tabs/windows. `sessionStorage` is scoped to a single tab and cleared when that tab closes. Cookies are much smaller (~4KB), are automatically sent with every matching HTTP request (adding overhead), and support server-set expiration and `httpOnly`/`secure` flags that Web Storage APIs don''t have.',null,null,null,'easy',ARRAY['javascript','dom','storage']::text[],true,119),
('javascript','dom','javascript-dom-120','How does the History API enable client-side routing in a single-page app?','`history.pushState(state, '''', url)` changes the URL shown in the address bar and adds a new entry to the browser''s session history, without triggering a full page reload, and `history.replaceState()` does the same but replaces the current entry instead of adding one. Listening for the `popstate` event lets the app re-render the correct view when the user navigates with the browser''s back/forward buttons.',null,'history.pushState({ page: ''profile'' }, '''', ''/profile'');
window.addEventListener(''popstate'', (e) => render(e.state));','javascript','medium',ARRAY['javascript','dom','routing']::text[],false,120),
('javascript','dom','javascript-dom-121','What is the same-origin policy and how does CORS relate to it?','The same-origin policy is the browser''s default restriction preventing a script from one origin (scheme + host + port) from reading responses from a different origin, to protect against malicious cross-site data access. CORS is the mechanism that lets a server explicitly opt in to allowing specific cross-origin requests, via response headers like `Access-Control-Allow-Origin`, which the browser checks before exposing the response to the calling script.',null,null,null,'medium',ARRAY['javascript','dom','security']::text[],false,121),
('javascript','dom','javascript-dom-122','What does a basic fetch() request look like, and how does it handle errors?','`fetch(url)` returns a Promise that resolves with a Response object once headers arrive — you then call `.json()` or `.text()` to read the body, which returns another Promise. Critically, `fetch()` only rejects on network failure, not on HTTP error status codes like 404 or 500, so you must check `response.ok` (or `response.status`) yourself and throw manually if the request failed at the HTTP level.',null,'const res = await fetch(''/api/users'');
if (!res.ok) throw new Error(`HTTP ${res.status}`);
const users = await res.json();','javascript','easy',ARRAY['javascript','dom','fetch']::text[],true,122),
('javascript','dom','javascript-dom-123','What is the difference between reflow and repaint in the browser?','A reflow (layout) recalculates the geometry — position and size — of elements affected by a change, which is expensive because it can cascade to the whole page. A repaint just redraws pixels for elements whose appearance changed (like color) without affecting layout, which is cheaper. Reading layout properties like `offsetHeight` right after writing a style change forces a synchronous reflow ("layout thrashing"), which is a common performance trap.',null,null,null,'hard',ARRAY['javascript','dom','performance']::text[],true,123),
('javascript','dom','javascript-dom-124','What is the critical rendering path?','The critical rendering path is the sequence of steps the browser takes to convert HTML, CSS, and JavaScript into pixels on screen: parsing HTML into the DOM, parsing CSS into the CSSOM, combining them into a render tree, computing layout, and finally painting. Optimizing it (minimizing render-blocking CSS/JS, reducing DOM depth) is central to improving perceived page-load performance.',null,null,null,'hard',ARRAY['javascript','dom','performance']::text[],false,124),
('javascript','dom','javascript-dom-125','When would you use requestAnimationFrame instead of setTimeout for animations?','`requestAnimationFrame` schedules a callback to run right before the browser''s next repaint, syncing your updates to the display''s actual refresh rate and automatically pausing in background tabs to save resources. `setTimeout`-based animation has no such synchronization, so it can cause visible jank (frames rendered at the wrong time) and keeps running (wasting CPU/battery) even when the tab isn''t visible.',null,'function tick() {
  updatePosition();
  requestAnimationFrame(tick);
}
requestAnimationFrame(tick);','javascript','medium',ARRAY['javascript','dom','performance','animation']::text[],false,125),
('javascript','dom','javascript-dom-126','What is requestIdleCallback used for?','`requestIdleCallback` schedules a callback to run during a browser''s idle periods, after more urgent work (rendering, user input) has been handled, and passes a deadline object so the callback can yield control if it''s running out of idle time. It''s useful for low-priority background work like analytics batching or prefetching, but shouldn''t be used for anything visually important since it offers no timing guarantees.',null,null,null,'medium',ARRAY['javascript','dom','performance']::text[],false,126),
('javascript','dom','javascript-dom-127','What are the core events involved in implementing native drag-and-drop?','The Drag and Drop API fires `dragstart` on the dragged element, `dragover` on potential drop targets (which must call `preventDefault()` to actually allow a drop), and `drop` on the target when the item is released — with `dataTransfer` carrying the payload between them. `dragend` fires on the source element once the operation finishes, regardless of whether the drop succeeded.',null,'el.addEventListener(''dragstart'', (e) => e.dataTransfer.setData(''text/plain'', el.id));
target.addEventListener(''dragover'', (e) => e.preventDefault());
target.addEventListener(''drop'', (e) => console.log(e.dataTransfer.getData(''text/plain'')));','javascript','medium',ARRAY['javascript','dom','drag-and-drop']::text[],false,127),
('javascript','dom','javascript-dom-128','How do you read from and write to the system clipboard in JavaScript?','The async Clipboard API (`navigator.clipboard.writeText()` / `.readText()`) lets you programmatically copy or read text, but it requires a secure context (HTTPS) and, for reading, often requires explicit user permission or a user-initiated event. The older `document.execCommand(''copy'')` approach still works in many browsers as a fallback but is deprecated.',null,'await navigator.clipboard.writeText(''Copied text'');','javascript','easy',ARRAY['javascript','dom','clipboard']::text[],false,128),
('javascript','dom','javascript-dom-129','What does getBoundingClientRect() return and what is it used for?','`element.getBoundingClientRect()` returns the element''s size and position relative to the viewport (`top`, `left`, `width`, `height`, etc.), reflecting its current rendered layout including any CSS transforms. It''s commonly used for things like custom tooltip positioning, drag-and-drop hit testing, or manual scroll-based visibility checks.','const rect = el.getBoundingClientRect();
const isVisible = rect.top < window.innerHeight && rect.bottom > 0;',null,null,'easy',ARRAY['javascript','dom']::text[],false,129),
('javascript','dom','javascript-dom-130','How can JavaScript respond to responsive CSS breakpoints using matchMedia?','`window.matchMedia(query)` evaluates a CSS media query and returns a `MediaQueryList` with a `.matches` boolean, and calling `.addEventListener(''change'', callback)` on it lets your JavaScript react whenever the viewport crosses that breakpoint — without polling `window.innerWidth` on every resize event.',null,'const mq = window.matchMedia(''(max-width: 768px)'');
mq.addEventListener(''change'', (e) => console.log(e.matches ? ''mobile'' : ''desktop''));','javascript','easy',ARRAY['javascript','dom','responsive']::text[],false,130),
('javascript','dom','javascript-dom-131','What is the Shadow DOM and what problem does it solve?','The Shadow DOM lets an element host a separate, encapsulated DOM subtree (a "shadow root") whose internal structure and styles don''t leak out to, or get affected by, the rest of the page — CSS selectors from outside can''t accidentally style inside the shadow tree, and vice versa. It''s the mechanism native form controls and Web Components use to keep their internal implementation details isolated from the surrounding page.',null,'const shadow = el.attachShadow({ mode: ''open'' });
shadow.innerHTML = ''<style>p { color: red; }</style><p>Isolated</p>'';','javascript','hard',ARRAY['javascript','dom','web-components']::text[],false,131),
('javascript','dom','javascript-dom-132','What is a custom element and how do you define one?','A custom element is a user-defined HTML tag registered with `customElements.define(name, class)`, where the class extends `HTMLElement` and can hook into its lifecycle via callbacks like `connectedCallback()` (mounted) and `attributeChangedCallback()` (an observed attribute changed). Combined with the Shadow DOM and `<template>`, this is the foundation of the Web Components standard for building framework-agnostic reusable UI.',null,'class MyBadge extends HTMLElement {
  connectedCallback() { this.textContent = ''Badge''; }
}
customElements.define(''my-badge'', MyBadge);','javascript','hard',ARRAY['javascript','dom','web-components']::text[],false,132),
('javascript','dom','javascript-dom-133','What are some key ARIA attributes used to make dynamic DOM updates accessible?','`aria-live` (e.g. `"polite"`) marks a region so screen readers announce content changes inside it automatically, `aria-expanded`/`aria-hidden` communicate toggled states like accordions or menus, and `aria-label`/`aria-labelledby` provide accessible names for elements that don''t have visible text. These matter most for custom interactive widgets, since native elements like `<button>` already carry correct semantics automatically.',null,null,null,'medium',ARRAY['javascript','dom','accessibility']::text[],false,133),
('javascript','dom','javascript-dom-134','What is focus management and why does it matter for modal dialogs?','Focus management means deliberately controlling which element has keyboard focus as the UI changes — for a modal, that means moving focus into the dialog when it opens, trapping Tab/Shift+Tab within it so focus can''t escape to the page behind it, and returning focus to the triggering element when it closes. Without this, keyboard and screen-reader users lose track of where they are and can interact with content hidden behind the modal.',null,null,null,'medium',ARRAY['javascript','dom','accessibility']::text[],false,134),
('javascript','dom','javascript-dom-135','What is the difference between touch events and pointer events?','Touch events (`touchstart`, `touchmove`, `touchend`) only fire for touch input and can report multiple simultaneous touch points. Pointer events (`pointerdown`, `pointermove`, `pointerup`) unify mouse, touch, and stylus input behind a single event model with a `pointerType` property, letting you write one handler that works correctly across input types instead of separately handling mouse and touch events.',null,null,null,'medium',ARRAY['javascript','dom','events']::text[],false,135),
('javascript','dom','javascript-dom-136','What is the difference between the window and document objects?','`window` represents the browser tab/window itself — the global execution context, providing things like `location`, `history`, `localStorage`, timers, and the global scope. `document` represents the loaded HTML page''s DOM tree specifically, and is actually a property of `window` (`window.document`), giving access to elements, `querySelector`, and page-level metadata.',null,null,null,'easy',ARRAY['javascript','dom']::text[],false,136),
('javascript','dom','javascript-dom-137','How can detached DOM nodes cause a memory leak?','A DOM node is "detached" once it''s removed from the document, but it can''t actually be garbage collected as long as something still references it — most commonly a JavaScript variable, closure, or an event listener that was never cleaned up. Long-lived single-page apps that repeatedly create and remove elements without releasing these references can slowly accumulate detached nodes in memory over time.',null,null,null,'hard',ARRAY['javascript','dom','memory']::text[],false,137),
('javascript','dom','javascript-dom-138','Why is it important to remove event listeners when an element is removed?','An event listener attached to an element (or to a stable target like `window`/`document` referencing that element in its closure) keeps that element''s scope alive, which can prevent both the element and anything it closes over from being garbage collected even after the element leaves the DOM. Explicitly calling `removeEventListener` (or using `{ signal }` with an AbortController to remove many listeners at once) when a component/element is torn down avoids this class of leak.',null,'const controller = new AbortController();
el.addEventListener(''click'', handler, { signal: controller.signal });
// later, removes all listeners registered with this signal:
controller.abort();','javascript','medium',ARRAY['javascript','dom','memory','events']::text[],false,138),
('javascript','dom','javascript-dom-139','What is the storage event used for?','The `storage` event fires on `window` in other tabs/windows of the same origin whenever `localStorage` is modified — notably, it does not fire in the tab that made the change. This makes it a simple way to synchronize state (like a logged-out session or a theme toggle) across multiple open tabs without any server round-trip.',null,'window.addEventListener(''storage'', (e) => {
  if (e.key === ''theme'') applyTheme(e.newValue);
});','javascript','medium',ARRAY['javascript','dom','storage']::text[],false,139),
('javascript','dom','javascript-dom-140','How do you programmatically enter and exit fullscreen mode?','`element.requestFullscreen()` asks the browser to display that element (and its descendants) in fullscreen, returning a Promise that resolves once the transition completes, and `document.exitFullscreen()` reverses it. This must be triggered from a user gesture (like a click) — browsers block fullscreen requests made without direct user interaction.',null,'videoEl.requestFullscreen();
document.exitFullscreen();','javascript','easy',ARRAY['javascript','dom']::text[],false,140),
('javascript','dom','javascript-dom-141','How do you get the user''s current location with the Geolocation API?','`navigator.geolocation.getCurrentPosition(success, error)` asynchronously requests the device''s location, prompting the user for permission first, and invokes the success callback with a `position.coords` object containing `latitude`/`longitude`. `watchPosition()` is the continuous variant that keeps calling the callback as the device moves, useful for live tracking.',null,'navigator.geolocation.getCurrentPosition(
  (pos) => console.log(pos.coords.latitude, pos.coords.longitude),
  (err) => console.error(err)
);','javascript','easy',ARRAY['javascript','dom']::text[],false,141),
('javascript','dom','javascript-dom-142','What is the difference between a shallow and a deep clone with cloneNode()?','`node.cloneNode()` (or `cloneNode(false)`) copies only the node itself, with none of its children. `node.cloneNode(true)` performs a deep clone, copying the entire subtree of descendants along with it. Neither variant copies event listeners attached via `addEventListener` — those must be reattached manually on the clone.','const copy = card.cloneNode(true);',null,null,'easy',ARRAY['javascript','dom']::text[],false,142),
('javascript','dom','javascript-dom-143','What does the contenteditable attribute do?','Setting `contenteditable="true"` on any element makes its content directly editable by the user in the browser, essentially turning it into a rich-text editing surface without a `<textarea>`. It''s the foundation most WYSIWYG/rich-text editors are built on, though it has notoriously inconsistent behavior across browsers for things like paste handling and list formatting.','<div contenteditable="true">Edit me</div>',null,null,'easy',ARRAY['javascript','dom']::text[],false,143),
('javascript','dom','javascript-dom-144','Why is IntersectionObserver generally preferred over scroll event listeners for detecting element visibility?','Scroll-based visibility checks require calling `getBoundingClientRect()` inside a scroll handler, which runs very frequently and forces the browser to recompute layout synchronously, hurting scroll performance even when debounced or throttled. `IntersectionObserver` instead runs asynchronously off the main thread''s critical path, only invoking your callback when the intersection state actually changes, making it both more efficient and simpler to use correctly.',null,null,null,'medium',ARRAY['javascript','dom','performance']::text[],false,144),
('javascript','dom','javascript-dom-145','What is the difference between innerText and textContent?','`textContent` returns all text within an element regardless of CSS, including text inside `<script>`/hidden elements, and is fast since it doesn''t trigger layout. `innerText` is layout-aware — it respects CSS (`display: none` text is excluded, `<br>` becomes a newline) and reading it forces a reflow, making it slower but sometimes more representative of what a user actually sees rendered.',null,null,null,'medium',ARRAY['javascript','dom']::text[],false,145),
('javascript','dom','javascript-dom-146','What is the beforeunload event used for?','`beforeunload` fires just before the page is about to be unloaded (closed, refreshed, or navigated away from), and setting `event.returnValue` (or calling `preventDefault()`) triggers the browser''s native "leave site?" confirmation dialog. It''s typically used to warn users about unsaved changes, but browsers heavily restrict its behavior (no custom message text, must result from user interaction) to prevent abuse.',null,'window.addEventListener(''beforeunload'', (e) => {
  if (hasUnsavedChanges) e.preventDefault();
});','javascript','medium',ARRAY['javascript','dom','events']::text[],false,146),
('javascript','dom','javascript-dom-147','Why is assigning untrusted data to innerHTML a security risk?','`innerHTML` parses its string as real HTML, so any untrusted content containing a `<script>` tag or an event-handler attribute (like `onerror`) can execute arbitrary JavaScript in the page''s context — a classic DOM-based XSS vulnerability. Using `textContent` for plain text, or sanitizing HTML through a trusted library before insertion, avoids this risk.',null,'// Dangerous if `comment` is user-supplied:
el.innerHTML = comment;
// Safe:
el.textContent = comment;','javascript','medium',ARRAY['javascript','dom','security']::text[],true,147),
('javascript','dom','javascript-dom-148','What does Element.closest() do?','`element.closest(selector)` walks up from the element through its ancestors (including itself) and returns the first one matching the given CSS selector, or `null` if none match. It''s frequently used inside a delegated event handler to find the relevant interactive ancestor of whatever was actually clicked, e.g. `event.target.closest(''.card'')`.','const card = event.target.closest(''.card'');',null,null,'easy',ARRAY['javascript','dom']::text[],false,148),
('javascript','dom','javascript-dom-149','What does Node.contains() check for?','`node.contains(otherNode)` returns whether `otherNode` is a descendant of `node` (or is `node` itself). It''s commonly used to detect "click outside" interactions — for example, checking whether the clicked element is contained within a dropdown before deciding to close it.',null,'document.addEventListener(''click'', (e) => {
  if (!dropdown.contains(e.target)) closeDropdown();
});','javascript','easy',ARRAY['javascript','dom']::text[],false,149),
('javascript','es6-plus','javascript-es6-plus-101','What is the temporal dead zone in JavaScript?','The temporal dead zone (TDZ) is the span between entering a scope and the point where a `let` or `const` declaration is actually executed. Accessing the variable anywhere in that span throws a ReferenceError, even though the declaration is technically hoisted — unlike `var`, which is hoisted and initialized to `undefined`.',null,'console.log(x); // ReferenceError
let x = 5;','javascript','medium',ARRAY['javascript','es6','scope']::text[],false,101),
('javascript','es6-plus','javascript-es6-plus-102','How does array destructuring work in JavaScript?','Array destructuring unpacks values from an array into distinct variables based on position, using square-bracket syntax on the left-hand side of an assignment. Elements can be skipped with empty commas, and default values can be supplied for positions that are undefined.',null,'const [first, , third = ''default''] = [1, 2];
// first = 1, third = ''default''','javascript','easy',ARRAY['javascript','es6','destructuring']::text[],true,102),
('javascript','es6-plus','javascript-es6-plus-103','How do you destructure a deeply nested object?','Nested destructuring mirrors the shape of the object being unpacked, using nested braces to reach into sub-objects and optionally renaming variables along the way. If an intermediate property might be missing, a default value should be provided for it to avoid a TypeError when destructuring further.',null,'const { user: { address: { city = ''Unknown'' } = {} } = {} } = response;','javascript','medium',ARRAY['javascript','es6','destructuring']::text[],false,103),
('javascript','es6-plus','javascript-es6-plus-104','How do default values work in destructuring assignments?','A default value in a destructuring pattern is used only when the corresponding property or array element is `undefined` — not when it is `null` or any other falsy value. This makes destructuring defaults a convenient way to handle optional function arguments or optional object properties.','function greet({ name = ''Guest'' } = {}) { return `Hi ${name}`; }',null,null,'easy',ARRAY['javascript','es6','destructuring']::text[],false,104),
('javascript','es6-plus','javascript-es6-plus-105','How can you swap two variables without a temporary variable using ES6?','Array destructuring lets you swap two variables in a single expression by destructuring a new array literal containing them in reversed order — the right-hand side array is fully evaluated before assignment, so no temporary variable is needed.',null,'let a = 1, b = 2;
[a, b] = [b, a];
// a = 2, b = 1','javascript','easy',ARRAY['javascript','es6','destructuring']::text[],false,105),
('javascript','es6-plus','javascript-es6-plus-106','How does a Set differ from an array for storing unique values?','A Set automatically enforces uniqueness — adding a value that already exists is a no-op — whereas an array allows duplicates and requires manual filtering (e.g. `indexOf` or `includes`) to deduplicate. Sets also provide O(1) average `has()` lookups compared to an array''s O(n) `includes()`.',null,'const unique = [...new Set([1, 2, 2, 3])]; // [1, 2, 3]','javascript','easy',ARRAY['javascript','es6','set']::text[],false,106),
('javascript','es6-plus','javascript-es6-plus-107','What is a WeakMap and how does it differ from a Map?','A WeakMap only accepts objects as keys and holds those keys weakly, meaning an entry doesn''t prevent its key object from being garbage collected once there are no other references to it. This makes WeakMap useful for associating metadata with an object (like private data or caches) without causing memory leaks, but it isn''t iterable and has no `size` property.',null,null,null,'medium',ARRAY['javascript','es6','map','memory']::text[],false,107),
('javascript','es6-plus','javascript-es6-plus-108','What is a WeakSet used for?','A WeakSet stores a collection of objects (not primitives) weakly, so an object present only in a WeakSet can still be garbage collected. It''s commonly used to track whether an object has been ''seen'' or ''processed'' before (like marking DOM nodes) without preventing that object from being cleaned up.',null,null,null,'medium',ARRAY['javascript','es6','set','memory']::text[],false,108),
('javascript','es6-plus','javascript-es6-plus-109','What is the purpose of the Symbol type in JavaScript?','Symbol is a primitive type that produces a guaranteed-unique value each time it''s created, even if given the same description string. It''s primarily used to create object property keys that won''t collide with string keys or with properties added by other code, enabling a form of weak namespacing.','const id = Symbol(''id'');
const obj = { [id]: 123 };',null,null,'medium',ARRAY['javascript','es6','symbol']::text[],false,109),
('javascript','es6-plus','javascript-es6-plus-110','What is a well-known symbol, and what does Symbol.iterator do?','Well-known symbols are built-in Symbol values (like `Symbol.iterator`, `Symbol.asyncIterator`, `Symbol.hasInstance`) that JavaScript itself uses as extension points to customize built-in behavior. `Symbol.iterator` specifically defines the default iterator for an object, which is what `for...of` and the spread operator call to iterate over it.',null,'const range = {
  [Symbol.iterator]() {
    let i = 0;
    return { next: () => (i < 3 ? { value: i++, done: false } : { value: undefined, done: true }) };
  }
};
[...range]; // [0, 1, 2]','javascript','hard',ARRAY['javascript','es6','symbol','iterators']::text[],false,110),
('javascript','es6-plus','javascript-es6-plus-111','What is the difference between for...of and for...in?','`for...of` iterates over the values produced by an iterable''s iterator (arrays, strings, Maps, Sets), which is what you usually want. `for...in` iterates over the enumerable property keys of an object, including inherited ones, which makes it error-prone on arrays since it can pick up non-index properties and doesn''t guarantee order.',null,'for (const value of [10, 20]) { /* 10, 20 */ }
for (const key in { a: 1, b: 2 }) { /* ''a'', ''b'' */ }','javascript','easy',ARRAY['javascript','es6','loops']::text[],false,111),
('javascript','es6-plus','javascript-es6-plus-112','What makes an object iterable in JavaScript?','An object is iterable if it implements the iterable protocol by defining a `[Symbol.iterator]` method that returns an iterator — an object with a `.next()` method returning `{ value, done }` pairs. This is the mechanism that lets built-in constructs like `for...of`, spread syntax, and destructuring work uniformly across arrays, strings, Maps, and Sets.',null,null,null,'hard',ARRAY['javascript','es6','iterators']::text[],false,112),
('javascript','es6-plus','javascript-es6-plus-113','What are generator functions and what problem do they solve?','A generator function, declared with `function*`, can pause its execution at `yield` expressions and resume later, producing a sequence of values lazily over time instead of computing them all at once. This makes generators well suited for representing infinite sequences, custom iterators, and cooperative, step-by-step computations.',null,'function* counter() {
  yield 1;
  yield 2;
  yield 3;
}
const it = counter();
it.next(); // { value: 1, done: false }','javascript','medium',ARRAY['javascript','es6','generators']::text[],true,113),
('javascript','es6-plus','javascript-es6-plus-114','How can you pass a value back into a generator via next()?','Calling `.next(value)` on a generator resumes it and makes `value` become the result of the `yield` expression the generator was paused at, enabling two-way communication between the generator and its caller. This allows generators to act as coroutines that both produce and consume values across multiple resumptions.',null,'function* echo() {
  const input = yield ''ready'';
  console.log(input); // ''hello''
}
const g = echo();
g.next();
g.next(''hello'');','javascript','hard',ARRAY['javascript','es6','generators']::text[],false,114),
('javascript','es6-plus','javascript-es6-plus-115','What does yield* do inside a generator?','`yield*` delegates iteration to another iterable (often another generator), forwarding each of its yielded values as if they were yielded directly by the outer generator. It''s a concise way to compose generators without manually looping over the inner one with `for...of`.',null,'function* inner() { yield 1; yield 2; }
function* outer() {
  yield* inner();
  yield 3;
}
[...outer()]; // [1, 2, 3]','javascript','hard',ARRAY['javascript','es6','generators']::text[],false,115),
('javascript','es6-plus','javascript-es6-plus-116','How do static methods work on ES6 classes?','A method marked `static` belongs to the class itself rather than to instances, and is called directly on the class (e.g. `MyClass.method()`) instead of on an object created with `new`. Static methods are commonly used for factory functions or utility helpers that logically relate to the class but don''t need instance state.',null,'class MathUtil {
  static square(x) { return x * x; }
}
MathUtil.square(4); // 16','javascript','easy',ARRAY['javascript','es6','classes']::text[],false,116),
('javascript','es6-plus','javascript-es6-plus-117','What are private class fields in JavaScript?','Private fields, declared with a `#` prefix, are only accessible from within the class body itself — any access from outside, even from a subclass, throws a SyntaxError at parse time. This gives classes true encapsulation, unlike the older convention of prefixing a property name with an underscore, which is just a naming convention with no actual enforcement.',null,'class Counter {
  #count = 0;
  increment() { return ++this.#count; }
}
const c = new Counter();
c.increment(); // 1
c.#count; // SyntaxError','javascript','medium',ARRAY['javascript','es6','classes']::text[],false,117),
('javascript','es6-plus','javascript-es6-plus-118','What is a class expression and how does it differ from a class declaration?','A class expression defines a class as part of an expression (often assigned to a variable) and can be anonymous, whereas a class declaration uses the `class Name {}` statement form. Unlike function declarations, class declarations are not hoisted in a usable way — both forms are only usable after their definition runs, due to the same temporal dead zone rules as `let`/`const`.','const Shape = class { area() { return 0; } };',null,null,'easy',ARRAY['javascript','es6','classes']::text[],false,118),
('javascript','es6-plus','javascript-es6-plus-119','What is a static initialization block in a class?','A static initialization block (`static { ... }`) runs once when the class itself is defined, letting you perform more complex setup for static fields than a single expression allows — including try/catch and access to private static fields. It executes in the order it appears among other static members.',null,'class Config {
  static settings;
  static {
    Config.settings = loadDefaults();
  }
}','javascript','medium',ARRAY['javascript','es6','classes']::text[],false,119),
('javascript','es6-plus','javascript-es6-plus-120','Can classes have private methods, not just private fields?','Yes — prefixing a method name with `#` makes it a private method, callable only from within the class body, following the same access rules as private fields. This lets a class expose a small public API while keeping internal helper logic fully hidden from consumers.',null,'class Validator {
  #isValidFormat(v) { return /^\d+$/.test(v); }
  check(v) { return this.#isValidFormat(v); }
}','javascript','medium',ARRAY['javascript','es6','classes']::text[],false,120),
('javascript','es6-plus','javascript-es6-plus-121','What is a Proxy in JavaScript and what is it used for?','A Proxy wraps a target object and lets you intercept and customize fundamental operations on it — like property reads, writes, and deletion — through a set of trap functions defined in a handler object. It''s used for things like validation, logging, reactive frameworks (tracking reads/writes for reactivity), and default values for missing properties.',null,'const target = {};
const proxy = new Proxy(target, {
  get(obj, prop) { return prop in obj ? obj[prop] : ''N/A''; }
});
proxy.missing; // ''N/A''','javascript','hard',ARRAY['javascript','es6','proxy']::text[],true,121),
('javascript','es6-plus','javascript-es6-plus-122','What is the Reflect object and how does it relate to Proxy?','Reflect is a built-in object that exposes the same set of fundamental operations (get, set, has, deleteProperty, etc.) as static methods, mirroring the trap names used by Proxy. Inside a Proxy trap, calling the corresponding `Reflect` method is the standard way to forward an operation to the target with correct default semantics, rather than reimplementing it manually.',null,'const proxy = new Proxy(target, {
  get(obj, prop, receiver) { return Reflect.get(obj, prop, receiver); }
});','javascript','hard',ARRAY['javascript','es6','proxy','reflect']::text[],false,122),
('javascript','es6-plus','javascript-es6-plus-123','What does Array.from() do and when would you use it?','`Array.from()` creates a real array from an array-like object (something with a `length` and indexed elements, like `arguments` or a NodeList) or from any iterable (like a Set or Map). It also accepts an optional mapping function as a second argument, letting you transform elements while converting them.',null,'Array.from({ length: 3 }, (_, i) => i * 2); // [0, 2, 4]
Array.from(document.querySelectorAll(''li''));','javascript','easy',ARRAY['javascript','es6','arrays']::text[],false,123),
('javascript','es6-plus','javascript-es6-plus-124','What is the difference between Array.of() and the Array constructor?','`Array.of(7)` creates a single-element array `[7]`, while `Array(7)` creates a sparse array with `length` 7 and no actual elements — a well-known footgun of the `Array` constructor when called with a single numeric argument. `Array.of()` always treats its arguments as elements regardless of how many or what type they are.',null,'Array.of(7); // [7]
Array(7);    // [ <7 empty items> ]','javascript','easy',ARRAY['javascript','es6','arrays']::text[],false,124),
('javascript','es6-plus','javascript-es6-plus-125','What is the difference between Array.prototype.find, findIndex, and findLast?','`find()` returns the first element matching a predicate (or `undefined` if none match), `findIndex()` returns that element''s index instead (or -1), and `findLast()` (ES2023) scans from the end of the array to find the last matching element. All three short-circuit as soon as a match is found, unlike `filter()` which always scans the whole array.',null,'[1, 5, 10, 15].find(n => n > 4);      // 5
[1, 5, 10, 15].findLast(n => n > 4);  // 15','javascript','easy',ARRAY['javascript','es6','arrays']::text[],false,125),
('javascript','es6-plus','javascript-es6-plus-126','What is the difference between Array.prototype.includes() and indexOf()?','`includes()` returns a boolean indicating whether a value is present, and correctly detects `NaN` using the SameValueZero algorithm, whereas `indexOf()` uses strict equality and can never find `NaN` (since `NaN !== NaN`). `includes()` is generally preferred when you only care about presence, not position.',null,'[NaN].includes(NaN); // true
[NaN].indexOf(NaN);  // -1','javascript','easy',ARRAY['javascript','es6','arrays']::text[],false,126),
('javascript','es6-plus','javascript-es6-plus-127','What does Array.prototype.at() offer over bracket notation?','`at()` accepts negative indices to count from the end of the array (e.g. `arr.at(-1)` for the last element), something bracket notation can''t do directly since `arr[-1]` just looks up a non-existent property. It works identically to bracket access for non-negative indices.','const last = [10, 20, 30].at(-1); // 30',null,null,'easy',ARRAY['javascript','es6','arrays']::text[],false,127),
('javascript','es6-plus','javascript-es6-plus-128','What is optional chaining and what problem does it solve?','Optional chaining (`?.`) short-circuits to `undefined` instead of throwing when accessing a property, calling a method, or indexing on a value that is `null` or `undefined` along the chain. It replaces verbose manual checks like `obj && obj.a && obj.a.b` with a single concise expression, `obj?.a?.b`.',null,'const city = user?.address?.city; // undefined instead of a TypeError
user?.getName?.();','javascript','easy',ARRAY['javascript','es6','optional-chaining']::text[],true,128),
('javascript','es6-plus','javascript-es6-plus-129','How does the nullish coalescing operator (??) differ from ||?','`??` returns its right-hand operand only when the left-hand operand is `null` or `undefined`, whereas `||` returns the right-hand operand for any falsy left value, including `0`, `''''`, and `false`. This makes `??` the safer choice for defaulting a value that might legitimately be `0` or an empty string.',null,'const count = 0;
count || 10; // 10 (wrong — 0 is a valid count)
count ?? 10; // 0 (correct)','javascript','easy',ARRAY['javascript','es6','operators']::text[],true,129),
('javascript','es6-plus','javascript-es6-plus-130','What does the exponentiation operator (**) do?','The `**` operator raises the left operand to the power of the right operand, providing a more concise, readable alternative to calling `Math.pow()`. It is right-associative, so `2 ** 3 ** 2` evaluates as `2 ** (3 ** 2)`, i.e. 512.','const cube = 3 ** 3; // 27',null,null,'easy',ARRAY['javascript','es6','operators']::text[],false,130),
('javascript','es6-plus','javascript-es6-plus-131','What does Promise.allSettled() do differently from Promise.all()?','`Promise.allSettled()` waits for every promise in the input to settle — whether fulfilled or rejected — and resolves with an array of `{ status, value }` or `{ status, reason }` objects describing each outcome, never short-circuiting on a single rejection. This is useful when you need the results of all operations regardless of individual failures, unlike `Promise.all()` which rejects immediately on the first failure.',null,'const results = await Promise.allSettled([p1, p2, p3]);
results.forEach(r => console.log(r.status));','javascript','medium',ARRAY['javascript','es6','promises']::text[],false,131),
('javascript','es6-plus','javascript-es6-plus-132','What does Promise.any() do?','`Promise.any()` resolves as soon as any one of the input promises fulfills, ignoring rejections unless every promise rejects — in that case it rejects with an `AggregateError` containing all the individual errors. It''s the fulfillment-focused counterpart to `Promise.race()`, which settles on the first outcome regardless of success or failure.',null,null,null,'medium',ARRAY['javascript','es6','promises']::text[],false,132),
('javascript','es6-plus','javascript-es6-plus-133','What do the logical assignment operators &&=, ||=, and ??= do?','These operators conditionally assign based on the current value: `a ||= b` assigns `b` only if `a` is falsy, `a &&= b` assigns `b` only if `a` is truthy, and `a ??= b` assigns `b` only if `a` is `null` or `undefined`. They''re shorthand for the equivalent `if` statement or ternary, and importantly they short-circuit — the right-hand side isn''t evaluated unless the assignment will actually happen.',null,'let config = {};
config.timeout ??= 3000; // only sets if undefined/null','javascript','medium',ARRAY['javascript','es6','operators']::text[],false,133),
('javascript','es6-plus','javascript-es6-plus-134','What are numeric separators in JavaScript?','Numeric separators let you insert underscores into number literals purely for readability, with no effect on the value — for example `1_000_000` is identical to `1000000`. They''re especially useful for large numbers, hex values, and binary literals where digit grouping helps at a glance.','const billion = 1_000_000_000;',null,null,'easy',ARRAY['javascript','es6','numbers']::text[],false,134),
('javascript','es6-plus','javascript-es6-plus-135','What is top-level await and what constraint does it have?','Top-level await lets you use `await` directly in the top-level scope of an ES module, without wrapping it in an async function, which is convenient for one-time async setup like loading configuration before the rest of the module runs. It only works inside actual ES modules — using it in a regular script or a CommonJS file is a syntax error.',null,'// inside an ES module
const config = await fetch(''/config.json'').then(r => r.json());','javascript','medium',ARRAY['javascript','es6','modules','async']::text[],false,135),
('javascript','es6-plus','javascript-es6-plus-136','What is dynamic import() and how does it differ from static import?','`import()` is a function-like expression that asynchronously loads a module and returns a Promise resolving to its exports namespace object, and it can be called anywhere at runtime — including conditionally inside an `if` block. Static `import` statements, by contrast, must appear at the top level of a module and are resolved before any module code runs, which is what enables features like tree-shaking.',null,'button.addEventListener(''click'', async () => {
  const { renderChart } = await import(''./chart.js'');
  renderChart();
});','javascript','medium',ARRAY['javascript','es6','modules']::text[],false,136),
('javascript','es6-plus','javascript-es6-plus-137','What is globalThis and why was it introduced?','`globalThis` provides a standard way to access the global object regardless of environment — `window` in browsers, `self` in web workers, `global` in Node.js — removing the need for environment-specific detection code. Before it existed, writing cross-environment code that needed the global object required awkward feature detection.',null,null,null,'easy',ARRAY['javascript','es6']::text[],false,137),
('javascript','es6-plus','javascript-es6-plus-138','What are tagged template literals used for?','A tagged template literal calls a function (the ''tag'') with the template''s literal string parts and its interpolated expression values passed separately, instead of producing a plain concatenated string. This is the mechanism libraries like styled-components use to parse CSS-in-JS, and it''s also useful for automatically escaping/sanitizing interpolated values (e.g. for safe SQL or HTML construction).',null,'function highlight(strings, ...values) {
  return strings.reduce((acc, s, i) => `${acc}${s}${values[i] ? `**${values[i]}**` : ''''}`, '''');
}
highlight`Score: ${42}`; // ''Score: **42**''','javascript','hard',ARRAY['javascript','es6','template-literals']::text[],false,138),
('javascript','es6-plus','javascript-es6-plus-139','What does the Intl object provide for formatting numbers and dates?','The `Intl` namespace provides locale-aware formatting built into the JavaScript engine, without needing a library — `Intl.NumberFormat` formats numbers, currencies, and percentages, and `Intl.DateTimeFormat` formats dates and times according to a given locale''s conventions. This avoids manually implementing locale-specific separators, currency symbols, and date orderings.',null,'new Intl.NumberFormat(''en-US'', { style: ''currency'', currency: ''USD'' }).format(1234.5);
// "$1,234.50"','javascript','medium',ARRAY['javascript','es6','intl']::text[],false,139),
('javascript','es6-plus','javascript-es6-plus-140','What is BigInt and when would you need it?','BigInt is a primitive type for representing integers of arbitrary precision, created with an `n` suffix (e.g. `10n`) or `BigInt()`, used when a value exceeds `Number.MAX_SAFE_INTEGER` (2^53 - 1) and precision would otherwise be lost. BigInt values can''t be mixed with regular numbers in arithmetic without explicit conversion, and they aren''t supported by `JSON.stringify()` without a custom replacer.',null,'const big = 9007199254740993n;
typeof big; // ''bigint''','javascript','medium',ARRAY['javascript','es6','bigint']::text[],false,140),
('javascript','es6-plus','javascript-es6-plus-141','What does export * from ''./module'' do?','`export * from ''./module''` re-exports every named export from another module through the current module, without needing to import and re-export each one individually — useful for building a single "barrel" entry point that aggregates a folder''s exports. It does not forward that module''s default export; that needs a separate explicit re-export.','// index.js
export * from ''./button.js'';
export * from ''./input.js'';',null,null,'medium',ARRAY['javascript','es6','modules']::text[],false,141),
('javascript','es6-plus','javascript-es6-plus-142','What are the trade-offs between named exports and a default export?','Named exports make a module''s API explicit and enable better auto-import and refactoring tooling since each import must match an actual exported name, and they support tree-shaking cleanly since bundlers can see exactly what''s used. A default export is convenient for modules that expose one primary thing, but its imported name is arbitrary at the call site, which can lead to inconsistent naming across a codebase.',null,null,null,'medium',ARRAY['javascript','es6','modules']::text[],false,142),
('javascript','es6-plus','javascript-es6-plus-143','What happens with circular dependencies between ES modules?','ES modules can have circular imports — module A importing from B while B imports from A — because the module system uses live bindings resolved lazily rather than eagerly copying values. If module A tries to use a binding from B before B has finished initializing it, that binding may still be `undefined` at that point in execution, so code relying on circular imports needs to be careful about what it accesses at module-evaluation time versus later.',null,null,null,'hard',ARRAY['javascript','es6','modules']::text[],false,143),
('javascript','es6-plus','javascript-es6-plus-144','How does the static structure of ES modules enable tree-shaking?','Because ES module `import`/`export` declarations are static — they can''t be conditionally constructed at runtime like CommonJS''s `require()` can — a bundler can analyze the full dependency graph ahead of time and determine exactly which exports are actually used. Unused exports can then be safely stripped from the final bundle, a process known as tree-shaking, which isn''t reliably possible with CommonJS''s dynamic module system.',null,null,null,'medium',ARRAY['javascript','es6','modules','performance']::text[],false,144),
('javascript','es6-plus','javascript-es6-plus-145','What is import.meta used for?','`import.meta` is an object available inside ES modules that exposes metadata about the current module, most commonly `import.meta.url`, which gives the module''s own URL — useful for resolving relative asset paths or constructing worker URLs without hardcoding an absolute path.','const workerUrl = new URL(''./worker.js'', import.meta.url);',null,null,'medium',ARRAY['javascript','es6','modules']::text[],false,145),
('javascript','es6-plus','javascript-es6-plus-146','What is Object.groupBy() and what problem does it solve?','`Object.groupBy()` (a newer addition to the language) takes an iterable and a callback, and returns a plain object whose keys are the callback''s return values and whose values are arrays of the original items that produced each key — replacing the common manual `reduce()` pattern used to bucket items by some property. `Map.groupBy()` is the equivalent that returns a Map instead of a plain object, useful when group keys aren''t strings.',null,'Object.groupBy([1, 2, 3, 4], n => n % 2 === 0 ? ''even'' : ''odd'');
// { odd: [1, 3], even: [2, 4] }','javascript','medium',ARRAY['javascript','es6','arrays']::text[],false,146),
('javascript','es6-plus','javascript-es6-plus-147','What is a WeakRef and when would you use one?','A `WeakRef` holds a weak reference to an object, letting you access it (via `.deref()`) while it''s still alive without preventing it from being garbage collected. It''s an advanced, rarely-needed tool for building caches where entries should be automatically reclaimed under memory pressure — most application code should prefer regular references and let normal scoping manage lifetime.',null,null,null,'hard',ARRAY['javascript','es6','memory']::text[],false,147),
('javascript','es6-plus','javascript-es6-plus-148','What does a FinalizationRegistry do?','A `FinalizationRegistry` lets you register a callback to run after an object has been garbage collected, typically used alongside `WeakRef` to clean up external resources (like a native handle) associated with an object once it''s gone. Because garbage collection timing is not guaranteed or deterministic, this callback should never be relied on for correctness-critical cleanup, only for best-effort resource reclamation.',null,null,null,'hard',ARRAY['javascript','es6','memory']::text[],false,148),
('javascript','functions','javascript-functions-101','Why does the classic "closures in a loop with var" example print the same value for every iteration?','Because var is function-scoped, not block-scoped, all the callbacks created inside the loop share the same single variable binding. By the time the callbacks actually run (asynchronously), the loop has already finished and the shared variable holds its final value. Using let instead creates a new binding for each iteration, so each closure captures its own value.',null,'for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}
// logs 3, 3, 3 — use let instead of var to fix','javascript','medium',ARRAY['javascript','functions','closures']::text[],true,101),
('javascript','functions','javascript-functions-102','What is a higher-order function?','A higher-order function is a function that either takes one or more functions as arguments, returns a function, or both. Array methods like map, filter, and reduce are common examples, as are function factories and decorators.',null,'const withLogging = (fn) => (...args) => {
  console.log(''calling with'', args);
  return fn(...args);
};','javascript','easy',ARRAY['javascript','functions']::text[],true,102),
('javascript','functions','javascript-functions-103','What is a pure function?','A pure function always returns the same output for the same input and produces no observable side effects, such as mutating external state, logging, or making network calls. Pure functions are easier to test, reason about, and memoize, and are a core building block of functional programming.',null,'// pure
const add = (a, b) => a + b;

// impure — depends on and mutates external state
let total = 0;
const addToTotal = (n) => (total += n);','javascript','easy',ARRAY['javascript','functions']::text[],false,103),
('javascript','functions','javascript-functions-104','What is memoization and how would you implement it?','Memoization is an optimization technique that caches the result of an expensive function call keyed by its arguments, so subsequent calls with the same arguments return the cached result instead of recomputing it. It only works correctly for pure functions, since it assumes the same input always produces the same output.',null,'function memoize(fn) {
  const cache = new Map();
  return (arg) => {
    if (cache.has(arg)) return cache.get(arg);
    const result = fn(arg);
    cache.set(arg, result);
    return result;
  };
}','javascript','medium',ARRAY['javascript','functions','performance']::text[],true,104),
('javascript','functions','javascript-functions-105','What is function composition?','Function composition is combining two or more functions to produce a new function, where the output of one function becomes the input of the next. It''s a core functional programming technique for building complex behavior from small, reusable, single-purpose functions.',null,'const compose = (...fns) => (x) => fns.reduceRight((acc, fn) => fn(acc), x);
const addThenDouble = compose((x) => x * 2, (x) => x + 1);
addThenDouble(3); // 8','javascript','medium',ARRAY['javascript','functions','functional']::text[],false,105),
('javascript','functions','javascript-functions-106','What are default parameters and what are some edge cases to be aware of?','Default parameters let a function fall back to a specified value when an argument is omitted or explicitly passed as undefined (but not null). A subtle edge case is that default values are evaluated at call time, left to right, and can reference earlier parameters in the same parameter list.',null,'function greet(name = ''Guest'', greeting = `Hello, ${name}`) {
  return greeting;
}
greet(); // ''Hello, Guest''
greet(undefined, ''Hi''); // ''Hi''','javascript','medium',ARRAY['javascript','functions','es6']::text[],false,106),
('javascript','functions','javascript-functions-107','What is the difference between rest parameters and the arguments object?','Rest parameters (...args) collect the remaining arguments into a real Array instance, so array methods like map and filter work directly on it. The arguments object is an array-like (not a real array) available in regular functions, lacks array methods, and — unlike rest params — isn''t available at all in arrow functions.',null,'function sum(...nums) {
  return nums.reduce((a, b) => a + b, 0); // works directly
}','javascript','medium',ARRAY['javascript','functions','es6']::text[],false,107),
('javascript','functions','javascript-functions-108','Why can''t arrow functions be used as object methods that need to access `this`?','Arrow functions don''t have their own `this` binding — they inherit `this` lexically from the surrounding scope at the time they''re defined, which for a top-level object literal method is usually not the object itself. Using a regular function (or method shorthand) ensures `this` refers to the object the method was called on.',null,'const counter = {
  count: 0,
  increment: () => { this.count++; } // wrong — `this` isn''t `counter`
};','javascript','hard',ARRAY['javascript','functions','this']::text[],true,108),
('javascript','functions','javascript-functions-109','What is the difference between a named function expression and an anonymous function expression?','A named function expression has an identifier that is only visible inside the function''s own body (useful for recursion or debugging stack traces), while the outer scope still refers to it via the variable it was assigned to. An anonymous function expression has no such internal name, which makes recursive self-reference and stack traces harder to read.',null,'const factorial = function fact(n) {
  return n <= 1 ? 1 : n * fact(n - 1); // ''fact'' only usable inside here
};','javascript','medium',ARRAY['javascript','functions']::text[],false,109),
('javascript','functions','javascript-functions-110','What is recursion, and what''s a risk to watch out for when using it in JavaScript?','Recursion is when a function calls itself to break a problem into smaller subproblems, with a base case that stops the recursion. The main risk is a stack overflow if the recursion is too deep or the base case is missing or unreachable, since JavaScript engines have a limited call stack size and (unlike some languages) don''t guarantee tail-call optimization in practice.',null,'function factorial(n) {
  if (n <= 1) return 1; // base case
  return n * factorial(n - 1);
}','javascript','easy',ARRAY['javascript','functions','recursion']::text[],false,110),
('javascript','functions','javascript-functions-111','What are generator functions and what does the yield keyword do?','A generator function, declared with function*, can pause and resume its execution using the yield keyword, producing a sequence of values over time instead of returning a single value at once. Calling a generator function returns an iterator, and each call to .next() resumes execution until the next yield.',null,'function* range(start, end) {
  for (let i = start; i <= end; i++) yield i;
}
[...range(1, 3)]; // [1, 2, 3]','javascript','hard',ARRAY['javascript','functions','generators']::text[],false,111),
('javascript','functions','javascript-functions-112','What is generator delegation using yield*?','yield* delegates iteration to another generator or iterable, effectively yielding all of its values one by one as though they were yielded directly from the outer generator. It''s useful for composing generators together without manually looping over the inner generator.',null,'function* inner() { yield 1; yield 2; }
function* outer() {
  yield* inner();
  yield 3;
}
[...outer()]; // [1, 2, 3]','javascript','hard',ARRAY['javascript','functions','generators']::text[],false,112),
('javascript','functions','javascript-functions-113','What is the difference between function hoisting and var hoisting?','Function declarations are hoisted completely, including their full body, so they can be called before their definition appears in the code. var declarations are hoisted but only the declaration itself, initialized to undefined — the assignment stays in place, so accessing the variable before assignment gives undefined rather than the intended value.',null,'sayHi(); // works — ''Hi''
function sayHi() { console.log(''Hi''); }

console.log(x); // undefined, not an error
var x = 5;','javascript','medium',ARRAY['javascript','functions','hoisting']::text[],false,113),
('javascript','functions','javascript-functions-114','What does Function.prototype.length return?','Function.length returns the number of parameters declared before the first one with a default value or a rest parameter — parameters after a default value, and rest parameters themselves, are not counted. It''s occasionally used by libraries to introspect how many arguments a callback expects.',null,'function f(a, b, c = 1, ...rest) {}
f.length; // 2','javascript','hard',ARRAY['javascript','functions']::text[],false,114),
('javascript','functions','javascript-functions-115','What does it mean that functions are "first-class citizens" in JavaScript?','Being first-class means functions can be treated like any other value: assigned to variables, stored in data structures, passed as arguments, and returned from other functions. This is what makes higher-order functions, callbacks, and functional programming patterns possible in JavaScript.',null,null,null,'easy',ARRAY['javascript','functions']::text[],false,115),
('javascript','functions','javascript-functions-116','What is a callback function, and what''s a downside of relying heavily on them?','A callback is a function passed as an argument to another function, to be invoked later — commonly used for asynchronous operations or customizable behavior. Deeply nesting callbacks (especially for sequential async steps) leads to "callback hell," hard-to-read pyramid-shaped code, which Promises and async/await were introduced to address.',null,null,null,'easy',ARRAY['javascript','functions','async']::text[],false,116),
('javascript','functions','javascript-functions-117','Does JavaScript support function overloading like Java does?','No — JavaScript doesn''t support true function overloading; declaring two functions with the same name simply has the second definition overwrite the first. The common workaround is to inspect the number or type of arguments inside a single function and branch behavior accordingly, or use default/rest parameters.',null,'function greet(name, formal) {
  return formal ? `Good day, ${name}` : `Hey ${name}`;
}','javascript','medium',ARRAY['javascript','functions']::text[],false,117),
('javascript','functions','javascript-functions-118','What is partial application, and how does it differ from currying?','Partial application fixes some (but not necessarily all) of a function''s arguments up front, producing a new function that takes the remaining arguments and can be called with any number of them at once. Currying specifically transforms a function into a chain of unary (single-argument) functions — currying is a specific, stricter form of partial application.',null,'const add3 = (a, b, c) => a + b + c;
const addTo5 = add3.bind(null, 5); // partial application
addTo5(2, 3); // 10','javascript','hard',ARRAY['javascript','functions','functional']::text[],false,118),
('javascript','functions','javascript-functions-119','What is new.target used for in a function?','new.target is a meta-property that is set to the constructor function itself when a function is invoked with the `new` keyword, and is undefined otherwise. It''s used inside a function to detect whether it was called as a constructor, letting you guard against a constructor function being called without `new`.',null,'function Person(name) {
  if (!new.target) throw new Error(''Person must be called with new'');
  this.name = name;
}','javascript','hard',ARRAY['javascript','functions']::text[],false,119),
('javascript','functions','javascript-functions-120','What is the difference between a constructor function and a regular function?','Any function can be used as a constructor by calling it with `new`, which creates a new object, sets its prototype, binds `this` to that new object, and returns it implicitly (unless the function explicitly returns another object). By convention, constructor functions are named with a capital letter to signal that they''re meant to be called with `new`.',null,'function Point(x, y) {
  this.x = x;
  this.y = y;
}
const p = new Point(1, 2);','javascript','medium',ARRAY['javascript','functions']::text[],false,120),
('javascript','functions','javascript-functions-121','What is the module pattern in JavaScript?','The module pattern uses an IIFE (or, in modern code, a real ES module) to create a private scope, exposing only a deliberate public API while keeping implementation details hidden. Before native ES modules existed, this was the standard way to emulate encapsulation and avoid polluting the global namespace.',null,'const counterModule = (function () {
  let count = 0;
  return {
    increment: () => ++count,
    get: () => count,
  };
})();','javascript','medium',ARRAY['javascript','functions','patterns']::text[],false,121),
('javascript','functions','javascript-functions-122','What is the difference between the Function constructor and a regular function declaration?','The Function constructor (new Function(''a'', ''b'', ''return a + b'')) creates a function from strings at runtime, similar to eval, and always executes in the global scope rather than the scope where it was created. It''s rarely used in practice because it''s slower, bypasses closures, and poses security/injection risks if used with untrusted input.',null,'const add = new Function(''a'', ''b'', ''return a + b'');
add(2, 3); // 5 — but avoid this pattern','javascript','hard',ARRAY['javascript','functions']::text[],false,122),
('javascript','functions','javascript-functions-123','What is a thunk in JavaScript?','A thunk is a function that wraps an expression or async operation to delay its evaluation until it''s actually called, deferring the work. Thunks are commonly seen in Redux middleware (redux-thunk) to delay dispatching an action until some async work completes.',null,'const thunk = () => fetch(''/api/data'').then((r) => r.json());
// nothing happens until thunk() is called','javascript','hard',ARRAY['javascript','functions','async']::text[],false,123),
('javascript','functions','javascript-functions-124','Is recursion generally faster or slower than an equivalent iterative loop in JavaScript?','Iterative loops are generally faster and more memory-efficient than recursion in JavaScript, because each recursive call adds a new frame to the call stack, and JavaScript engines don''t reliably optimize tail calls in practice despite it being part of the ES6 spec. Recursion is still preferred when it makes the code significantly clearer, such as tree traversal.',null,null,null,'medium',ARRAY['javascript','functions','performance']::text[],false,124),
('javascript','functions','javascript-functions-125','Does JavaScript actually perform tail call optimization?','Tail call optimization (reusing the current stack frame for a function call that is the very last action in a function) is part of the ES6 specification, but in practice only Safari''s JavaScriptCore implements it — V8 (Chrome, Node.js) and Firefox''s engine do not, so recursive code relying on it will still hit a stack overflow on deep recursion in most environments.',null,null,null,'hard',ARRAY['javascript','functions','performance']::text[],false,125),
('javascript','functions','javascript-functions-126','What is a variadic function?','A variadic function is one that accepts a variable number of arguments rather than a fixed count, implemented in JavaScript using rest parameters or the arguments object. Math.max() and console.log() are built-in examples of variadic functions.',null,'function sum(...numbers) {
  return numbers.reduce((a, b) => a + b, 0);
}
sum(1, 2, 3, 4); // 10','javascript','easy',ARRAY['javascript','functions']::text[],false,126),
('javascript','functions','javascript-functions-127','What is method shorthand syntax in object literals?','ES6 introduced a shorter syntax for defining methods on an object literal, omitting the `function` keyword and colon. It behaves the same as assigning a regular function expression to a property, except shorthand methods can use `super` when defined inside an object literal.',null,'const obj = {
  greet() { return ''hi''; } // shorthand, same as greet: function() {...}
};','javascript','easy',ARRAY['javascript','functions','es6']::text[],false,127),
('javascript','functions','javascript-functions-128','How is bind() used for partial application, and how does it differ from a plain wrapper function?','fn.bind(thisArg, ...presetArgs) returns a new function with `this` and some leading arguments permanently fixed, and any further arguments passed at call time are appended after the preset ones. Unlike writing a manual wrapper function, bind() is a built-in, slightly more efficient mechanism and also correctly locks in `this`, not just the arguments.',null,'function multiply(a, b) { return a * b; }
const double = multiply.bind(null, 2);
double(5); // 10','javascript','medium',ARRAY['javascript','functions','this']::text[],false,128),
('javascript','functions','javascript-functions-129','What is a self-invoking function pattern used for besides creating private scope?','Besides encapsulating private state, self-invoking (IIFE) patterns are used to run initialization code exactly once immediately on load, to avoid leaking loop variables into an async callback pre-ES6, and to create isolated contexts for library code that shouldn''t conflict with globals from other scripts on the page.',null,null,null,'medium',ARRAY['javascript','functions','patterns']::text[],false,129),
('javascript','functions','javascript-functions-130','What happens if you forget to bind `this` in a class method passed as a callback?','When a class method is passed as a standalone reference (e.g. as an event handler), it loses its connection to the instance it was defined on, so `this` inside the method becomes undefined (in strict mode/classes) when the method is later invoked. Fixing this requires binding the method in the constructor, using an arrow function class field, or binding at the call site.',null,'class Button {
  constructor() { this.label = ''Click''; }
  handleClick() { console.log(this.label); }
}
const b = new Button();
const fn = b.handleClick;
fn(); // TypeError: Cannot read properties of undefined','javascript','hard',ARRAY['javascript','functions','this']::text[],true,130),
('javascript','functions','javascript-functions-131','What is an arrow function class field, and how does it solve the `this` binding problem?','An arrow function assigned as a class field (e.g. `handleClick = () => {...}`) captures `this` lexically from the constructor at the time the instance is created, so it''s always bound to that instance regardless of how the method is later called or passed around. This avoids needing to manually bind the method in the constructor.',null,'class Button {
  label = ''Click'';
  handleClick = () => console.log(this.label); // always bound to instance
}','javascript','medium',ARRAY['javascript','functions','this']::text[],false,131),
('javascript','functions','javascript-functions-132','What is the difference between eager and lazy evaluation, and how do generators enable laziness in JavaScript?','Eager evaluation computes a value immediately when an expression is encountered; lazy evaluation defers computation until the value is actually needed. Generators enable lazy evaluation because each `yield` pauses execution, so values are only produced on demand as the consumer calls .next(), which is useful for infinite sequences or expensive computations.',null,'function* naturals() {
  let n = 1;
  while (true) yield n++;
}
const it = naturals();
it.next().value; // 1 — nothing else computed yet','javascript','hard',ARRAY['javascript','functions','generators']::text[],false,132),
('javascript','functions','javascript-functions-133','What does it mean for a function to be idempotent, and how does that differ from being pure?','An idempotent function produces the same result and end state no matter how many times it''s called with the same input (common in HTTP PUT/DELETE semantics), but it may still have side effects — repeating them just doesn''t change the outcome further. A pure function additionally must have no side effects at all, which is a stricter requirement than idempotency.',null,null,null,'hard',ARRAY['javascript','functions']::text[],false,133),
('javascript','functions','javascript-functions-134','How can you implement a simple once() function that ensures a callback only runs a single time?','A once() wrapper uses a closure to keep track of whether the wrapped function has already been called, and simply returns the cached result (or does nothing) on subsequent calls, delegating to the original function only the first time.',null,'function once(fn) {
  let called = false, result;
  return (...args) => {
    if (!called) { called = true; result = fn(...args); }
    return result;
  };
}','javascript','medium',ARRAY['javascript','functions','closures']::text[],false,134),
('javascript','functions','javascript-functions-135','What is the difference between a callback-based API and a Promise-based API from a function design perspective?','A callback-based API accepts a function argument that the underlying operation invokes when it completes (often with an error-first signature), giving the caller no direct return value to work with. A Promise-based API instead returns a Promise object immediately, which the caller can chain with .then()/.catch() or await, making composition and error handling far more consistent.',null,null,null,'medium',ARRAY['javascript','functions','async']::text[],false,135),
('javascript','functions','javascript-functions-136','How do you write a curried function manually without a library?','A manually curried function returns a chain of single-argument functions until all expected arguments have been collected, at which point it invokes the original function with all of them. A generic curry() helper can do this for any function by checking fn.length against the accumulated arguments so far.',null,'function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) return fn(...args);
    return (...more) => curried(...args, ...more);
  };
}','javascript','hard',ARRAY['javascript','functions','functional']::text[],false,136),
('javascript','functions','javascript-functions-137','What is the difference between passing a function reference and invoking a function when assigning an event handler?','Passing a function reference (onClick={handleClick}) hands the function itself to be called later by the framework/DOM API. Invoking it immediately (onClick={handleClick()}) calls the function right away during render/setup and assigns whatever it *returns* as the handler, which is almost never the intended behavior.',null,'button.addEventListener(''click'', handleClick); // correct — passes reference
button.addEventListener(''click'', handleClick()); // wrong — calls immediately','javascript','easy',ARRAY['javascript','functions']::text[],true,137),
('javascript','functions','javascript-functions-138','What is a closure, technically, in terms of the JavaScript execution model?','Technically, a closure is the combination of a function together with references to its surrounding lexical environment (the variables in scope at the time it was created). The JavaScript engine keeps that environment alive in memory for as long as the closure itself is reachable, even after the outer function that created it has returned.',null,null,null,'medium',ARRAY['javascript','functions','closures']::text[],false,138),
('javascript','functions','javascript-functions-139','How can closures accidentally cause memory leaks?','Because a closure keeps its entire enclosing scope alive as long as it exists, capturing a large object or DOM node inside a long-lived closure (like an event listener that''s never removed) prevents that memory from being garbage collected even if it''s no longer actually needed. Being deliberate about what a closure captures, and cleaning up listeners/timers, avoids this.',null,null,null,'hard',ARRAY['javascript','functions','closures','performance']::text[],false,139),
('javascript','functions','javascript-functions-140','What is a private variable pattern using closures, before class private fields existed?','Before the # private field syntax, closures were the standard way to emulate private state — a variable declared inside a constructor or factory function is inaccessible from outside, and only the functions returned/attached from that same scope (which close over the variable) can read or modify it.',null,'function createAccount(balance) {
  return {
    deposit: (amount) => (balance += amount),
    getBalance: () => balance,
  };
}
// balance itself is not directly accessible from outside','javascript','medium',ARRAY['javascript','functions','closures']::text[],true,140),
('javascript','functions','javascript-functions-141','What is the difference between arguments.length and a function''s declared parameter count?','arguments.length reflects the actual number of arguments passed at the call site, regardless of how many parameters the function declares. fn.length reflects how many parameters were declared (up to the first default/rest parameter) — the two can easily differ if a function is called with more or fewer arguments than it declares.',null,'function f(a, b) { return arguments.length; }
f(1, 2, 3); // 3, even though f.length is 2','javascript','hard',ARRAY['javascript','functions']::text[],false,141),
('javascript','functions','javascript-functions-142','What is an async function under the hood, in terms of generators and promises?','Conceptually, an async function behaves like a generator function whose yields are automatically driven by a runner that resolves each awaited Promise before resuming execution. You don''t write the generator/runner machinery yourself — async/await is syntactic sugar the engine provides — but understanding that mental model explains why await only works inside async functions.',null,null,null,'hard',ARRAY['javascript','functions','async']::text[],false,142),
('javascript','functions','javascript-functions-143','What is function currying used for in real-world code, beyond interview trivia?','Currying is used to build specialized, reusable functions from a general one by pre-filling common arguments — for example, a generic `request(method, url, body)` function curried into `get = request(''GET'')`, or configuring event handlers, validators, or middleware with shared setup ahead of time.',null,'const request = (method) => (url) => (body) => fetch(url, { method, body });
const post = request(''POST'');
post(''/api/users'')({ name: ''Ana'' });','javascript','medium',ARRAY['javascript','functions','functional']::text[],false,143),
('javascript','functions','javascript-functions-144','What is the difference between Array.prototype.forEach and a for loop in terms of function semantics?','forEach takes a callback function and invokes it once per array element, but it cannot be stopped early with break/continue and always returns undefined, making it purely for side effects. A regular for loop supports break/continue and can be used to build a return value directly, giving more control at the cost of slightly more boilerplate.',null,'arr.forEach((item) => {
  if (item === ''skip'') return; // only skips this iteration, doesn''t stop the loop
});','javascript','medium',ARRAY['javascript','functions','arrays']::text[],false,144),
('javascript','functions','javascript-functions-145','What is a decorator-like pattern for functions in plain JavaScript (without the decorator proposal)?','Even without the experimental decorator syntax, you can achieve the same effect by writing a higher-order function that wraps another function, adding behavior (like logging, timing, or retries) before/after calling the original, then returning the wrapped version.',null,'function withTiming(fn) {
  return (...args) => {
    const start = Date.now();
    const result = fn(...args);
    console.log(`${fn.name} took ${Date.now() - start}ms`);
    return result;
  };
}','javascript','hard',ARRAY['javascript','functions','patterns']::text[],false,145),
('javascript','functions','javascript-functions-146','What is the difference between .call() and a direct method call in terms of what problem it solves?','A direct method call (obj.method()) automatically binds `this` to obj. .call() lets you invoke a function while manually specifying what `this` should be, which is useful for borrowing a method from one object (or from Array.prototype) and applying it to a different, unrelated object.',null,'function greet() { return `Hi, ${this.name}`; }
greet.call({ name: ''Sam'' }); // ''Hi, Sam'' — borrowing greet for another object','javascript','medium',ARRAY['javascript','functions','this']::text[],false,146),
('javascript','functions','javascript-functions-147','How would you convert an array-like arguments object into a real array inside a function?','Use Array.from(arguments) or the spread operator [...arguments] to convert the array-like arguments object into a genuine array with full access to array methods. This is largely unnecessary in modern code since rest parameters already produce a real array directly.',null,'function f() {
  const args = Array.from(arguments);
  return args.map((x) => x * 2);
}','javascript','easy',ARRAY['javascript','functions']::text[],false,147),
('javascript','functions','javascript-functions-148','What''s the difference between throwing inside a regular function versus inside a Promise executor or async function?','Throwing inside a regular synchronous function propagates immediately as a normal exception that the caller must catch with try/catch. Throwing inside a Promise executor or an async function is captured automatically and turned into a rejected Promise instead of an uncaught exception, so it must be handled with .catch() or a try/catch around an await.',null,null,null,'hard',ARRAY['javascript','functions','async']::text[],false,148),
('javascript','functions','javascript-functions-149','What is the significance of a function''s name property, and can it be changed?','Every function has a read-only (but configurable) `name` property reflecting its inferred or declared name, which is inferred automatically when a function is assigned to a variable or object property, even for anonymous arrow functions. It''s mainly useful for debugging and stack traces, and can be explicitly overridden with Object.defineProperty if needed.',null,'const greet = () => {};
greet.name; // ''greet'', inferred from the assignment','javascript','hard',ARRAY['javascript','functions']::text[],false,149),
('javascript','functions','javascript-functions-150','What is the difference between a factory function and a constructor function?','A factory function is a regular function that returns a new object explicitly, without using `new` or `this` — the caller just calls it like any other function. A constructor function relies on `new` to create and implicitly return a new object with `this` bound to it. Factory functions avoid `new`-related footguns (like forgetting it) entirely.',null,'function createPoint(x, y) {
  return { x, y }; // no `new` needed
}
const p = createPoint(1, 2);','javascript','medium',ARRAY['javascript','functions','patterns']::text[],false,150),
('javascript','functions','javascript-functions-151','What does it mean for a function argument to be passed "by reference" versus "by value" in JavaScript?','JavaScript always passes arguments by value — but for objects and arrays, the "value" being copied is a reference to the object, so mutating the object''s contents inside the function affects the caller''s object too, while reassigning the parameter itself to a brand-new object does not affect the caller''s variable.',null,'function mutate(obj) { obj.x = 99; } // affects caller''s object
function reassign(obj) { obj = { x: 99 }; } // does not affect caller''s variable','javascript','medium',ARRAY['javascript','functions']::text[],true,151),
('javascript','objects','javascript-objects-101','What does Object.keys(), Object.values(), and Object.entries() return?','Object.keys() returns an array of a given object''s own enumerable string-keyed property names. Object.values() returns an array of the corresponding values, and Object.entries() returns an array of [key, value] pairs. All three only include own enumerable properties, not inherited ones.',null,'const obj = { a: 1, b: 2 };
Object.keys(obj);   // [''a'', ''b'']
Object.values(obj); // [1, 2]
Object.entries(obj); // [[''a'',1],[''b'',2]]','javascript','easy',ARRAY['javascript','objects']::text[],true,101),
('javascript','objects','javascript-objects-102','What is the difference between Object.assign() and the object spread operator?','Both perform a shallow merge of one or more source objects into a target, copying only own enumerable properties. Object.assign() mutates and returns the first argument (the target), while the spread operator ({...a, ...b}) always creates a brand new object, leaving the originals untouched. Spread is generally preferred for immutable-style merging since it avoids accidentally mutating an existing object.',null,'const merged = Object.assign({}, a, b);
const merged2 = { ...a, ...b };','javascript','easy',ARRAY['javascript','objects']::text[],false,102),
('javascript','objects','javascript-objects-103','What does Object.create() do and when would you use it?','Object.create(proto) creates a new object with the specified object as its prototype, without invoking a constructor. It''s useful for building objects with a specific prototype chain directly, implementing prototypal inheritance without classes, or creating an object with no prototype at all via Object.create(null), which avoids inherited properties like toString.',null,'const animal = { speak() { return ''sound''; } };
const dog = Object.create(animal);
dog.speak(); // ''sound''','javascript','medium',ARRAY['javascript','objects','prototype']::text[],false,103),
('javascript','objects','javascript-objects-104','How does the prototype chain work when looking up a property?','When you access a property on an object, the JS engine first checks the object''s own properties. If not found, it looks at the object''s prototype (via the internal [[Prototype]] link), then that prototype''s prototype, and so on, until it reaches Object.prototype or finds the property. If the chain ends at null without a match, the result is undefined.',null,null,null,'medium',ARRAY['javascript','objects','prototype']::text[],true,104),
('javascript','objects','javascript-objects-105','What is the difference between __proto__ and Object.getPrototypeOf()?','__proto__ is a legacy, non-standard (though widely implemented) accessor property that exposes an object''s prototype, primarily kept for browser compatibility. Object.getPrototypeOf() is the standard, recommended way to read an object''s prototype, and Object.setPrototypeOf() is the standard way to change it. Modern code should avoid __proto__ in favor of these methods or Object.create().',null,null,null,'medium',ARRAY['javascript','objects','prototype']::text[],false,105),
('javascript','objects','javascript-objects-106','How do ES6 classes relate to JavaScript''s prototype-based inheritance?','ES6 class syntax is primarily syntactic sugar over the existing prototype-based inheritance model — methods defined in a class body are added to the class''s prototype object, not to each instance. Under the hood, class Dog extends Animal still sets up a prototype chain: Dog.prototype''s [[Prototype]] is Animal.prototype. Classes don''t introduce a fundamentally new inheritance model, just a cleaner syntax on top of the existing one.',null,null,null,'medium',ARRAY['javascript','objects','classes']::text[],false,106),
('javascript','objects','javascript-objects-107','What are private class fields and how do you declare one?','Private class fields, prefixed with #, are properties that can only be accessed from within the class body itself — not from outside instances or subclasses. They were standardized in ES2022 and provide true encapsulation, unlike the older convention of prefixing a property with an underscore, which is just a naming convention with no actual enforcement.',null,'class Counter {
  #count = 0;
  increment() { return ++this.#count; }
}
const c = new Counter();
c.increment(); // 1','javascript','medium',ARRAY['javascript','objects','classes']::text[],true,107),
('javascript','objects','javascript-objects-108','What are static class members and when are they useful?','Static members are declared with the static keyword and belong to the class itself rather than to instances — they''re accessed as ClassName.member rather than instance.member. They''re useful for utility/factory methods, constants, or counters that logically relate to the class as a whole rather than any particular instance.',null,'class MathUtils {
  static PI = 3.14159;
  static square(n) { return n * n; }
}
MathUtils.square(4); // 16','javascript','easy',ARRAY['javascript','objects','classes']::text[],false,108),
('javascript','objects','javascript-objects-109','How do you define getters and setters inside a class?','Getters and setters are declared with the get and set keywords before a method name, and they let a property look like a plain field from the outside while running custom logic on read or write. They''re commonly used for computed properties or to add validation when a property is assigned.',null,'class Circle {
  constructor(radius) { this._radius = radius; }
  get area() { return Math.PI * this._radius ** 2; }
  set radius(r) { if (r > 0) this._radius = r; }
}','javascript','easy',ARRAY['javascript','objects','classes']::text[],false,109),
('javascript','objects','javascript-objects-110','What are computed property names in object literals?','Computed property names let you use a bracketed expression as an object key at creation time, so the actual key name can be determined dynamically at runtime rather than being a static identifier. This is especially useful when building objects keyed by a variable or function result.',null,'const key = ''score'';
const obj = { [key]: 100 }; // { score: 100 }','javascript','easy',ARRAY['javascript','objects','es6']::text[],false,110),
('javascript','objects','javascript-objects-111','What does Object.defineProperty() let you control that a normal assignment doesn''t?','Object.defineProperty() lets you precisely configure a property''s descriptor: whether it''s writable, enumerable (shows up in for...in/Object.keys), and configurable (can be redefined or deleted), or define it as an accessor with get/set functions. A plain assignment always creates a writable, enumerable, configurable property, so defineProperty is needed for anything more restrictive.',null,'const obj = {};
Object.defineProperty(obj, ''id'', { value: 1, writable: false, enumerable: false });','javascript','hard',ARRAY['javascript','objects']::text[],false,111),
('javascript','objects','javascript-objects-112','What is the difference between hasOwnProperty() and the in operator?','obj.hasOwnProperty(key) checks only the object''s own properties, ignoring the prototype chain. The in operator checks both own properties and inherited ones from the entire prototype chain. So ''toString'' in {} is true (inherited from Object.prototype), but {}.hasOwnProperty(''toString'') is false.',null,null,null,'medium',ARRAY['javascript','objects','prototype']::text[],true,112),
('javascript','objects','javascript-objects-113','How do you correctly compare two objects for equality in JavaScript?','Both == and === compare objects by reference, not by their contents, so two objects with identical properties are never === unless they''re literally the same reference. To compare structural equality you need a deep-equality check — either a manual recursive comparison, JSON.stringify() for simple cases (with caveats around key order and unsupported types), or a library like lodash''s isEqual.',null,null,null,'medium',ARRAY['javascript','objects']::text[],false,113),
('javascript','objects','javascript-objects-114','What is structuredClone() and how does it differ from JSON-based deep cloning?','structuredClone() is a built-in browser/Node API that performs a true deep clone of an object, correctly handling Dates, Maps, Sets, ArrayBuffers, and circular references. The older JSON.parse(JSON.stringify(obj)) trick fails on those cases — it silently drops functions and undefined, breaks Dates into strings, and throws on circular references.',null,'const clone = structuredClone({ date: new Date(), nested: { a: 1 } });','javascript','medium',ARRAY['javascript','objects']::text[],false,114),
('javascript','objects','javascript-objects-115','When would you use a Map instead of a plain object?','Map is preferable when keys aren''t simple strings (Map allows objects, functions, or any value as a key), when insertion order matters for iteration (which Map guarantees), when you need a reliable .size, or when you''re frequently adding/removing keys, since Map doesn''t carry inherited prototype properties that could collide with data. Plain objects remain fine for simple, known-shape records.',null,null,null,'medium',ARRAY['javascript','objects']::text[],true,115),
('javascript','objects','javascript-objects-116','Why would you use a Set instead of an array to track unique values?','A Set automatically enforces uniqueness — adding a duplicate value is a no-op — and its .has() lookup is O(1) on average versus an array''s O(n) .includes() scan. This makes Set the natural choice for deduplication and fast membership checks, though arrays remain better when you need ordering by index or duplicate values.',null,'const unique = [...new Set([1, 2, 2, 3])]; // [1, 2, 3]','javascript','easy',ARRAY['javascript','objects']::text[],false,116),
('javascript','objects','javascript-objects-117','What problem do WeakMap and WeakSet solve?','WeakMap and WeakSet hold their keys (WeakMap) or values (WeakSet) weakly, meaning those references don''t prevent garbage collection — once nothing else references an object used as a key, it (and its associated value) can be collected. This makes them ideal for associating metadata with objects (like caching or private data) without causing memory leaks by keeping objects alive indefinitely.',null,null,null,'hard',ARRAY['javascript','objects','memory']::text[],false,117),
('javascript','objects','javascript-objects-118','What is a mixin in JavaScript and how is it typically implemented?','A mixin is a pattern for sharing reusable behavior across classes that don''t share a common ancestor, working around JavaScript''s lack of multiple inheritance. It''s commonly implemented as a function that takes a base class and returns a new subclass with additional methods mixed in, allowing you to compose several mixins onto one class.',null,'const Serializable = (Base) => class extends Base {
  serialize() { return JSON.stringify(this); }
};
class Model extends Serializable(Object) {}','javascript','hard',ARRAY['javascript','objects','patterns']::text[],false,118),
('javascript','objects','javascript-objects-119','How does the instanceof operator actually work?','obj instanceof Constructor checks whether Constructor.prototype appears anywhere in obj''s prototype chain, not whether obj was literally created by that constructor. This means you can make instanceof return true or false in unexpected ways by manually altering the prototype chain, and it doesn''t work reliably across different realms (e.g., iframes) since each has its own constructor identity.',null,null,null,'medium',ARRAY['javascript','objects','prototype']::text[],false,119),
('javascript','objects','javascript-objects-120','How do you make a custom object iterable with for...of?','You implement the Symbol.iterator method on the object, returning an iterator object with a next() method that yields { value, done } pairs. Once an object has this method, it can be used directly with for...of, spread syntax, and destructuring.',null,'const range = {
  from: 1, to: 3,
  [Symbol.iterator]() {
    let cur = this.from, last = this.to;
    return { next: () => cur <= last ? { value: cur++, done: false } : { done: true } };
  }
};
[...range]; // [1, 2, 3]','javascript','hard',ARRAY['javascript','objects','iterators']::text[],false,120),
('javascript','objects','javascript-objects-121','What''s the difference between spreading an object ({...obj}) and Object.assign({}, obj)?','Functionally they both produce a shallow copy merged into a new object, and in most cases are interchangeable. Object spread is generally considered more readable and slightly faster in modern engines, while Object.assign is still useful when the set of source objects is dynamic (an array of objects) since it can be called with apply or spread arguments itself.',null,null,null,'easy',ARRAY['javascript','objects','es6']::text[],false,121),
('javascript','objects','javascript-objects-122','What are common pitfalls when serializing objects to JSON?','JSON.stringify() silently omits properties whose value is undefined, a function, or a Symbol; it converts Date objects to ISO strings (losing the Date type on parse); and it throws a TypeError on circular references unless you supply a custom replacer function. NaN and Infinity are serialized as null, which can silently corrupt numeric data.',null,null,null,'medium',ARRAY['javascript','objects','json']::text[],false,122),
('javascript','objects','javascript-objects-123','What is property shorthand syntax in object literals?','When a variable''s name matches the key you want in an object literal, you can write just the variable name instead of key: value. This reduces repetition and is extremely common when returning multiple values from a function as an object.',null,'const name = ''Amy'', age = 30;
const user = { name, age }; // same as { name: name, age: age }','javascript','easy',ARRAY['javascript','objects','es6']::text[],false,123),
('javascript','objects','javascript-objects-124','How does optional chaining interact with method calls?','obj?.method?.() calls method only if both obj and obj.method are not null/undefined, short-circuiting to undefined otherwise instead of throwing a TypeError. This is especially useful for calling optional callback props or methods on objects that might not have been initialized yet.',null,'user.onLogin?.(); // only calls onLogin if it exists','javascript','easy',ARRAY['javascript','objects','es6']::text[],false,124),
('javascript','objects','javascript-objects-125','Does Object.freeze() perform a deep freeze?','No — Object.freeze() only freezes the object''s own top-level properties; any nested objects remain fully mutable. To achieve a deep freeze you need to recursively freeze each nested object yourself, which is a common gotcha when developers assume immutability extends further than it does.',null,null,null,'medium',ARRAY['javascript','objects']::text[],true,125),
('javascript','objects','javascript-objects-126','How does the super keyword work in class inheritance?','Inside a subclass constructor, super(...) calls the parent class''s constructor and must be called before this can be used. Inside a method, super.methodName() calls the parent class''s version of that method, which is useful for extending rather than fully replacing inherited behavior.',null,'class Animal {
  speak() { return ''generic sound''; }
}
class Dog extends Animal {
  speak() { return super.speak() + '' (barks)''; }
}','javascript','medium',ARRAY['javascript','objects','classes']::text[],false,126),
('javascript','objects','javascript-objects-127','How do you simulate an abstract class in JavaScript, which has no built-in abstract keyword?','A common pattern is to check in the base class''s constructor whether new.target === BaseClass and throw an error if so, preventing direct instantiation. Methods meant to be ''abstract'' can throw an error like ''must be implemented by subclass'' if not overridden, giving a runtime approximation of an abstract contract.',null,null,null,'hard',ARRAY['javascript','objects','classes','patterns']::text[],false,127),
('javascript','objects','javascript-objects-128','What is method overriding in JavaScript classes?','Method overriding happens when a subclass defines a method with the same name as one on its parent class, replacing the inherited implementation for instances of the subclass. Unlike some languages, JS doesn''t require any special keyword or check signature compatibility — any method name can simply be redefined.',null,null,null,'easy',ARRAY['javascript','objects','classes']::text[],false,128),
('javascript','objects','javascript-objects-129','Why is composition often preferred over inheritance in JavaScript?','Composition — building objects by combining smaller, focused pieces of behavior — tends to produce more flexible code than deep inheritance hierarchies, which can become rigid and hard to change as a codebase grows (the fragile base class problem). JS''s functions-as-values and object literals make composition (passing behavior in, combining small objects) especially natural compared to class-based inheritance chains.',null,null,null,'medium',ARRAY['javascript','objects','patterns']::text[],false,129),
('javascript','objects','javascript-objects-130','How do toString() and valueOf() affect type coercion of objects?','When an object is used in a context expecting a primitive (like string concatenation or arithmetic), JS calls valueOf() first for numeric contexts and toString() first for string contexts (this is now more precisely governed by Symbol.toPrimitive if defined). Overriding these methods lets you control how a custom object behaves when coerced, e.g., in template literals or comparisons.',null,'class Money {
  constructor(cents) { this.cents = cents; }
  valueOf() { return this.cents; }
}
new Money(500) + new Money(250); // 750','javascript','hard',ARRAY['javascript','objects','coercion']::text[],false,130),
('javascript','objects','javascript-objects-131','What is a discriminated union pattern using plain objects, and why is it useful?','It''s a pattern where related object shapes share a common ''tag'' or ''type'' field whose value determines which other fields are present, letting code branch (often with a switch) on that field to safely narrow the shape. It''s commonly used to model state machines or API responses (e.g. { status: ''loading'' } vs { status: ''success'', data } vs { status: ''error'', error }) in a self-describing way.',null,null,null,'medium',ARRAY['javascript','objects','patterns']::text[],false,131),
('javascript','objects','javascript-objects-132','How can you enforce immutability in JavaScript without an external library?','Combine Object.freeze() (applied recursively for deep immutability) with consistently returning new objects/arrays instead of mutating in place (using spread syntax or array methods like map/filter that don''t mutate). This convention-plus-freeze approach mimics immutable data structures without needing a library like Immutable.js, though it doesn''t give you the structural-sharing performance benefits those libraries provide.',null,null,null,'medium',ARRAY['javascript','objects']::text[],false,132),
('javascript','objects','javascript-objects-133','What does it mean for an object property to be ''enumerable''?','Enumerable properties show up in for...in loops, Object.keys(), Object.entries(), and JSON.stringify() output; non-enumerable ones (like most built-in methods on Object.prototype, or properties defined via defineProperty without enumerable: true) are hidden from those but still directly accessible. This distinction lets built-in and library code attach ''hidden'' metadata to objects without polluting normal iteration.',null,null,null,'hard',ARRAY['javascript','objects']::text[],false,133),
('javascript','objects','javascript-objects-134','What is the Reflect object used for?','Reflect provides methods that mirror many object-level operations (like Reflect.get, Reflect.set, Reflect.ownKeys, Reflect.deleteProperty) as regular functions with consistent, predictable return values, rather than operators or statements that can throw or behave inconsistently. It''s most commonly used alongside Proxy, where trap handlers often forward to the corresponding Reflect method for default behavior.',null,null,null,'hard',ARRAY['javascript','objects','reflect']::text[],false,134),
('javascript','objects','javascript-objects-135','What does Object.fromEntries() do?','Object.fromEntries() is the inverse of Object.entries() — it builds a plain object from an iterable of [key, value] pairs, such as an array of entries or a Map. It''s commonly used to convert a Map back into a plain object, or to transform an object''s entries with map/filter and rebuild a new object from the result.',null,'Object.fromEntries([[''a'', 1], [''b'', 2]]); // { a: 1, b: 2 }','javascript','easy',ARRAY['javascript','objects','es6']::text[],false,135),
('javascript','objects','javascript-objects-136','What are the basic traps a Proxy can intercept, and what is a Proxy used for?','A Proxy wraps a target object and lets you intercept fundamental operations via ''traps'' — most commonly get (property read), set (property write), has (the in operator), and deleteProperty. Proxies are used for validation, logging/debugging property access, creating reactive objects (as Vue''s reactivity system does), or implementing virtual/computed properties.',null,'const logged = new Proxy({}, {
  set(target, key, value) { console.log(`set ${key}`); target[key] = value; return true; }
});
logged.x = 5; // logs ''set x''','javascript','hard',ARRAY['javascript','objects','proxy']::text[],false,136),
('javascript','objects','javascript-objects-137','What is the difference between Object.seal() and Object.preventExtensions()?','Object.preventExtensions() only stops new properties from being added, but existing ones can still be modified or deleted. Object.seal() goes further — it also marks all existing properties as non-configurable (so they can''t be deleted or reconfigured, though writable ones can still have their value changed), sitting between preventExtensions and the fully locked-down freeze.',null,null,null,'hard',ARRAY['javascript','objects']::text[],false,137),
('javascript','objects','javascript-objects-138','What is duck typing and how does it relate to polymorphism in JavaScript?','Duck typing means code cares only about whether an object has the methods/properties it needs at the moment it''s used (''if it walks like a duck and quacks like a duck...''), rather than its declared type or class. Because JavaScript is dynamically typed, this enables a lightweight form of polymorphism — different objects can be used interchangeably anywhere they implement the expected shape, without needing a shared base class or interface.',null,null,null,'medium',ARRAY['javascript','objects','patterns']::text[],false,138),
('javascript','objects','javascript-objects-139','What is method chaining and how do you implement a fluent interface?','Method chaining lets you call multiple methods on the same object in a single expression (obj.a().b().c()), which is achieved simply by having each method return this (or a new instance of the same type) instead of undefined. It''s commonly seen in builder patterns, query builders, and libraries like jQuery or array methods that return arrays.',null,'class QueryBuilder {
  where(cond) { this.conditions = cond; return this; }
  build() { return `WHERE ${this.conditions}`; }
}
new QueryBuilder().where(''id=1'').build();','javascript','easy',ARRAY['javascript','objects','patterns']::text[],false,139),
('javascript','objects','javascript-objects-140','How would you implement a simple object pool, and why might you need one?','An object pool pre-allocates and reuses a fixed set of objects instead of constantly creating and discarding them, which reduces garbage collection pressure in performance-sensitive code like games or high-frequency event handling. It typically exposes acquire() (returns a free object from the pool, creating one if needed) and release(obj) (returns the object to the pool for reuse) methods.',null,null,null,'hard',ARRAY['javascript','objects','performance']::text[],false,140),
('javascript','objects','javascript-objects-141','How do you clone a class instance while preserving its prototype (and thus its methods)?','A plain spread ({...instance}) or Object.assign({}, instance) copies own properties but loses the prototype, turning the result into a plain object without the class''s methods. To preserve the prototype, use Object.create(Object.getPrototypeOf(instance), Object.getOwnPropertyDescriptors(instance)), or simply pass the instance''s properties into new instance.constructor(...) if the constructor supports it.',null,null,null,'hard',ARRAY['javascript','objects','classes']::text[],false,141),
('javascript','objects','javascript-objects-142','Does JavaScript guarantee the iteration order of object properties?','Mostly yes, per the ES2015+ specification: integer-like keys are iterated first in ascending numeric order, followed by string keys in insertion order, followed by Symbol keys in insertion order. This is a common point of confusion since older mental models assumed object key order was entirely unspecified.',null,null,null,'hard',ARRAY['javascript','objects']::text[],false,142),
('javascript','objects','javascript-objects-143','How can you use a plain object or Map to memoize a function''s results?','Memoization caches a function''s return value keyed by its arguments (often serialized to a string, or used directly as a Map key for object/array arguments) so that a repeated call with the same input returns the cached result instead of recomputing. This trades memory for speed and is especially effective for expensive, pure (side-effect-free) computations.',null,'function memoize(fn) {
  const cache = new Map();
  return (arg) => {
    if (cache.has(arg)) return cache.get(arg);
    const result = fn(arg);
    cache.set(arg, result);
    return result;
  };
}','javascript','medium',ARRAY['javascript','objects','performance']::text[],false,143),
('javascript','objects','javascript-objects-144','What is the difference between Object.is() and the === operator?','Object.is() behaves like === for almost all values, but corrects two edge cases: Object.is(NaN, NaN) is true (whereas NaN === NaN is false), and Object.is(0, -0) is false (whereas 0 === -0 is true). It''s mainly used internally by React and other libraries for precise equality checks, and rarely needed in everyday application code.',null,'Object.is(NaN, NaN); // true
NaN === NaN; // false','javascript','medium',ARRAY['javascript','objects']::text[],false,144),
('javascript','objects','javascript-objects-145','How do you declare a private method inside a class?','Prefix the method name with # just like a private field: #helper() { ... }. It can only be called from within the class body (this.#helper()), and attempting to access it from outside — even via bracket notation — throws a syntax/reference error, giving genuine encapsulation rather than convention-based privacy.',null,'class Auth {
  #hash(password) { return password.split('''').reverse().join(''''); }
  login(password) { return this.#hash(password) === this.storedHash; }
}','javascript','medium',ARRAY['javascript','objects','classes']::text[],false,145),
('javascript','objects','javascript-objects-146','Can static fields be private, and what''s a use case?','Yes — combining static and # (e.g. static #instances = 0) creates a private field shared across the class itself rather than instances, inaccessible from outside. A common use case is a private static counter tracking how many instances have been created, exposed only through a public static getter.',null,'class Widget {
  static #count = 0;
  constructor() { Widget.#count++; }
  static get count() { return Widget.#count; }
}','javascript','medium',ARRAY['javascript','objects','classes']::text[],false,146),
('javascript','objects','javascript-objects-147','Why might you validate input inside a setter rather than in the constructor alone?','Validating in a setter ensures the invariant holds not just at construction time but every time the property is reassigned later in the object''s lifetime, since the constructor typically delegates to the same setter (this.radius = radius) rather than duplicating the check. This centralizes validation logic in one place instead of scattering it across every assignment site.',null,'class Circle {
  set radius(r) {
    if (r <= 0) throw new Error(''radius must be positive'');
    this._radius = r;
  }
}','javascript','medium',ARRAY['javascript','objects','classes']::text[],false,147),
('javascript','objects','javascript-objects-148','What''s the risk of using object keys derived from user input without sanitization?','If user input is used directly as an object key without care, it can collide with inherited properties like __proto__, constructor, or toString, potentially leading to prototype pollution — where an attacker manipulates an object''s prototype to affect unrelated code. Using a Map (which has no prototype pollution risk) or Object.create(null) for such lookup tables avoids this class of bug entirely.',null,null,null,'hard',ARRAY['javascript','objects','security']::text[],false,148),
('javascript','objects','javascript-objects-149','What is the difference between a plain object literal and a class instance in terms of underlying representation?','Both are ultimately objects with an internal prototype link — a class instance''s [[Prototype]] points to the class''s prototype (carrying its methods), while an object literal''s [[Prototype]] points directly to Object.prototype by default. Functionally, a class is really just a more structured, conventionalized way to produce objects with a shared prototype and consistent initialization via the constructor.',null,null,null,'medium',ARRAY['javascript','objects','classes']::text[],false,149),
('javascript','objects','javascript-objects-150','How would you deeply merge two nested objects, unlike Object.assign''s shallow merge?','A deep merge recursively walks both objects, and whenever a key exists in both and both values are plain objects, it merges them recursively instead of letting one simply overwrite the other; for non-object values, the source typically takes precedence. There''s no built-in deep merge in JS, so it''s either hand-written recursively or delegated to a utility library like lodash''s merge.',null,'function deepMerge(target, source) {
  for (const key in source) {
    if (source[key] instanceof Object && key in target) {
      Object.assign(source[key], deepMerge(target[key], source[key]));
    }
  }
  return { ...target, ...source };
}','javascript','medium',ARRAY['javascript','objects']::text[],false,150),
('react','advanced-react','react-advanced-react-101','How does React Suspense work for data fetching, beyond just lazy-loading components?','A data source that supports Suspense (like a framework''s data layer, or React''s own use() hook with a promise) can "throw" a pending promise during render, which tells React to pause that part of the tree and show the nearest Suspense boundary''s fallback until the promise resolves. This lets components read data as if it were already available, with the loading state handled declaratively by a wrapping <Suspense> instead of manual isLoading checks scattered through the component.',null,null,null,'hard',ARRAY['react','advanced','suspense']::text[],true,101),
('react','advanced-react','react-advanced-react-102','How should you decide where to place Suspense boundaries in a component tree?','A boundary placed too high shows a large, jarring loading fallback for the whole page even if only a small part is waiting on data; a boundary placed too low means every nested async component blocks its own tiny corner independently, which can look inconsistent. The common approach is to group logically-related content that should appear together behind one boundary, and let independent sections (like a sidebar versus a main content area) have their own separate boundaries so they can load and appear independently.',null,'<Suspense fallback={<PageSkeleton />}>
  <Header />
  <Suspense fallback={<SidebarSkeleton />}>
    <Sidebar />
  </Suspense>
  <MainContent />
</Suspense>','jsx','medium',ARRAY['react','advanced','suspense']::text[],false,102),
('react','advanced-react','react-advanced-react-103','What does "concurrent" mean when people describe React 18 as a concurrent renderer?','Concurrent doesn''t mean multi-threaded — React still runs on a single thread. It means React can start rendering an update, pause partway through, work on something more urgent instead, and come back to (or discard) the paused render later, rather than always running a render to completion once started, the way React''s original synchronous renderer worked.',null,null,null,'hard',ARRAY['react','advanced','concurrent-rendering']::text[],false,103),
('react','advanced-react','react-advanced-react-104','What is the difference between hydration and a full client-side render?','A full client-side render builds the DOM from scratch in the browser using JavaScript. Hydration takes HTML that was already rendered (on the server or at build time) and attaches React''s event listeners and internal state to that existing markup without re-creating the DOM nodes, so the page appears instantly while React "wakes up" the already-visible content and makes it interactive.',null,null,null,'medium',ARRAY['react','advanced','hydration']::text[],false,104),
('react','advanced-react','react-advanced-react-105','What is islands architecture / partial hydration, at a high level?','Instead of hydrating an entire page''s worth of React as one unit, islands architecture ships and hydrates only the small, genuinely interactive pieces of a page (like a like-button or a carousel) independently, while the rest of the page stays static HTML with no JavaScript attached at all. This is a framework-agnostic pattern aimed at pages that are mostly static content with only a few interactive widgets, minimizing the amount of JS shipped and hydrated.',null,null,null,'hard',ARRAY['react','advanced','hydration']::text[],false,105),
('react','advanced-react','react-advanced-react-106','What are React Server Components and how do they differ from traditional server-side rendering?','Server Components run exclusively on the server (or at build time) and never ship their code to the client at all — not even for hydration — whereas traditional SSR renders HTML on the server but still sends the full component JavaScript to the browser so it can hydrate. Server Components can also directly access server-only resources (a database, the filesystem) without an API layer, and can be mixed with regular Client Components for the interactive parts of a page.',null,null,null,'hard',ARRAY['react','advanced','server-components']::text[],true,106),
('react','advanced-react','react-advanced-react-107','How would you implement the children-as-a-function (render props) pattern?','Instead of accepting a static children element, the component calls the children prop as a function during its own render, passing it internal state or data the caller needs. This lets the parent component own some shared logic (like tracking mouse position or a data subscription) while giving the consumer full control over what markup to render with that data.',null,'function MouseTracker({ children }) {
  const [pos, setPos] = useState({ x: 0, y: 0 });
  return (
    <div onMouseMove={(e) => setPos({ x: e.clientX, y: e.clientY })}>
      {children(pos)}
    </div>
  );
}

<MouseTracker>{(pos) => <p>{pos.x}, {pos.y}</p>}</MouseTracker>','jsx','medium',ARRAY['react','advanced','render-props']::text[],false,107),
('react','advanced-react','react-advanced-react-108','How do compound components use Context internally to share implicit state between siblings?','A compound component (like <Tabs><Tabs.List><Tabs.Tab /></Tabs.List></Tabs>) sets up a Context provider in its root component to hold shared state (like the currently active tab), and each child subcomponent reads that Context internally rather than receiving the state as an explicit prop. This gives consumers a clean, declarative JSX API while the components coordinate behind the scenes.',null,'const TabsContext = createContext();
function Tabs({ children }) {
  const [active, setActive] = useState(0);
  return <TabsContext.Provider value={{ active, setActive }}>{children}</TabsContext.Provider>;
}
function Tab({ index, children }) {
  const { active, setActive } = useContext(TabsContext);
  return <button onClick={() => setActive(index)}>{children}</button>;
}','jsx','medium',ARRAY['react','advanced','compound-components']::text[],false,108),
('react','advanced-react','react-advanced-react-109','Why do events triggered inside a Portal still bubble up through the React component tree instead of the DOM tree?','React maintains its own synthetic event system layered on top of the DOM, and it dispatches bubbling events based on the React component tree (where the Portal''s content was logically rendered), not the actual DOM parent it was inserted into. This means a click inside a modal rendered via a portal into document.body will still trigger onClick handlers on its logical React ancestors, even though those ancestors aren''t its DOM ancestors.',null,null,null,'medium',ARRAY['react','advanced','portals']::text[],false,109),
('react','advanced-react','react-advanced-react-110','What kinds of errors do React error boundaries NOT catch?','Error boundaries only catch errors thrown during rendering, in lifecycle methods, and in constructors of the tree below them. They do not catch errors inside event handlers (those need a regular try/catch), errors in asynchronous code like setTimeout or promise callbacks, errors during server-side rendering, or errors thrown in the error boundary''s own code.',null,null,null,'medium',ARRAY['react','advanced','error-boundaries']::text[],true,110),
('react','advanced-react','react-advanced-react-111','How would you let a user recover from an error caught by an error boundary, instead of leaving them stuck on a fallback UI?','The error boundary''s fallback UI can include a "try again" button that resets the boundary''s internal hasError state, which causes React to attempt rendering the children again — useful if the error was transient (like a flaky network request). For errors tied to specific data (like a broken route), the reset can also be tied to a key change so navigating away and back gets a completely fresh boundary instance.',null,'class ErrorBoundary extends React.Component {
  state = { hasError: false };
  static getDerivedStateFromError() { return { hasError: true }; }
  render() {
    if (this.state.hasError) {
      return <button onClick={() => this.setState({ hasError: false })}>Try again</button>;
    }
    return this.props.children;
  }
}','jsx','medium',ARRAY['react','advanced','error-boundaries']::text[],false,111),
('react','advanced-react','react-advanced-react-112','How can the key prop be used as an advanced reset mechanism beyond simple lists?','Changing a key anywhere — not just in a list — tells React to treat the element as a completely new instance rather than updating the existing one, discarding all of its state, refs, and effects. This is a useful trick for resetting a complex form or wizard when switching between unrelated records, without manually resetting every individual field.',null,'<EditForm key={selectedRecord.id} record={selectedRecord} />','jsx','medium',ARRAY['react','advanced','key']::text[],false,112),
('react','advanced-react','react-advanced-react-113','How would you apply the controlled/uncontrolled pattern when designing a reusable library component?','A well-designed reusable component (like a dropdown or accordion) usually supports both modes: it manages its own internal state by default (uncontrolled, easy for basic usage), but accepts optional value and onChange props that, when provided, let the parent fully control the state instead. This dual API is common in component libraries because it serves simple use cases out of the box while still giving advanced consumers full control when they need it.',null,'function Toggle({ value, onChange, defaultValue = false }) {
  const [internal, setInternal] = useState(defaultValue);
  const isControlled = value !== undefined;
  const isOn = isControlled ? value : internal;
  const toggle = () => isControlled ? onChange(!isOn) : setInternal((v) => !v);
  return <button onClick={toggle}>{isOn ? ''On'' : ''Off''}</button>;
}','jsx','hard',ARRAY['react','advanced','component-design']::text[],false,113),
('react','advanced-react','react-advanced-react-114','How would you build a custom hook that wraps a third-party imperative API (like a chart library or a map SDK)?','The hook typically creates the imperative instance inside a useEffect (or useLayoutEffect if it touches layout) tied to a ref pointing at a DOM container, exposes an imperative-to-declarative bridge by updating the instance whenever relevant React state/props change, and tears the instance down in the effect''s cleanup function to avoid leaking it on unmount or re-initialization.',null,'function useChart(containerRef, data) {
  useEffect(() => {
    const chart = new ChartLib(containerRef.current);
    chart.render(data);
    return () => chart.destroy();
  }, [data]);
}','jsx','medium',ARRAY['react','advanced','custom-hooks']::text[],false,114),
('react','advanced-react','react-advanced-react-115','How does ref forwarding work through multiple layers of wrapping components?','By default, a ref passed to a custom component doesn''t automatically attach to a DOM node inside it, because refs aren''t part of the normal props flow. forwardRef lets a component explicitly accept a ref as a second argument and forward it to whichever inner DOM node or child it chooses, and this can be chained through several nested wrapper components as long as each one also forwards the ref it receives.',null,'const FancyInput = forwardRef((props, ref) => (
  <input ref={ref} className="fancy" {...props} />
));

const inputRef = useRef(null);
<FancyInput ref={inputRef} />;','jsx','medium',ARRAY['react','advanced','refs']::text[],false,115),
('react','advanced-react','react-advanced-react-116','How does combining the Provider pattern with a custom hook create a common library-authoring idiom?','A Context Provider supplies shared state to a subtree, and a paired custom hook (like useAuth() or useTheme()) wraps useContext to both read that value and throw a helpful error if it''s called outside the Provider — giving consumers a clean, self-documenting API instead of importing and using the raw Context object directly everywhere.',null,'const AuthContext = createContext(null);
export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error(''useAuth must be used within AuthProvider'');
  return ctx;
}','jsx','medium',ARRAY['react','advanced','context']::text[],true,116),
('react','advanced-react','react-advanced-react-117','What problem did React''s fiber architecture solve compared to the older stack reconciler?','The original "stack" reconciler processed the entire component tree synchronously and couldn''t be paused once started, which could block the main thread long enough to make an app feel unresponsive during large updates. Fiber restructured reconciliation into units of work that can be paused, resumed, prioritized, or abandoned, which is the foundation that makes features like concurrent rendering, Suspense, and useTransition possible.',null,null,null,'hard',ARRAY['react','advanced','fiber']::text[],true,117),
('react','advanced-react','react-advanced-react-118','What is time slicing in the context of React''s concurrent features?','Time slicing is the technique of breaking rendering work into small chunks and yielding control back to the browser between chunks, so the main thread stays free to handle higher-priority work like user input or animation frames instead of being monopolized by a single long render. It''s what allows React to render a large update "in the background" without freezing the page.',null,null,null,'hard',ARRAY['react','advanced','concurrent-rendering']::text[],false,118),
('react','advanced-react','react-advanced-react-119','Why does React avoid synchronous rendering that blocks the main thread for large updates?','Because JavaScript in the browser runs on a single thread shared with layout, painting, and input handling, a long synchronous render blocks all of that, making the page feel frozen and unresponsive to clicks or typing during the update. Concurrent rendering exists specifically to let React interrupt a big render to handle urgent input first, keeping the app feeling responsive even while a large update is still in progress.',null,null,null,'medium',ARRAY['react','advanced','concurrent-rendering']::text[],false,119),
('react','advanced-react','react-advanced-react-120','Why does React''s Strict Mode intentionally invoke component functions and effects twice in development?','Double-invoking helps surface bugs caused by impure render logic or missing effect cleanup — if a render function or an effect isn''t idempotent (e.g. it mutates something outside its scope, or an effect forgets to clean up a subscription before running again), running it twice makes the bug visible immediately in development instead of only appearing later under concurrent rendering in production. It only happens in development builds and has no effect on production behavior.',null,null,null,'medium',ARRAY['react','advanced','strict-mode']::text[],false,120),
('react','advanced-react','react-advanced-react-121','How would you approach testing an error boundary?','Render a component tree with the error boundary wrapping a deliberately-throwing child (a small test-only component that throws in its render), then assert that the fallback UI appears instead of the app crashing. Since React logs errors to the console during this, tests typically suppress or spy on console.error for that specific test to keep output clean, while still asserting the boundary''s behavior.',null,'function Bomb() { throw new Error(''boom''); }

test(''shows fallback on error'', () => {
  render(<ErrorBoundary><Bomb /></ErrorBoundary>);
  expect(screen.getByText(/something went wrong/i)).toBeInTheDocument();
});','jsx','medium',ARRAY['react','advanced','testing']::text[],false,121),
('react','advanced-react','react-advanced-react-122','What are the key considerations when building an accessible modal using a Portal?','Beyond rendering the modal outside the normal DOM flow via a portal, an accessible modal needs to trap keyboard focus inside itself while open (so Tab doesn''t escape to the page behind it), return focus to the triggering element on close, be dismissible via the Escape key, and use appropriate ARIA attributes (role="dialog", aria-modal="true") so assistive technology announces it correctly.',null,null,null,'hard',ARRAY['react','advanced','accessibility']::text[],false,122),
('react','advanced-react','react-advanced-react-123','What is the "lifting content up" pattern, and how does it differ from passing configuration objects as props?','Instead of a component accepting a configuration prop describing what to render (like a headerConfig object with a title and icon name), "lifting content up" has the parent pass actual JSX as a prop or children, giving the parent full flexibility over markup and behavior without the child needing to anticipate every possible configuration. It trades some structure/type-safety for significantly more composability.',null,'// Configuration object — child must know every possible shape
<Card header={{ title: ''Stats'', icon: ''chart'' }} />

// Lifted content — parent has full control
<Card header={<h2><ChartIcon /> Stats</h2>} />','jsx','medium',ARRAY['react','advanced','component-design']::text[],false,123),
('react','advanced-react','react-advanced-react-124','Why did the React ecosystem largely move from HOCs and render props to hooks?','HOCs and render props both share stateful logic by wrapping components, which adds extra layers to the component tree ("wrapper hell"), makes props harder to trace back to their source, and can create naming collisions between multiple HOCs. Hooks let you extract and reuse the exact same stateful logic as a plain function call inside a component, with no extra nesting, clearer data flow, and props/types that are easy to trace directly.',null,null,null,'medium',ARRAY['react','advanced','hooks']::text[],false,124),
('react','advanced-react','react-advanced-react-125','How would you build a reusable useFetch custom hook that wraps fetch with loading and error state?','The hook wraps a fetch call in a useEffect keyed on the URL, tracks loading/data/error in state, and — critically — checks a "still relevant" flag or uses an AbortController in the cleanup function so a stale response from a superseded request doesn''t overwrite state after the component has moved on to a new URL or unmounted.',null,'function useFetch(url) {
  const [state, setState] = useState({ data: null, loading: true, error: null });
  useEffect(() => {
    let active = true;
    setState((s) => ({ ...s, loading: true }));
    fetch(url).then((r) => r.json())
      .then((data) => active && setState({ data, loading: false, error: null }))
      .catch((error) => active && setState({ data: null, loading: false, error }));
    return () => { active = false; };
  }, [url]);
  return state;
}','jsx','medium',ARRAY['react','advanced','custom-hooks']::text[],true,125),
('react','advanced-react','react-advanced-react-126','How would you avoid "wrapper hell" when a component needs several cross-cutting concerns from multiple HOCs?','Composing several HOCs (withAuth(withTheme(withLogging(Component)))) creates deep, hard-to-debug nesting in the React tree and in the props chain. Converting each HOC''s logic into a custom hook and calling all of them directly inside a single component — useAuth(), useTheme(), useLogging() — achieves the same functionality flat, with each concern independently visible and no extra component layers.',null,null,null,'medium',ARRAY['react','advanced','hoc']::text[],false,126),
('react','advanced-react','react-advanced-react-127','How does the key prop interact with list reordering when combined with animation libraries?','Animation libraries that animate list reordering (like sliding items into their new position) rely on stable keys to know that an item at a new index is actually the same logical item that moved, rather than a different item that happened to land there. If keys aren''t stable (e.g. using array index), the library will animate the wrong items or fail to animate the move at all, since it can''t tell which DOM node corresponds to which piece of data across the reorder.',null,null,null,'medium',ARRAY['react','advanced','key']::text[],false,127),
('react','advanced-react','react-advanced-react-128','What does streaming SSR mean, and what problem does it solve compared to traditional SSR?','Traditional SSR waits until the entire page''s HTML is generated on the server before sending any of it to the browser, so a single slow data dependency delays the whole response. Streaming SSR sends HTML in chunks as it becomes ready — the shell and fast content arrive immediately while slower sections stream in afterward wrapped in Suspense boundaries — so users see and can interact with part of the page much sooner.',null,null,null,'hard',ARRAY['react','advanced','ssr']::text[],false,128),
('react','advanced-react','react-advanced-react-129','What is the difference between a Server Component and a Client Component in a framework that supports React Server Components?','Server Components render only on the server, can be async and read server-only resources directly, and produce no client-side JavaScript. Client Components (marked explicitly, e.g. with a "use client" directive) run in the browser, can use hooks like useState and useEffect, and handle interactivity — a typical app composes both, using Server Components for static/data-heavy parts of the tree and Client Components only where interactivity is actually needed.',null,null,null,'hard',ARRAY['react','advanced','server-components']::text[],false,129),
('react','advanced-react','react-advanced-react-130','How can you use useImperativeHandle to customize what a parent''s ref actually receives from a child?','By default, forwardRef exposes the raw underlying DOM node to the parent''s ref. useImperativeHandle lets the child instead expose a custom object with only specific methods it chooses to allow (like focus() or reset()), hiding the rest of its internals and giving the parent a deliberately limited imperative API rather than direct DOM access.',null,'const VideoPlayer = forwardRef((props, ref) => {
  const videoRef = useRef(null);
  useImperativeHandle(ref, () => ({
    play: () => videoRef.current.play(),
    pause: () => videoRef.current.pause(),
  }));
  return <video ref={videoRef} src={props.src} />;
});','jsx','hard',ARRAY['react','advanced','refs']::text[],false,130),
('react','advanced-react','react-advanced-react-131','What is the difference between the render props pattern and simply passing children?','Plain children are a static React element — whatever was passed is rendered as-is. Render props pass a function as children (or as another prop), which the component invokes during its own render and can supply arguments to, letting the consumer''s rendered output depend on internal state the component controls, something static children can''t do.',null,null,null,'easy',ARRAY['react','advanced','render-props']::text[],false,131),
('react','advanced-react','react-advanced-react-132','How would you implement a compound component that also supports an alternative flat/prop-driven API for simpler use cases?','The compound component''s root can accept optional props (like a tabs array) and, if provided, internally render the same subcomponents it would otherwise expect the consumer to compose manually — giving simple use cases a one-line API while still exposing the flexible <Tabs.Tab> composition for consumers who need custom markup per tab.',null,null,null,'hard',ARRAY['react','advanced','compound-components']::text[],false,132),
('react','advanced-react','react-advanced-react-133','Why can''t a Client Component directly import and render a Server Component as a child in frameworks that support RSC?','Once a component tree crosses into a Client Component, everything below it must also be capable of running in the browser, but Server Components are never sent to the client at all — so a Client Component can''t import one directly. The workaround is for a Server Component higher up the tree to render the Server Component and pass its already-rendered output down as the children prop to the Client Component, which the Client Component can then simply display.',null,null,null,'hard',ARRAY['react','advanced','server-components']::text[],false,133),
('react','advanced-react','react-advanced-react-134','What is a common gotcha when combining Suspense with data that depends on props that change frequently?','If a component wrapped by Suspense re-suspends every time its data-fetching key changes (e.g. a search query updating on every keystroke), the fallback UI can flash repeatedly instead of the previous content staying visible while new data loads. Wrapping the update that changes the key in useTransition (or using useDeferredValue) keeps the old content on screen and marks the pending state instead of immediately unmounting to the fallback.',null,null,null,'hard',ARRAY['react','advanced','suspense']::text[],false,134),
('react','advanced-react','react-advanced-react-135','How does React decide whether to reuse a DOM node or destroy and recreate it when the element type changes at the same position?','If two elements at the same position in the tree have different types (e.g. a <div> replaced by a <span>, or one custom component replaced by a different one), React tears down the entire old subtree — including its state and DOM nodes — and builds a fresh one, rather than trying to patch the differences. This is why conditionally rendering entirely different component types (instead of the same type with different props) resets any local state those components held.',null,null,null,'hard',ARRAY['react','advanced','reconciliation']::text[],false,135),
('react','advanced-react','react-advanced-react-136','What is the purpose of the use() hook introduced alongside Suspense-based data fetching?','use() lets a component read the value of a promise or a Context directly during render, suspending the component (via Suspense) if the promise hasn''t resolved yet. Unlike other hooks, it can be called conditionally, which makes it more flexible for reading async resources exactly where they''re needed rather than always at the top of a component.',null,'function Comments({ commentsPromise }) {
  const comments = use(commentsPromise);
  return <ul>{comments.map((c) => <li key={c.id}>{c.text}</li>)}</ul>;
}','jsx','hard',ARRAY['react','advanced','suspense']::text[],false,136),
('react','advanced-react','react-advanced-react-137','How would you design a component library''s theming system to support both a default theme and consumer overrides?','A common approach layers a ThemeProvider around the app supplying design tokens (colors, spacing, typography) via Context with sensible defaults, letting consumers override only the specific tokens they need by merging their partial theme object over the defaults, rather than requiring a full theme object to be supplied every time.',null,'const defaultTheme = { colors: { primary: ''#2563eb'' }, spacing: { sm: 8 } };
function ThemeProvider({ theme = {}, children }) {
  const merged = { ...defaultTheme, ...theme, colors: { ...defaultTheme.colors, ...theme.colors } };
  return <ThemeContext.Provider value={merged}>{children}</ThemeContext.Provider>;
}','jsx','medium',ARRAY['react','advanced','component-design']::text[],false,137),
('react','advanced-react','react-advanced-react-138','What is the difference between an error boundary catching a render error and a global window error handler?','A window.onerror or window.addEventListener(''error'', ...) handler catches uncaught errors anywhere in the page''s JavaScript, including outside React entirely, but can''t stop React from unmounting the broken tree or show a React-rendered fallback in its place. An error boundary is specifically integrated into React''s render lifecycle, so it can catch the error before the broken UI is committed and swap in a fallback UI seamlessly within the component tree.',null,null,null,'medium',ARRAY['react','advanced','error-boundaries']::text[],false,138),
('react','advanced-react','react-advanced-react-139','How can compound components expose an imperative escape hatch (like a ref-based API) alongside their declarative props?','The root compound component can accept a ref via forwardRef and use useImperativeHandle to expose specific imperative methods (like next() or reset() for a carousel), giving consumers a declarative props-based API for the common case while still allowing direct imperative control for edge cases that don''t fit cleanly into props.',null,null,null,'hard',ARRAY['react','advanced','compound-components']::text[],false,139),
('react','advanced-react','react-advanced-react-140','Why might two components with the exact same output still be treated differently by React''s reconciler based on how they''re defined?','If a component function is defined inside another component''s body (re-created on every parent render), React sees a new component type on every render — even though the JSX output looks identical — and will unmount/remount it instead of updating it in place, silently resetting its state. Defining components at the module level (outside other components) avoids this trap.',null,'// Bug: Inner defined inside Outer — new type every render, resets state
function Outer() {
  function Inner() { const [n, setN] = useState(0); return <button onClick={() => setN(n+1)}>{n}</button>; }
  return <Inner />;
}','jsx','hard',ARRAY['react','advanced','reconciliation']::text[],true,140),
('react','advanced-react','react-advanced-react-141','What role does the ErrorBoundary''s getDerivedStateFromError differ from componentDidCatch?','getDerivedStateFromError is called during the render phase and should be a pure function that returns new state to trigger the fallback UI — it can''t perform side effects. componentDidCatch is called during the commit phase and is where side effects belong, such as logging the error to a monitoring service; most error boundaries implement both, one to render the fallback and the other to report the error.',null,'class ErrorBoundary extends React.Component {
  state = { hasError: false };
  static getDerivedStateFromError() { return { hasError: true }; }
  componentDidCatch(error, info) { logErrorToService(error, info); }
  render() { return this.state.hasError ? <Fallback /> : this.props.children; }
}','jsx','medium',ARRAY['react','advanced','error-boundaries']::text[],false,141),
('react','advanced-react','react-advanced-react-142','How would you structure a custom hook so it can be safely called conditionally, given the rules of hooks forbid conditional hook calls?','You can''t call a hook conditionally, but you can make the hook itself always run and internally decide whether to do work based on an argument — for example, a useFetch(url) hook can always be called, but skip the actual fetch inside its effect if url is null, keeping the hook call itself unconditional while its behavior is effectively conditional.',null,'function useFetch(url) {
  useEffect(() => {
    if (!url) return; // conditional behavior, not a conditional hook call
    fetch(url);
  }, [url]);
}','jsx','medium',ARRAY['react','advanced','hooks']::text[],false,142),
('react','advanced-react','react-advanced-react-143','What is the difference between React''s legacy Context API (contextTypes) and the modern createContext API?','The legacy API required class components to declare contextTypes and read context off this.context, worked only with class components, and had no way to opt out of re-rendering when unrelated context changed. The modern createContext/useContext API works in both function and class components, supports multiple independent contexts cleanly via nesting, and is the only option going forward since the legacy API is deprecated.',null,null,null,'easy',ARRAY['react','advanced','context']::text[],false,143),
('react','advanced-react','react-advanced-react-144','How would you build a generic useLocalStorage custom hook that keeps React state in sync with localStorage?','The hook initializes state by reading from localStorage (falling back to a default if nothing is stored or parsing fails), and wraps the setter so every update also writes the new value back to localStorage, wrapped in try/catch since storage access can throw (private browsing, quota exceeded, or a non-browser environment during SSR).',null,'function useLocalStorage(key, defaultValue) {
  const [value, setValue] = useState(() => {
    try { return JSON.parse(localStorage.getItem(key)) ?? defaultValue; }
    catch { return defaultValue; }
  });
  useEffect(() => {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch {}
  }, [key, value]);
  return [value, setValue];
}','jsx','medium',ARRAY['react','advanced','custom-hooks']::text[],false,144),
('react','advanced-react','react-advanced-react-145','Why is it recommended to keep error boundaries relatively granular rather than having just one at the app root?','A single root-level error boundary means any unhandled error anywhere in the app replaces the entire UI with a fallback, even if the error occurred in a small, non-critical widget. Placing boundaries around independent sections (a sidebar, a single card in a dashboard) contains failures to just that section, letting the rest of the app keep working.',null,null,null,'medium',ARRAY['react','advanced','error-boundaries']::text[],false,145),
('react','advanced-react','react-advanced-react-146','What does it mean for a custom hook to "leak" implementation details, and how would you avoid it?','A hook leaks details when its return value or required arguments expose internals that force consumers to understand how it works internally (like returning a raw dispatch function alongside state, or requiring a specific shape only relevant to the hook''s own logic) rather than a clean, purpose-built API. Designing the hook''s public surface around what the consumer actually needs to do (return an updater function with a clear name, not raw internals) keeps it reusable and easy to refactor later.',null,null,null,'medium',ARRAY['react','advanced','custom-hooks']::text[],false,146),
('react','advanced-react','react-advanced-react-147','How would you type a compound component''s subcomponents so TypeScript knows Tabs.Tab and Tabs.List are valid?','You attach the subcomponents as static properties on the root component and declare that shape in the type, e.g. by intersecting the root component''s function type with an object type listing each subcomponent, so Tabs.Tab and Tabs.List are recognized both at runtime (as actual properties) and by the type checker.',null,'const Tabs = Object.assign(TabsRoot, { List: TabsList, Tab: TabsTab });
// Tabs.List and Tabs.Tab are now valid, type-checked usages','tsx','medium',ARRAY['react','advanced','typescript']::text[],false,147),
('react','advanced-react','react-advanced-react-148','What is the difference between a controlled component re-rendering on every keystroke and how that scales in a large form?','A single controlled input re-rendering on every keystroke is cheap, but if that state lives at the top of a large form and every field is controlled from the same parent, every keystroke re-renders the entire form and all its fields, not just the one being typed into. Splitting form state per-field (or using a form library with field-level subscriptions) keeps each keystroke''s re-render scoped to just the relevant field.',null,null,null,'medium',ARRAY['react','advanced','forms']::text[],false,148),
('react','advanced-react','react-advanced-react-149','Why might you wrap a list of Fragments with keys instead of wrapping each group in an extra <div>?','React.Fragment (or the <>...</> shorthand) lets a component return multiple sibling elements without adding an extra wrapping DOM node, which matters when that wrapper would break CSS layout (like flex or grid) that depends on direct-child relationships. When rendering a list of fragments, each still needs a key (using the explicit <React.Fragment key={id}> form, since the shorthand <> syntax doesn''t accept props).',null,'{items.map((item) => (
  <React.Fragment key={item.id}>
    <dt>{item.term}</dt>
    <dd>{item.definition}</dd>
  </React.Fragment>
))}','jsx','easy',ARRAY['react','advanced','fragments']::text[],false,149),
('react','advanced-react','react-advanced-react-150','What''s the difference between defaultProps and using default parameter values in a function component?','defaultProps is set as a static property on the component and works for both class and function components, but is being phased out for function components in favor of plain JavaScript default parameter values in the function signature, which are simpler, more idiomatic, and work identically for destructured props. Default parameters are now the recommended approach; defaultProps still exists mainly for backward compatibility and class components.',null,'// Preferred
function Avatar({ size = 40, alt = ''User avatar'' }) { /* ... */ }

// Legacy
function Avatar({ size, alt }) { /* ... */ }
Avatar.defaultProps = { size: 40, alt: ''User avatar'' };','jsx','easy',ARRAY['react','advanced','props']::text[],false,150),
('react','components','react-components-101','What does it mean for a component to be ''pure'' in React?','A pure component always renders the same output given the same props and state, with no side effects during rendering (no mutating external variables, no network calls in the render body itself). Purity is what makes optimizations like React.memo safe — React can skip re-rendering a pure component when its inputs haven''t changed, because it trusts the output would be identical anyway.',null,null,null,'medium',ARRAY['react','components','purity']::text[],true,101),
('react','components','react-components-102','What is the presentational vs. container component pattern?','A presentational component focuses purely on how things look — it receives data and callbacks via props and has little to no internal logic. A container component focuses on how things work — it manages state, fetches data, and passes the results down to presentational components to render. This separation makes presentational components easy to reuse and test in isolation, though hooks have made the pattern less rigid than it used to be.',null,null,null,'medium',ARRAY['react','components','patterns']::text[],false,102),
('react','components','react-components-103','What is the compound components pattern?','Compound components are a set of components designed to be used together, sharing implicit state (usually via context) so the parent can expose a flexible, declarative API instead of one giant component with many boolean props. A classic example is a <Tabs> component that exposes <Tabs.List>, <Tabs.Tab>, and <Tabs.Panel> as related pieces that communicate behind the scenes.',null,'<Tabs defaultValue="a">
  <Tabs.List>
    <Tabs.Tab value="a">First</Tabs.Tab>
    <Tabs.Tab value="b">Second</Tabs.Tab>
  </Tabs.List>
  <Tabs.Panel value="a">Content A</Tabs.Panel>
  <Tabs.Panel value="b">Content B</Tabs.Panel>
</Tabs>','jsx','hard',ARRAY['react','components','patterns']::text[],true,103),
('react','components','react-components-104','Why does React favor composition over inheritance for reusing component logic?','React components rarely benefit from a class-inheritance hierarchy the way traditional OOP UI toolkits did, because most reuse needs (sharing markup, injecting behavior, wrapping with extra functionality) are better solved by passing components as props or children (composition) than by extending a base component class. The React team has explicitly recommended composition over inheritance since early React documentation.',null,null,null,'easy',ARRAY['react','components','composition']::text[],false,104),
('react','components','react-components-105','How do you provide default values for props in a functional component?','The idiomatic way is to use a default parameter value when destructuring props in the function signature, so the default only applies when the prop is undefined. The older defaultProps static property still works on function components but is deprecated in modern React in favor of default parameters.',null,'function Button({ label = ''Submit'', variant = ''primary'' }) {
  return <button className={variant}>{label}</button>;
}','jsx','easy',ARRAY['react','components','props']::text[],false,105),
('react','components','react-components-106','How can you use props.children to build a generic wrapper component?','By accepting children and rendering it somewhere inside your own markup, a component can wrap arbitrary content with consistent styling or behavior without needing to know what that content actually is. This is how generic components like Card, Modal, or Layout are usually implemented.',null,'function Panel({ title, children }) {
  return (
    <section className="panel">
      <h2>{title}</h2>
      {children}
    </section>
  );
}','jsx','easy',ARRAY['react','components','children']::text[],false,106),
('react','components','react-components-107','Why must React component names start with a capital letter?','JSX uses capitalization to distinguish between a built-in DOM tag and a custom component: a lowercase tag like <div> compiles to a plain string type (''div''), while a capitalized tag like <Button> compiles to a reference to the Button variable. If a component were named lowercase, JSX would treat it as an unknown HTML tag instead of your component.',null,'function button() { return <button />; }
<button />   // renders a native <button>, NOT your component!

function Button() { return <button />; }
<Button />   // correctly renders your component','jsx','easy',ARRAY['react','components','jsx']::text[],false,107),
('react','components','react-components-108','How do you conditionally render an entire component with an early return?','Instead of nesting a ternary deep inside JSX, a component can return early — for example returning null or a loading indicator before its main return statement — to keep the primary render logic flat and readable when a whole branch of the UI should be skipped.',null,'function UserProfile({ user }) {
  if (!user) return <p>No user selected.</p>;
  return <h1>{user.name}</h1>;
}','jsx','easy',ARRAY['react','components','conditional-rendering']::text[],false,108),
('react','components','react-components-109','How do you use Fragments with keys when a list item renders multiple elements?','When each item in a mapped list needs to render more than one sibling element (for example a <dt>/<dd> pair), you can''t wrap them in a keyed <div> without affecting layout, so you use an explicit <React.Fragment key={...}> instead — the shorthand <> </> syntax doesn''t support the key prop.',null,'{terms.map(t => (
  <React.Fragment key={t.id}>
    <dt>{t.term}</dt>
    <dd>{t.definition}</dd>
  </React.Fragment>
))}','jsx','medium',ARRAY['react','components','lists']::text[],false,109),
('react','components','react-components-110','What is forwardRef and when would you use it?','By default, function components don''t accept a ref — refs passed to them are ignored. forwardRef wraps a component to receive the ref as a second argument and manually attach it to an inner DOM node, which is needed when you build a reusable input-like component and want consumers to still be able to focus/measure the underlying element directly.',null,'const FancyInput = forwardRef((props, ref) => (
  <input ref={ref} className="fancy" {...props} />
));

// usage
const ref = useRef(null);
<FancyInput ref={ref} />','jsx','hard',ARRAY['react','components','refs']::text[],true,110),
('react','components','react-components-111','What does useImperativeHandle do, and how does it relate to forwardRef?','useImperativeHandle customizes what value a ref exposes when used together with forwardRef — instead of exposing the raw DOM node, the component can expose a curated object of specific methods (e.g. { focus, reset }), hiding internal implementation details from the parent. It''s used sparingly, since exposing imperative APIs works against React''s declarative model and should be reserved for cases that genuinely need it.',null,'const CustomInput = forwardRef((props, ref) => {
  const inputRef = useRef(null);
  useImperativeHandle(ref, () => ({
    focus: () => inputRef.current.focus(),
  }));
  return <input ref={inputRef} {...props} />;
});','jsx','hard',ARRAY['react','components','refs']::text[],false,111),
('react','components','react-components-112','How can a component expose ''slots'' of custom JSX via named props?','When a component needs more than one distinct region of custom content (not just a single children block), it can accept multiple props that are themselves JSX, such as header and footer, and render each in its designated spot. This is a common way to build layout components with more structure than plain children allows.',null,'function Dialog({ header, children, footer }) {
  return (
    <div className="dialog">
      <div className="dialog-header">{header}</div>
      <div className="dialog-body">{children}</div>
      <div className="dialog-footer">{footer}</div>
    </div>
  );
}','jsx','medium',ARRAY['react','components','composition']::text[],false,112),
('react','components','react-components-113','What does it mean to think of components as a ''design system''?','A design system is a shared library of consistent, reusable components (buttons, inputs, cards) with a well-defined API and consistent styling, used across an entire product or organization instead of each team reinventing its own version. Treating components this way encourages thinking about props as a stable public contract, since many unrelated features may depend on the same component.',null,null,null,'easy',ARRAY['react','components','design-systems']::text[],false,113),
('react','components','react-components-114','How would you render a dynamic list of controlled text inputs, each with its own value?','Keep an array (or object keyed by id) in state representing each input''s current value, render one controlled <input> per array item using its index or id as the key, and update just that one entry in the array (immutably) in the onChange handler rather than replacing the whole array with a single new value.',null,'function updateField(index, value) {
  setFields(prev => prev.map((f, i) => (i === index ? value : f)));
}

fields.map((value, i) => (
  <input key={i} value={value} onChange={e => updateField(i, e.target.value)} />
))','jsx','medium',ARRAY['react','components','forms']::text[],false,114),
('react','components','react-components-115','What are some component-design considerations when building a multi-step form?','A common approach is to keep the overall form data and current step index in the parent, and render one ''step'' component at a time based on that index, passing down the relevant slice of data plus onNext/onBack callbacks. Each step component stays focused on its own fields, while validation can happen per-step (before allowing ''Next'') or all at once on final submit, depending on the desired UX.',null,null,null,'medium',ARRAY['react','components','forms']::text[],false,115),
('react','components','react-components-116','What''s the difference between a ''wrapper'' component built through composition versus a higher-order component?','A composition-based wrapper simply renders its children (or a specific prop) inside some extra markup or context provider — you use it directly in JSX like any other component. A higher-order component (HOC) is a function that takes a component and returns a brand new component with injected props, so you use its output rather than nesting the original component as a child — composition is generally simpler and easier to trace than HOCs for most cases.',null,'// Composition-based wrapper (simpler)
function Centered({ children }) {
  return <div className="centered">{children}</div>;
}
<Centered><Form /></Centered>','jsx','medium',ARRAY['react','components','composition','hoc']::text[],false,116),
('react','components','react-components-117','How does the single responsibility principle apply to React components?','Each component should ideally be responsible for one clear piece of UI or behavior — for example, separating a data-fetching concern from a purely presentational list item — rather than one component trying to handle layout, data fetching, and business logic all at once. This makes components easier to test, reuse, and reason about in isolation.',null,null,null,'easy',ARRAY['react','components','design']::text[],false,117),
('react','components','react-components-118','How can component composition (children as props) help avoid prop drilling, as an alternative to Context?','Instead of passing a deeply-nested piece of data down through many layers as a prop, a parent that already has that data can render the deeply-nested component itself and pass it in as children (or another JSX prop) to an intermediate component, which just renders {children} without needing to know about that data at all. This sidesteps drilling through components that don''t actually use the value, without introducing Context.',null,'// Instead of: <Layout data={data} /> forwarding data through many layers
function App() {
  return <Layout><Sidebar data={data} /></Layout>;
}
function Layout({ children }) {
  return <div className="layout">{children}</div>; // never touches `data`
}','jsx','medium',ARRAY['react','components','composition']::text[],false,118),
('react','components','react-components-119','Why does wrapping a child component in React.memo sometimes fail to prevent re-renders?','React.memo does a shallow comparison of props, so if a parent passes a new object, array, or inline function literal as a prop on every render (even with the same logical contents), the shallow comparison sees a different reference and re-renders the child anyway. Fixing this usually means memoizing that prop value with useMemo/useCallback in the parent, or restructuring so the prop is a stable primitive.',null,'// Breaks memoization: new object every render
<Child style={{ color: ''red'' }} />

// Fixed: stable reference
const style = useMemo(() => ({ color: ''red'' }), []);
<Child style={style} />','jsx','medium',ARRAY['react','components','performance','memo']::text[],true,119),
('react','components','react-components-120','Why can passing a new object or array literal as a prop on every render hurt performance?','Even if two object literals are structurally identical, they are different references in memory, so any child relying on reference equality (React.memo, a useEffect dependency, useMemo) treats them as ''changed'' every single render. This can cause unnecessary re-renders or effect re-runs that wouldn''t happen if the same reference were reused.',null,'// New array reference every render, even though contents are the same
<List items={[1, 2, 3]} />','jsx','hard',ARRAY['react','components','performance']::text[],false,120),
('react','components','react-components-121','What are common conventions for organizing component files in a React project?','Common approaches include grouping by feature/domain (each feature folder contains its own components, hooks, and styles) or grouping by type (a top-level components/, hooks/, pages/ split). Most teams also co-locate a component''s styles, tests, and sub-components in the same folder as the component itself, rather than scattering related files across the project.',null,null,null,'easy',ARRAY['react','components','project-structure']::text[],false,121),
('react','components','react-components-122','What does it mean to ''colocate'' state near where it''s used?','Colocating state means keeping a piece of state in the lowest (most local) component that actually needs it, rather than defaulting to lifting everything to a top-level parent or global store. This keeps unrelated parts of the tree from re-rendering when that state changes, and keeps the component''s logic easier to understand in isolation.',null,null,null,'medium',ARRAY['react','components','state']::text[],false,122),
('react','components','react-components-123','When should you extract a piece of JSX into its own component versus keeping it inline?','Good signals to extract a component include the JSX being reused in more than one place, the block being complex enough to hurt readability where it is, or the block needing its own isolated state or memoization. If none of those apply, keeping markup inline is often simpler than introducing an extra file and prop-passing overhead for no real benefit.',null,null,null,'easy',ARRAY['react','components','design']::text[],false,123),
('react','components','react-components-124','What''s the convention for naming event handler props on a custom component?','By convention, a component exposes an event-like prop as onSomething (e.g. onSave, onClose, onSelect) mirroring the native DOM onClick/onChange naming, while the internal function that implements the behavior is usually named handleSomething. Following this convention makes a component''s API predictable to anyone familiar with React norms.',null,'function Modal({ onClose }) {
  function handleBackdropClick() {
    onClose();
  }
  return <div onClick={handleBackdropClick}>...</div>;
}','jsx','easy',ARRAY['react','components','conventions']::text[],false,124),
('react','components','react-components-125','How do you make a component render nothing under certain conditions?','A component can return null (or false, or undefined) from its render function, and React simply renders nothing to the DOM for it — no wrapper element, no placeholder. This is commonly used for components that should conditionally ''disappear'' entirely, like a banner that''s dismissed.',null,'function Banner({ visible, message }) {
  if (!visible) return null;
  return <div className="banner">{message}</div>;
}','jsx','easy',ARRAY['react','components','conditional-rendering']::text[],false,125),
('react','components','react-components-126','Does it matter whether you write <Input /> or <Input></Input> in JSX?','No — for a component or element with no children, the self-closing form <Input /> and the explicit open/close form <Input></Input> compile to the exact same output. Self-closing is just the conventional, more concise style for childless elements; JSX requires closing every tag one way or the other, unlike HTML where some tags can be left unclosed.',null,null,null,'easy',ARRAY['react','components','jsx']::text[],false,126),
('react','components','react-components-127','How do you forward unknown ''rest'' props onto the underlying DOM element in a wrapper component?','Destructure the props you specifically care about, then spread the remaining rest object onto the DOM element, so consumers can still pass through standard HTML attributes (id, aria-label, data-* attributes, etc.) without the wrapper having to explicitly declare every single one.',null,'function PrimaryButton({ variant, children, ...rest }) {
  return (
    <button className={`btn btn-${variant}`} {...rest}>
      {children}
    </button>
  );
}','jsx','medium',ARRAY['react','components','props']::text[],false,127),
('react','components','react-components-128','How should a custom component handle accessibility props like aria-label?','A well-designed custom component should forward standard ARIA attributes through to the underlying native element (usually via rest-prop spreading) rather than swallowing them, so consumers can still make the component accessible in context. Some components also set sensible default ARIA attributes internally (like role and aria-expanded on a custom dropdown) so consumers don''t have to wire up accessibility from scratch every time.',null,'function IconButton({ label, icon, ...rest }) {
  return (
    <button aria-label={label} {...rest}>
      {icon}
    </button>
  );
}','jsx','medium',ARRAY['react','components','accessibility']::text[],false,128),
('react','components','react-components-129','What''s the general philosophy behind testing React components?','The widely recommended approach (popularized by Testing Library) is to test components the way a user would interact with them — querying by visible text or accessible roles and simulating clicks/typing — rather than reaching into internal implementation details like component state or instance methods. This makes tests more resilient to refactors, since they only break when actual user-facing behavior changes, not when internals are reorganized.',null,null,null,'medium',ARRAY['react','components','testing']::text[],false,129),
('react','components','react-components-130','Why did class components require render() to be a pure function, and how does that carry over to function components?','React could call render() multiple times (or not at all, if it decided the output wasn''t needed) as part of its internal scheduling, so relying on side effects inside render() led to unpredictable behavior. The same rule carries over to function components: the function body itself (everything outside of useEffect) must stay free of side effects, with useEffect being the designated place for anything that needs to interact with the outside world.',null,null,null,'hard',ARRAY['react','components','purity']::text[],false,130),
('react','components','react-components-131','What is the ''children as a function'' (render prop) pattern at a basic level?','Instead of passing static JSX as children, you pass a function as children, and the component calls that function with some internal data, letting the caller decide exactly what to render with it. It''s less common today since custom hooks solve the same ''share stateful logic'' problem with less nesting, but it still appears in some libraries.',null,'function MouseTracker({ children }) {
  const [pos, setPos] = useState({ x: 0, y: 0 });
  return (
    <div onMouseMove={e => setPos({ x: e.clientX, y: e.clientY })}>
      {children(pos)}
    </div>
  );
}

<MouseTracker>{pos => <p>{pos.x}, {pos.y}</p>}</MouseTracker>','jsx','medium',ARRAY['react','components','patterns','render-props']::text[],false,131),
('react','components','react-components-132','How do you conditionally apply CSS classes based on props or state in JSX?','For a couple of simple conditions, template literals or ternaries are enough; for anything more complex, a small utility like clsx or classnames is commonly used to combine class names based on truthy values, which reads more clearly than manually concatenating strings.',null,'import clsx from ''clsx'';

<button className={clsx(''btn'', { ''btn-active'': isActive, ''btn-disabled'': disabled })} />','jsx','easy',ARRAY['react','components','styling']::text[],false,132),
('react','components','react-components-133','What''s the difference between using inline styles and CSS classes in a React component?','Inline styles (style={{ color: ''red'' }}) are a JavaScript object applied directly to the element''s style attribute, useful for one-off dynamic values computed at runtime, but they can''t use pseudo-classes, media queries, or be overridden by normal CSS specificity rules as easily. CSS classes (via plain CSS, CSS Modules, or a CSS-in-JS library) support the full power of CSS and are generally preferred for anything beyond a truly dynamic, per-instance value.',null,'// Inline: fine for one dynamic value
<div style={{ width: `${progress}%` }} />

// Class: fine for everything else
<div className="progress-bar" />','jsx','easy',ARRAY['react','components','styling']::text[],false,133),
('react','components','react-components-134','How would you pass a whole component (not just data) as a prop to another component?','Because components are just values (function references) in React, you can pass a component itself as a prop and render it with JSX syntax inside the receiving component, which is useful for injecting a customizable piece of UI, like letting a List component accept an ItemComponent to render for each row.',null,'function List({ items, ItemComponent }) {
  return items.map(item => <ItemComponent key={item.id} item={item} />);
}

<List items={users} ItemComponent={UserRow} />','jsx','medium',ARRAY['react','components','composition']::text[],false,134),
('react','components','react-components-135','What''s the difference between a fully controlled input and one using defaultValue?','A fully controlled input''s value always comes from state, and every keystroke must go through onChange to update that state before the input reflects it. An input with defaultValue is uncontrolled — React sets its initial value once and then lets the DOM manage the value itself afterward, which is useful when you don''t need to react to every change, just read the value later (e.g. via a ref or on submit).',null,'// Uncontrolled: React doesn''t track keystrokes
<input defaultValue="Jane" ref={inputRef} />','jsx','medium',ARRAY['react','components','forms']::text[],false,135),
('react','components','react-components-136','Why does an event handler prop passed to a memoized child need a stable reference?','If a memoized child is wrapped in React.memo but receives an inline arrow function as a prop (e.g. onClick={() => doThing()}), a new function is created on every parent render, which breaks the shallow-equality check React.memo relies on and causes the child to re-render anyway. Wrapping the handler in useCallback in the parent keeps the same function reference across renders (as long as its own dependencies don''t change) so the memoized child can actually skip re-rendering.',null,'const handleClick = useCallback(() => setCount(c => c + 1), []);
<MemoizedButton onClick={handleClick} />','jsx','hard',ARRAY['react','components','performance','usecallback']::text[],false,136),
('react','components','react-components-137','Is prop validation still worth doing in a TypeScript React project?','TypeScript catches type mismatches at compile time, but it can''t validate data coming from truly dynamic runtime sources like an API response or third-party integration whose shape wasn''t guaranteed. For components consuming genuinely untrusted external data, a lightweight runtime check (or a schema validation library) can still add a useful safety net that pure compile-time types can''t provide.',null,null,null,'medium',ARRAY['react','components','typescript']::text[],false,137),
('react','components','react-components-138','What''s the trade-off between using named exports and a default export for a component?','A default export lets the importer name the component anything they want on import, which can lead to inconsistent naming across a codebase and makes some ''find all usages'' tooling less reliable. Named exports enforce a single consistent name everywhere and make auto-import tooling more predictable, which is why many style guides now prefer named exports for components, especially in larger codebases.',null,'// Named export (consistent name everywhere it''s imported)
export function Button() { /* ... */ }
import { Button } from ''./Button'';','jsx','easy',ARRAY['react','components','conventions']::text[],false,138),
('react','components','react-components-139','What is a polymorphic component in React?','A polymorphic component accepts an ''as'' prop (or similar) that lets the caller choose which underlying HTML element or component it renders as, while keeping the same styling and behavior — for example, a Text component that can render as a <p>, <span>, or <h1> depending on context, without needing a separate component for each.',null,'function Text({ as: Tag = ''p'', children, ...rest }) {
  return <Tag {...rest}>{children}</Tag>;
}

<Text as="h1">Title</Text>
<Text as="span">Inline text</Text>','jsx','hard',ARRAY['react','components','patterns']::text[],false,139),
('react','components','react-components-140','What API design decisions matter most when building a reusable Modal component?','A typical Modal needs at minimum an isOpen boolean and an onClose callback so the parent stays in control of when it''s shown, plus children for its content — implementation details like rendering via a portal, trapping focus, and closing on Escape/backdrop click should live inside the Modal itself so every consumer gets that behavior for free rather than reimplementing it.',null,'<Modal isOpen={isOpen} onClose={() => setIsOpen(false)}>
  <p>Are you sure?</p>
</Modal>','jsx','medium',ARRAY['react','components','design']::text[],false,140),
('react','components','react-components-141','What does it mean to separate a component''s ''props API'' from its implementation details?','A component''s props are its public contract with consumers — what it accepts and what it promises to do with it — while everything inside the component (how it''s structured internally, what hooks it uses, whether it renders one element or ten) is an implementation detail that should be free to change without breaking anyone using the component. Good component design keeps that props API small, stable, and intention-revealing, independent of internal refactors.',null,null,null,'medium',ARRAY['react','components','design']::text[],false,141),
('react','components','react-components-142','When rendering a list of togglable items, should each item''s open/closed state live in the parent or in each item component?','If only one item can be open at a time (like an accordion), the ''which item is open'' state needs to live in the parent so it can enforce that constraint across siblings. If each item toggles completely independently with no relationship to its siblings, colocating the open/closed state inside each item component is simpler and avoids unnecessary parent re-renders.',null,null,null,'medium',ARRAY['react','components','state']::text[],false,142),
('react','components','react-components-143','What''s the benefit of splitting a large form into smaller field components?','Splitting a form into per-field components (e.g. a TextField, SelectField) lets each field manage its own local UI concerns (like showing/hiding a validation message) and can limit re-renders to just the field that changed rather than the entire form, while also making the individual field markup reusable across different forms in the app.',null,null,null,'easy',ARRAY['react','components','forms']::text[],false,143),
('react','components','react-components-144','Is it possible to over-fragment a UI into too many small components?','Yes — splitting every few lines of JSX into its own component can add indirection (having to jump between many files to follow one flow) and prop-passing overhead without meaningfully improving reuse or clarity. Extraction should be driven by genuine reuse, complexity, or isolation needs (see when-to-extract guidance) rather than an arbitrary rule like ''components should be under N lines.''',null,null,null,'medium',ARRAY['react','components','design']::text[],false,144),
('react','components','react-components-145','How would you render something only in the browser, not during server rendering, inside a component?','Check for the browser environment (commonly via a mounted flag set in a useEffect, since useEffect only runs on the client) and conditionally render the browser-only content once that flag is true, rather than checking typeof window directly during render, which would cause a mismatch between server and client output.',null,'const [mounted, setMounted] = useState(false);
useEffect(() => setMounted(true), []);
if (!mounted) return null;
return <BrowserOnlyWidget />;','jsx','medium',ARRAY['react','components','ssr']::text[],false,145),
('react','components','react-components-146','How did the render props pattern''s nesting problem lead to the adoption of custom hooks?','Sharing multiple pieces of stateful logic via render props meant nesting each provider component inside the next (''wrapper hell''), which made the JSX tree deep and hard to follow even though none of those wrappers rendered any actual visible markup. Custom hooks solve the same reuse problem by letting a component call several hooks side by side as plain function calls, with no extra nesting or indirection in the render tree at all.',null,null,null,'medium',ARRAY['react','components','patterns','hooks']::text[],false,146),
('react','components','react-components-147','How can a component expose multiple distinct ''slots'' of JSX beyond a single children prop?','Define separate named props for each slot (e.g. leftIcon, rightIcon, title) that each accept JSX, and render them in their respective positions — this is useful when a component''s layout has more than one meaningful content region and a single children block wouldn''t convey which content goes where.',null,'function ListItem({ leftIcon, title, rightIcon }) {
  return (
    <div className="list-item">
      {leftIcon}
      <span>{title}</span>
      {rightIcon}
    </div>
  );
}','jsx','medium',ARRAY['react','components','composition']::text[],false,147),
('react','components','react-components-148','What''s the difference between a component definition and a component instance?','A component definition (the function itself, e.g. function Button() {...}) is a single reusable blueprint. Each time you write <Button /> in JSX, React creates a separate instance of it with its own independent state — rendering <Button /> three times produces three distinct instances, each unaware of the others'' state, even though they all share the same underlying definition.',null,'<div>
  <Button label="A" />
  <Button label="B" />
  <Button label="C" />
</div> // 3 independent instances of the same Button definition','jsx','medium',ARRAY['react','components','fundamentals']::text[],false,148),
('react','components','react-components-149','What actually happens if you ignore React''s ''each child in a list should have a unique key'' warning?','The list still renders, but React falls back to matching items by their position in the array, which can cause state to attach to the wrong item after an insertion, removal, or reorder — for example, a text input''s typed value can visibly ''jump'' to a different row if an earlier item is removed from the array. Fixing the warning by adding a stable, unique key eliminates this class of bug.',null,null,null,'easy',ARRAY['react','components','keys','debugging']::text[],true,149),
('react','components','react-components-150','What are the three high-level lifecycle stages every component goes through?','Mounting is when a component is created and inserted into the DOM for the first time. Updating is when it re-renders in response to changed props, state, or context. Unmounting is when it''s removed from the DOM entirely. In function components these map to useEffect running after mount/update, and its cleanup function running before unmount or before the effect re-runs.',null,null,null,'easy',ARRAY['react','components','lifecycle']::text[],true,150),
('react','fundamentals','react-fundamentals-101','What does it mean that React uses a declarative programming model?','In a declarative model you describe what the UI should look like for a given state, and React figures out how to update the DOM to match. This contrasts with an imperative model, where you manually write step-by-step instructions to create, update, and remove DOM nodes yourself.',null,null,null,'easy',ARRAY['react','fundamentals']::text[],false,101),
('react','fundamentals','react-fundamentals-102','What is meant by React''s component tree and unidirectional data flow?','A React application is structured as a tree of nested components, with data (props) flowing from parent to child in one direction only. A child cannot directly modify data owned by a parent; it can only request a change by calling a function the parent passed down, which keeps data flow predictable and easy to trace.',null,null,null,'easy',ARRAY['react','fundamentals','data-flow']::text[],false,102),
('react','fundamentals','react-fundamentals-103','What does JSX actually compile down to?','JSX is syntactic sugar that a build tool (Babel or the Vite/SWC compiler) transforms into plain JavaScript function calls before it runs in the browser. Historically it compiled to React.createElement() calls; since the ''automatic'' JSX runtime (React 17+), it compiles to calls into react/jsx-runtime instead, which is slightly more efficient and no longer requires importing React just to use JSX.',null,'// JSX
const el = <h1 className="title">Hello</h1>;

// Compiles to (classic runtime)
const el = React.createElement(''h1'', { className: ''title'' }, ''Hello'');','jsx','medium',ARRAY['react','fundamentals','jsx']::text[],false,103),
('react','fundamentals','react-fundamentals-104','What are React Fragments and why do they matter?','A Fragment (<React.Fragment> or the <>...</> shorthand) lets a component return multiple sibling elements without wrapping them in an extra DOM node. Before fragments existed, every component had to return a single root element, which often forced unnecessary wrapper divs that could break CSS layouts like flexbox or grid.',null,'function Row() {
  return (
    <>
      <td>Name</td>
      <td>Age</td>
    </>
  );
}','jsx','easy',ARRAY['react','fundamentals','jsx']::text[],true,104),
('react','fundamentals','react-fundamentals-105','What''s a common pitfall when using the && operator for conditional rendering?','If the left-hand value is a falsy number like 0 (e.g. items.length && <List />), React renders the literal 0 to the screen instead of nothing, because 0 is a valid renderable child, not just a ''falsy'' value that gets skipped. The fix is to coerce to a boolean first, e.g. items.length > 0 && <List />.',null,'// Bug: renders "0" when the array is empty
{items.length && <List items={items} />}

// Fixed
{items.length > 0 && <List items={items} />}','jsx','medium',ARRAY['react','fundamentals','jsx','gotcha']::text[],false,105),
('react','fundamentals','react-fundamentals-106','What are the common ways to do conditional rendering in React?','Common patterns include the && operator for ''render this or nothing'', the ternary operator for ''render this or that'', and an early return statement inside the component function when an entire branch of markup should be skipped. Which one to use is mostly a readability choice based on how many conditions and how much markup are involved.',null,null,null,'easy',ARRAY['react','fundamentals','jsx']::text[],false,106),
('react','fundamentals','react-fundamentals-107','How do you render a list of items in React?','Call .map() on an array to transform each item into a JSX element, and return the resulting array directly inside your JSX — React renders arrays of elements automatically. Each element in the resulting array needs a unique key prop so React can track it correctly across re-renders.',null,'<ul>
  {users.map((user) => (
    <li key={user.id}>{user.name}</li>
  ))}
</ul>','jsx','easy',ARRAY['react','fundamentals','lists']::text[],false,107),
('react','fundamentals','react-fundamentals-108','What does React.StrictMode do, and why does it double-invoke things in development?','StrictMode is a wrapper component that opts a subtree into extra development-only checks, such as warning about deprecated APIs and unsafe lifecycle methods. In development it intentionally double-invokes things like component function bodies and some effects to help surface side effects that aren''t properly cleaned up — it has no effect in production builds.',null,null,null,'medium',ARRAY['react','fundamentals','strict-mode']::text[],true,108),
('react','fundamentals','react-fundamentals-109','At a conceptual level, how does React''s reconciliation algorithm decide what to update?','Reconciliation is the process where React compares a newly rendered tree of elements against the previous one to compute the minimal set of real DOM changes needed. It uses heuristics to keep this fast: elements of different types are treated as entirely different subtrees and rebuilt from scratch, while elements of the same type at the same position are diffed prop-by-prop and their children are reconciled recursively, using keys to match items in a list across renders.',null,null,null,'hard',ARRAY['react','fundamentals','reconciliation','internals']::text[],true,109),
('react','fundamentals','react-fundamentals-110','How does React fit into building a single-page application (SPA)?','React itself only handles rendering the view layer for a given piece of state — it doesn''t include routing or data fetching out of the box. Building a full SPA typically means combining React with a router (like React Router) to handle client-side navigation without full page reloads, plus a data-fetching strategy, since React alone is just the UI library at the core.',null,null,null,'easy',ARRAY['react','fundamentals','spa']::text[],false,110),
('react','fundamentals','react-fundamentals-111','What is React''s synthetic event system?','React wraps native browser DOM events in a cross-browser SyntheticEvent object that normalizes differences between browsers and exposes the same API everywhere. Since React 17, these events are attached at the root of the rendered tree rather than on document, which made it easier to embed multiple React versions on the same page.',null,null,null,'medium',ARRAY['react','fundamentals','events']::text[],false,111),
('react','fundamentals','react-fundamentals-112','Conceptually, why does reconciliation need keys at all?','Without keys, React has no reliable way to tell whether an item in a list was added, removed, or reordered versus simply changed — it would have to guess based on position alone, which can mismatch component state to the wrong data after a list changes. A stable, unique key gives React an explicit identity to match old and new elements against, independent of their position in the array.',null,null,null,'medium',ARRAY['react','fundamentals','reconciliation','keys']::text[],true,112),
('react','fundamentals','react-fundamentals-113','What can you inspect using React DevTools?','React DevTools is a browser extension that adds Components and Profiler tabs to your dev tools. The Components tab lets you browse the live component tree, inspect and edit props/state/hooks values, and see which component owns a given DOM node; the Profiler tab records renders over time and helps identify unnecessary or expensive re-renders.',null,null,null,'easy',ARRAY['react','fundamentals','tooling']::text[],false,113),
('react','fundamentals','react-fundamentals-114','What is the difference between the react and react-dom packages?','The react package contains the core APIs for defining components and managing state/hooks, independent of any particular rendering target. react-dom contains the renderer that knows how to translate React''s output into actual browser DOM operations — other renderers, like React Native, swap in a different rendering package while reusing the same react core.',null,null,null,'easy',ARRAY['react','fundamentals','packages']::text[],false,114),
('react','fundamentals','react-fundamentals-115','What is the difference between createRoot and the legacy ReactDOM.render?','createRoot (React 18+) creates a root that opts an app into React''s concurrent rendering features, such as automatic batching and transitions. The older ReactDOM.render (deprecated in React 18) always ran in the legacy synchronous rendering mode and does not support those concurrent features.',null,'import { createRoot } from ''react-dom/client'';

const root = createRoot(document.getElementById(''root''));
root.render(<App />);','jsx','medium',ARRAY['react','fundamentals','react-18']::text[],true,115),
('react','fundamentals','react-fundamentals-116','What does it mean that React 18 batches state updates automatically?','When multiple setState calls happen within the same event handler, React groups them into a single re-render instead of re-rendering after each one, which improves performance. Before React 18, this automatic batching only happened inside React event handlers; React 18 extends it to updates inside promises, timeouts, and native event handlers too.',null,'function handleClick() {
  setCount(c => c + 1);
  setFlag(f => !f);
  // Only one re-render happens, not two
}','jsx','hard',ARRAY['react','fundamentals','react-18','performance']::text[],true,116),
('react','fundamentals','react-fundamentals-117','At a high level, what are React 18''s concurrent rendering features?','Concurrent rendering lets React prepare multiple versions of the UI in memory and interrupt, pause, or discard a render in progress if something more urgent (like user input) comes in, rather than always finishing one render before starting the next. Features built on this include automatic batching, transitions (useTransition, marking updates as non-urgent), and streaming server rendering with Suspense.',null,null,null,'hard',ARRAY['react','fundamentals','react-18','concurrent']::text[],false,117),
('react','fundamentals','react-fundamentals-118','What does a React element actually look like under the hood?','A React element is a plain, lightweight JavaScript object describing a piece of UI — it has a type (a tag name string or a component function/class), a props object, and a key. Elements are not the actual rendered DOM nodes; React reads these objects to figure out what real DOM to create or update.',null,'// Roughly what <h1 className="x">Hi</h1> becomes
{
  type: ''h1'',
  props: { className: ''x'', children: ''Hi'' },
  key: null
}','jsx','medium',ARRAY['react','fundamentals','internals']::text[],false,118),
('react','fundamentals','react-fundamentals-119','Why does React discourage directly manipulating the DOM yourself?','React maintains its own internal representation of the UI to efficiently compute and batch updates; if you manually change a DOM node React manages, React''s internal model goes out of sync with reality, which can cause bugs or have your change silently overwritten on the next render. When you truly need direct DOM access (e.g. focusing an input), you should do it through a ref rather than querySelector-style code.',null,null,null,'easy',ARRAY['react','fundamentals','dom']::text[],false,119),
('react','fundamentals','react-fundamentals-120','How does building a counter in React compare to doing it with vanilla JS DOM manipulation?','In vanilla JS you''d manually select the counter element, keep a variable for the count, and imperatively update textContent on every click. In React you keep the count in state and describe what the counter should render for any given count value — clicking the button just updates state, and React handles updating the actual text on screen for you.',null,'// React
function Counter() {
  const [count, setCount] = useState(0);
  return <button onClick={() => setCount(c => c + 1)}>{count}</button>;
}','jsx','medium',ARRAY['react','fundamentals','state']::text[],false,120),
('react','fundamentals','react-fundamentals-121','Why does using semantic HTML still matter inside JSX?','JSX ultimately renders real DOM elements, so using semantic tags like <button>, <nav>, and <main> instead of generic <div>s with click handlers still matters for accessibility, keyboard navigation, and SEO, exactly as it would in plain HTML. React doesn''t add any semantics on its own — it just gives you a more convenient way to describe the same DOM tree.',null,null,null,'easy',ARRAY['react','fundamentals','accessibility']::text[],false,121),
('react','fundamentals','react-fundamentals-122','What does spreading props with {...props} do?','The spread syntax {...props} expands all key-value pairs of a props object onto a JSX element as individual attributes, which is a concise way to forward a whole set of props through to an underlying element or component without listing each one manually.',null,'function Wrapper(props) {
  return <input {...props} className="styled" />;
}','jsx','easy',ARRAY['react','fundamentals','props']::text[],false,122),
('react','fundamentals','react-fundamentals-123','What is props.children and where does it come from?','props.children holds whatever JSX (or text) was nested between a component''s opening and closing tags when it was used. It''s just a regular prop under the hood, automatically populated by JSX rather than something you have to pass explicitly.',null,'function Card({ children }) {
  return <div className="card">{children}</div>;
}

<Card>
  <p>Nested content</p>
</Card>','jsx','easy',ARRAY['react','fundamentals','props','children']::text[],false,123),
('react','fundamentals','react-fundamentals-124','How does a parent re-rendering affect its child components?','By default, when a component re-renders, React also re-renders all of its child components regardless of whether their own props actually changed — it''s just usually cheap because React only commits real DOM changes where something differs. This is why techniques like React.memo exist: to let a specific child opt out of re-rendering when its props are unchanged.',null,null,null,'medium',ARRAY['react','fundamentals','rendering']::text[],false,124),
('react','fundamentals','react-fundamentals-125','Why do React apps typically need a bundler like Vite or webpack?','Browsers don''t understand JSX or, historically, ES modules with bare package imports, so a bundler transforms JSX into plain JavaScript, resolves and bundles dependencies from node_modules, and produces optimized output (code splitting, minification) for production. Vite additionally provides a fast dev server with hot module replacement during development.',null,null,null,'easy',ARRAY['react','fundamentals','tooling']::text[],false,125),
('react','fundamentals','react-fundamentals-126','What is the difference between client-side rendering and hydration?','In pure client-side rendering, the browser downloads a near-empty HTML shell and JavaScript builds the entire UI after the page loads. Hydration is what happens when the server already sent fully-rendered HTML for the initial view, and React attaches event listeners and internal state to that existing markup on the client instead of re-creating the DOM from scratch, making the page interactive.',null,null,null,'hard',ARRAY['react','fundamentals','ssr','hydration']::text[],false,126),
('react','fundamentals','react-fundamentals-127','What role does a tool like Vite or Create React App play in a React project?','These are project scaffolding and build tooling setups that wire together a dev server, JSX/TypeScript compilation, bundling, and sensible defaults so you don''t have to hand-configure a bundler yourself. Vite has largely replaced Create React App (now unmaintained) because of its much faster dev server startup and hot reload, using native ES modules during development.',null,null,null,'easy',ARRAY['react','fundamentals','tooling']::text[],false,127),
('react','fundamentals','react-fundamentals-128','How do PropTypes and TypeScript compare for type-checking props?','PropTypes is a runtime library that checks prop types while the app is running in development and logs a console warning on mismatch, but it has no effect on production behavior and doesn''t catch errors until the component actually renders with bad data. TypeScript checks prop types statically at compile time, catching many mismatches before the code ever runs, which is why most modern React projects use TypeScript instead of, or in addition to, PropTypes.',null,null,null,'medium',ARRAY['react','fundamentals','typescript']::text[],false,128),
('react','fundamentals','react-fundamentals-129','What is ''lifting state up'' and why is it one of the first patterns React developers learn?','Lifting state up means moving state from a component into its closest common ancestor when two or more sibling components need to read or react to the same value. It''s foundational because it''s the simplest way to keep multiple components in sync without any extra library — later patterns like Context exist to avoid lifting state so far up that it has to be threaded through many layers of props.',null,null,null,'medium',ARRAY['react','fundamentals','state']::text[],false,129),
('react','fundamentals','react-fundamentals-130','What actually causes a React component to re-render?','A component re-renders when its own state changes, when the props passed to it change, when a context value it consumes changes, or when its parent re-renders (regardless of whether that parent''s re-render was caused by something relevant to the child). Understanding this is the starting point for diagnosing unnecessary re-renders and applying memoization correctly.',null,null,null,'medium',ARRAY['react','fundamentals','rendering']::text[],false,130),
('react','fundamentals','react-fundamentals-131','What does declarative UI actually buy you compared to jQuery-style DOM scripting?','With jQuery-style code, every possible state transition needs its own hand-written sequence of DOM mutations, and it gets exponentially harder to reason about as the number of states grows. With React''s declarative model, you only describe the UI for each state once, and React''s diffing handles figuring out the transition between any two states for you, which scales far better as an application grows in complexity.',null,null,null,'easy',ARRAY['react','fundamentals']::text[],false,131),
('react','fundamentals','react-fundamentals-132','Why did early React require every component to return a single root element?','React.createElement (and the underlying rendering model) originally worked with a single element tree per call, so a component''s render output had to be one element with everything else nested inside it. Fragments were added later specifically to lift this restriction without requiring an extra wrapper DOM node.',null,'// Not allowed without a Fragment/wrapper
function Bad() {
  return (
    <li>One</li>
    <li>Two</li>
  );
}','jsx','medium',ARRAY['react','fundamentals','jsx']::text[],false,132),
('react','fundamentals','react-fundamentals-133','What does it mean that ''JSX is just JavaScript''?','Because JSX compiles down to regular function calls, any valid JavaScript expression can be embedded inside curly braces {} within JSX — variables, function calls, ternaries, array methods, and so on. This means you don''t need a separate templating language or special syntax to express logic in your markup; it''s the same language throughout.',null,'const name = ''Sam'';
const el = <p>Hello, {name.toUpperCase()}!</p>;','jsx','easy',ARRAY['react','fundamentals','jsx']::text[],false,133),
('react','fundamentals','react-fundamentals-134','Why can''t a component return multiple sibling elements without a wrapper?','A component''s return value must be a single value in JavaScript, and JSX compiles to a single nested element tree — you can''t return two independent element trees from one function call. A Fragment (or any wrapping element) solves this by giving the multiple elements a single, if invisible, parent to be returned as one unit.',null,null,null,'easy',ARRAY['react','fundamentals','jsx']::text[],false,134),
('react','fundamentals','react-fundamentals-135','How do JSX prop names differ from standard HTML attribute names?','Some JSX props are renamed because they''d otherwise collide with reserved JavaScript words or don''t map cleanly to the DOM property: class becomes className, for becomes htmlFor, and most attributes use camelCase (onclick becomes onClick, tabindex becomes tabIndex) to match JavaScript naming conventions rather than HTML''s lowercase-only attributes.',null,'<label htmlFor="email" className="label">Email</label>','jsx','easy',ARRAY['react','fundamentals','jsx']::text[],false,135),
('react','fundamentals','react-fundamentals-136','How does JSX render boolean, null, and undefined values?','React treats false, true, null, and undefined as ''nothing to render'' when they appear as JSX children, so they simply produce no output rather than an error or the literal text. This is what makes the {condition && <Component />} pattern work: when condition is false, JSX renders nothing.',null,'<div>{null}{undefined}{false}{true}</div> // renders an empty div','jsx','medium',ARRAY['react','fundamentals','jsx']::text[],false,136),
('react','fundamentals','react-fundamentals-137','What does it mean that React is ''a UI library, not an application framework''?','React only concerns itself with turning state into rendered UI and handling events — it deliberately doesn''t prescribe how to do routing, data fetching, or global state management, unlike a full framework such as Angular. Teams choose and assemble their own supporting libraries (React Router, TanStack Query, Redux/Zustand, etc.), which gives flexibility at the cost of more setup decisions.',null,null,null,'medium',ARRAY['react','fundamentals']::text[],false,137),
('react','fundamentals','react-fundamentals-138','What is the difference between React''s render phase and commit phase?','The render phase is where React calls your component functions to figure out what the new tree of elements should look like and diffs it against the previous tree — this phase can be paused, aborted, or restarted by React and must be free of side effects. The commit phase is where React actually applies the computed DOM mutations and runs effects like useEffect/componentDidMount, and this phase always runs synchronously to completion once started.',null,null,null,'hard',ARRAY['react','fundamentals','internals']::text[],false,138),
('react','fundamentals','react-fundamentals-139','What actually triggers a component''s render phase to begin?','A render is triggered by a state update (via a state setter), a prop change coming from a re-rendering parent, or a context value update for a component subscribed to that context. React schedules and may batch several triggers together before actually running the render phase once.',null,null,null,'hard',ARRAY['react','fundamentals','internals','rendering']::text[],false,139),
('react','fundamentals','react-fundamentals-140','At a fundamentals level, why must hooks always be called in the same order on every render?','React associates each hook call with internal state purely by the order it was called in during a render, not by name — there''s no other identifier. If a hook is called conditionally so the order changes between renders, React would attach the wrong stored state to the wrong hook call, corrupting component state in subtle ways.',null,null,null,'medium',ARRAY['react','fundamentals','hooks']::text[],false,140),
('react','fundamentals','react-fundamentals-141','How do refs differ from React''s normal declarative rendering model?','Refs (useRef, or a DOM ref returned from forwardRef) give you an ''escape hatch'' to imperatively read or mutate a DOM node or hold a mutable value directly, bypassing the render-based data flow. They''re meant for cases the declarative model doesn''t cover well, like focusing an input or measuring an element''s size, not as a general substitute for state.',null,'const inputRef = useRef(null);
// Imperative: directly call a DOM method
inputRef.current.focus();','jsx','medium',ARRAY['react','fundamentals','refs']::text[],false,141),
('react','fundamentals','react-fundamentals-142','How does React decide what to do when a JSX child is a plain string, number, or object?','Strings and numbers are rendered directly as text nodes. Plain objects (other than valid React elements or arrays of children) are not valid as a React child and will throw an error at runtime — you''d need to convert the object to a string or extract the specific fields you want to render.',null,'<div>{42}</div>       // renders "42"
<div>{{ a: 1 }}</div> // throws: Objects are not valid as a React child','jsx','medium',ARRAY['react','fundamentals','jsx']::text[],false,142),
('react','fundamentals','react-fundamentals-143','What kinds of JavaScript expressions are NOT allowed inside JSX curly braces?','Curly braces in JSX must contain an expression that produces a value, not a statement — so if/else blocks, for loops, and variable declarations (let/const) can''t go directly inside {}. You work around this by computing the value beforehand (outside the JSX) or using expression-based alternatives like the ternary operator or .map().',null,'// Invalid: if is a statement, not an expression
{if (loggedIn) { <p>Hi</p> }}

// Valid: ternary is an expression
{loggedIn ? <p>Hi</p> : null}','jsx','easy',ARRAY['react','fundamentals','jsx']::text[],false,143),
('react','fundamentals','react-fundamentals-144','What''s the difference between a React application and a React component library?','A React application is a deployable product with routing, pages, and business logic built on top of React. A component library is a reusable package of components (and often hooks/utilities) meant to be installed as a dependency of other applications, typically published with its own build step, type definitions, and documentation rather than a running app.',null,null,null,'easy',ARRAY['react','fundamentals']::text[],false,144),
('react','fundamentals','react-fundamentals-145','Why is onClick={() => doSomething()} usually correct while onClick={doSomething()} is usually a bug?','onClick={doSomething()} calls doSomething immediately during render and passes whatever it returns as the handler, instead of passing a function to run later on click. Wrapping it in an arrow function, onClick={() => doSomething()}, defers the call until the click actually happens, and also lets you pass arguments that plain onClick={doSomething} (without parentheses) wouldn''t allow.',null,'// Bug: runs on every render, not on click
<button onClick={deleteItem(id)}>Delete</button>

// Correct: runs only when clicked
<button onClick={() => deleteItem(id)}>Delete</button>','jsx','medium',ARRAY['react','fundamentals','events','gotcha']::text[],false,145),
('react','fundamentals','react-fundamentals-146','Does a key prop need to be unique across the whole app, or just somewhere specific?','A key only needs to be unique among its immediate siblings within the same array being rendered — it does not need to be globally unique across the entire component tree. Using the same key value in two unrelated lists elsewhere in the app causes no conflict at all.',null,'// Both lists can safely reuse key="1", key="2" independently
<ul>{users.map(u => <li key={u.id}>{u.name}</li>)}</ul>
<ul>{posts.map(p => <li key={p.id}>{p.title}</li>)}</ul>','jsx','medium',ARRAY['react','fundamentals','keys']::text[],false,146),
('react','fundamentals','react-fundamentals-147','What does ''one-way data binding'' mean, and how does it differ from two-way binding?','In one-way binding, data flows from state into the UI in a single direction, and any change originating from the UI (like typing in an input) has to explicitly call a function to update state, which then flows back down to re-render the UI. Two-way binding, common in frameworks like older Angular or Vue''s v-model, automatically syncs a form input''s value back into a bound variable without the developer wiring an explicit handler.',null,null,null,'medium',ARRAY['react','fundamentals','data-flow']::text[],false,147),
('react','fundamentals','react-fundamentals-148','What is the role of the index.html file in a Vite-based React app?','index.html is the actual entry point Vite serves — it contains a script tag pointing at your main JavaScript/TypeScript entry file (e.g. src/main.jsx) and typically a single empty <div id="root">. React then mounts the entire application into that div at runtime; almost none of the visible UI is written directly in this file.',null,null,null,'easy',ARRAY['react','fundamentals','tooling']::text[],false,148),
('react','fundamentals','react-fundamentals-149','When can''t you use the <>...</> Fragment shorthand and need React.Fragment explicitly instead?','The shorthand syntax <>...</> cannot accept any props, including a key. If you''re rendering a list of fragments (for example, grouping multiple elements per array item without an extra wrapper), you need the explicit <React.Fragment key={...}> form so each fragment can carry the required key.',null,'{items.map(item => (
  <React.Fragment key={item.id}>
    <dt>{item.term}</dt>
    <dd>{item.description}</dd>
  </React.Fragment>
))}','jsx','easy',ARRAY['react','fundamentals','jsx']::text[],false,149),
('react','fundamentals','react-fundamentals-150','What is meant by ''component-driven development''?','Component-driven development is the practice of building a UI from the bottom up — starting with small, isolated, reusable components (often developed and tested independently, e.g. in Storybook) and composing them into larger features and pages. It encourages thinking in terms of a reusable component library rather than building each page as one large, monolithic piece of markup.',null,null,null,'medium',ARRAY['react','fundamentals','design']::text[],false,150),
('react','hooks','react-hooks-101','When should you use useReducer instead of useState?','useReducer is preferable when state logic is complex, involves multiple sub-values that update together, or when the next state depends on the previous state in non-trivial ways. It centralizes update logic in a single reducer function, making state transitions more predictable and testable than scattering multiple useState calls and setter calls across a component.',null,'function reducer(state, action) {
  switch (action.type) {
    case ''increment'': return { count: state.count + 1 };
    default: return state;
  }
}
const [state, dispatch] = useReducer(reducer, { count: 0 });','jsx','medium',ARRAY['react','hooks','usereducer']::text[],true,101),
('react','hooks','react-hooks-102','How do you consume a context value using the useContext hook?','Call useContext(SomeContext) inside a function component to read the nearest matching Provider''s value directly, without wrapping the component in a Consumer render-prop. The component re-renders automatically whenever the Provider''s value changes, and if no Provider is present, useContext returns the context''s default value.',null,'const theme = useContext(ThemeContext);','jsx','easy',ARRAY['react','hooks','usecontext']::text[],false,102),
('react','hooks','react-hooks-103','What is a custom hook and why should its name start with "use"?','A custom hook is simply a JavaScript function that calls other hooks internally to encapsulate and share reusable stateful logic across components. Prefixing its name with "use" is a naming convention that lets both React and the ESLint hooks plugin recognize it as a hook, applying the rules of hooks and enabling correct linting.',null,'function useWindowWidth() {
  const [width, setWidth] = useState(window.innerWidth);
  useEffect(() => {
    const onResize = () => setWidth(window.innerWidth);
    window.addEventListener(''resize'', onResize);
    return () => window.removeEventListener(''resize'', onResize);
  }, []);
  return width;
}','jsx','easy',ARRAY['react','hooks','custom-hooks']::text[],true,103),
('react','hooks','react-hooks-104','When exactly does a useEffect cleanup function run?','The cleanup function returned from an effect runs right before the component re-runs that same effect (when its dependencies change) and again when the component unmounts. This ordering ensures that a previous effect''s side effect, like a subscription or timer, is torn down before a new one is set up, preventing duplicate subscriptions or leaks.',null,null,null,'medium',ARRAY['react','hooks','useeffect']::text[],false,104),
('react','hooks','react-hooks-105','What common bugs occur when the useEffect dependency array is incomplete?','Omitting a value the effect actually reads from its dependency array causes the effect to close over a stale version of that value, a "stale closure". This often shows up as data going out of sync or event handlers acting on old values, and is why the exhaustive-deps ESLint rule flags missing dependencies.',null,'useEffect(() => {
  console.log(count); // always logs the initial count
}, []); // missing ''count'' dependency','jsx','medium',ARRAY['react','hooks','useeffect']::text[],true,105),
('react','hooks','react-hooks-106','Beyond timing, what practical difference does choosing useLayoutEffect over useEffect make?','useEffect runs asynchronously after the browser has painted, so any DOM mutation inside it can cause a visible flicker before the update is applied. useLayoutEffect runs synchronously after DOM mutations but before the browser paints, blocking the paint until it finishes — useful for measuring or adjusting layout so the user never sees the unadjusted frame, at the cost of potentially blocking rendering if the work is slow.',null,null,null,'hard',ARRAY['react','hooks','uselayouteffect']::text[],false,106),
('react','hooks','react-hooks-107','What is the main pitfall of fetching data directly inside a useEffect, and how is it commonly avoided?','If a component re-renders quickly, for example a prop like an id changes twice in a row, an earlier fetch can resolve after a later one and overwrite fresher data with stale results — a race condition. The common fix is to track a "cancelled" flag or use an AbortController in the effect''s cleanup function so a stale response is ignored once a newer request has started.',null,'useEffect(() => {
  let cancelled = false;
  fetchUser(id).then((data) => { if (!cancelled) setUser(data); });
  return () => { cancelled = true; };
}, [id]);','jsx','medium',ARRAY['react','hooks','useeffect','data-fetching']::text[],false,107),
('react','hooks','react-hooks-108','What is the difference between setCount(count + 1) and setCount(c => c + 1)?','setCount(count + 1) uses the value of count captured when the function was defined, which can be stale if multiple updates happen before a re-render. setCount(c => c + 1) passes an updater function that always receives the latest pending state, making it safe to call multiple times in a row without losing updates.',null,'setCount(c => c + 1);
setCount(c => c + 1); // count increases by 2, reliably','jsx','easy',ARRAY['react','hooks','usestate']::text[],false,108),
('react','hooks','react-hooks-109','What does it mean to pass a function to useState, and why would you do that?','When the initial state is expensive to compute, passing a function tells React to call it only once, on the initial render, rather than recomputing and discarding the value on every re-render as you would by calling the expensive function directly as the argument. This is called lazy initialization.',null,'const [items, setItems] = useState(() => JSON.parse(localStorage.getItem(''items'')) ?? []);','jsx','medium',ARRAY['react','hooks','usestate']::text[],false,109),
('react','hooks','react-hooks-110','Is it better to use several useState calls or one useState holding an object?','Several independent useState calls are usually preferable for unrelated values since each setter only updates its own piece of state and doesn''t require manually spreading the rest. A single state object makes sense when values are tightly related and typically change together, but every update must spread the previous object since, unlike class component setState, useState does not shallow-merge automatically.',null,null,null,'medium',ARRAY['react','hooks','usestate']::text[],false,110),
('react','hooks','react-hooks-111','How does useRef let you store a value across renders without causing a re-render?','useRef(initialValue) returns a plain mutable object with a .current property that persists for the lifetime of the component. Reading or writing ref.current does not trigger a re-render or schedule an update, unlike setState, making refs suitable for values like timer IDs or previous values that the component needs to remember but never needs to display.',null,null,null,'easy',ARRAY['react','hooks','useref']::text[],false,111),
('react','hooks','react-hooks-112','If both useRef and useState can hold a value, when should you choose one over the other?','Choose useState when a change to the value should cause the component to re-render and reflect the new value in the UI. Choose useRef when you need to persist a value between renders, like a timer ID, a DOM node, or a flag, but updating it should never by itself cause a re-render.',null,null,null,'easy',ARRAY['react','hooks','useref','usestate']::text[],false,112),
('react','hooks','react-hooks-113','What does useImperativeHandle do, and when is it appropriate to use?','useImperativeHandle, used together with forwardRef, lets a component customize the instance value exposed to a parent''s ref, exposing only a specific imperative API like a focus() method instead of the raw DOM node. It should be used sparingly — only when a parent genuinely needs to imperatively trigger behavior on a child that can''t be expressed declaratively through props.',null,'const Input = forwardRef((props, ref) => {
  const inputRef = useRef(null);
  useImperativeHandle(ref, () => ({
    focus: () => inputRef.current.focus(),
  }));
  return <input ref={inputRef} {...props} />;
});','jsx','hard',ARRAY['react','hooks','useimperativehandle','forwardref']::text[],false,113),
('react','hooks','react-hooks-114','What problem does useDeferredValue solve?','useDeferredValue lets you defer re-rendering a non-urgent part of the UI, like a large filtered list, behind a fast-changing value like a text input, so React can keep the input responsive while the expensive part updates slightly behind, showing the previous value until the new one is ready. It''s a way to deprioritize rendering work without debouncing or throttling the actual input state.',null,'const deferredQuery = useDeferredValue(query);
// list filtered by deferredQuery can lag slightly behind the input','jsx','hard',ARRAY['react','hooks','usedeferredvalue','performance']::text[],false,114),
('react','hooks','react-hooks-115','What does useTransition let you do?','useTransition returns a startTransition function and an isPending flag, letting you mark a state update as a low-priority "transition" that can be interrupted by more urgent updates like typing. React keeps the UI responsive by rendering the urgent update first and the transition update when it has spare time, while isPending lets you show a pending indicator during that gap.',null,'const [isPending, startTransition] = useTransition();
startTransition(() => setFilter(nextFilter));','jsx','hard',ARRAY['react','hooks','usetransition','performance']::text[],false,115),
('react','hooks','react-hooks-116','What is useId used for?','useId generates a stable, unique string ID that is consistent between server and client renders, primarily for wiring up accessibility attributes like htmlFor/id pairs on form labels and inputs without risking hydration mismatches. It should not be used as a list key or for generating IDs shown to end users.',null,'const id = useId();
<label htmlFor={id}>Name</label>
<input id={id} />','jsx','easy',ARRAY['react','hooks','useid','accessibility']::text[],false,116),
('react','hooks','react-hooks-117','What problem does useSyncExternalStore solve?','useSyncExternalStore lets a component safely subscribe to a value that lives outside React''s own state, like a browser API or a third-party store, while guaranteeing the value stays consistent even under React''s concurrent rendering features, which could otherwise tear between subscribing and reading the store. It''s the low-level hook that most external state-management library bindings are built on.',null,null,null,'hard',ARRAY['react','hooks','usesyncexternalstore']::text[],false,117),
('react','hooks','react-hooks-118','Can a custom hook call other hooks internally, including other custom hooks?','Yes — a custom hook is just a function, so it can call built-in hooks like useState and useEffect, as well as other custom hooks, as long as it still follows the rules of hooks by only calling them at its own top level, not conditionally. This composability is what lets you build higher-level hooks out of smaller reusable ones.',null,'function useAuthenticatedUser() {
  const [token] = useLocalStorage(''token'');
  const { data } = useFetch(token ? ''/api/me'' : null);
  return data;
}','jsx','easy',ARRAY['react','hooks','custom-hooks']::text[],false,118),
('react','hooks','react-hooks-119','How do you typically test a custom hook in isolation?','Since hooks can only be called inside a component, testing utilities like React Testing Library''s renderHook render the hook inside a minimal throwaway test component and expose its return value and a way to trigger re-renders via act(). This lets you assert on the hook''s returned state and behavior without needing to build and interact with a full UI.',null,null,null,'medium',ARRAY['react','hooks','testing']::text[],false,119),
('react','hooks','react-hooks-120','What typically causes an infinite loop with useEffect, and how do you fix it?','An infinite loop usually happens when an effect updates a piece of state that is also listed in its dependency array, causing the effect to re-run after every render it triggers. The fix is to either remove the unnecessary dependency, use a functional state update that doesn''t need the value as a dependency, or restructure the logic so the effect doesn''t need to depend on the state it''s setting.',null,'useEffect(() => {
  setCount(count + 1); // depends on and updates ''count'' -> infinite loop
}, [count]);','jsx','medium',ARRAY['react','hooks','useeffect']::text[],true,120),
('react','hooks','react-hooks-121','What does the react-hooks/exhaustive-deps ESLint rule check, and why does it matter?','It statically analyzes an effect, or useMemo/useCallback, and warns when a value used inside is missing from the dependency array, since that''s the most common source of stale-closure bugs. It''s a strong default to follow, though there are rare, well-understood cases, like intentionally running an effect only once, where suppressing it with a comment is appropriate rather than papering over a real bug.',null,null,null,'medium',ARRAY['react','hooks','eslint','useeffect']::text[],false,121),
('react','hooks','react-hooks-122','Does React call an effect''s cleanup function differently on unmount versus a dependency change?','The cleanup runs the same way in both cases — right before the effect runs again for a dependency change, and once more on unmount — so the cleanup function can''t easily tell which case triggered it. If different behavior is needed for unmount specifically, that distinction has to be tracked manually, for example with a ref flag, rather than relied upon from the cleanup call itself.',null,null,null,'medium',ARRAY['react','hooks','useeffect']::text[],false,122),
('react','hooks','react-hooks-123','What does passing an empty dependency array to useEffect mean, and when is it a mistake?','An empty array tells React the effect doesn''t depend on any reactive value, so it should run only once after the initial render and its cleanup only on unmount, appropriate for a one-time subscription or fetch that doesn''t depend on props or state. It''s a mistake when the effect body actually reads props or state, since the effect will then silently keep using the original values forever.',null,'useEffect(() => {
  document.title = ''Dashboard'';
}, []); // runs once, fine — doesn''t depend on props/state','jsx','easy',ARRAY['react','hooks','useeffect']::text[],false,123),
('react','hooks','react-hooks-124','Can a custom hook share state between two different components?','Not by itself — each component that calls a custom hook gets its own independent instance of any useState inside it, so the hook alone doesn''t share state across components. To actually share state, the hook needs to read from something external and shared, like a module-level variable, Context, or an external store.',null,null,null,'medium',ARRAY['react','hooks','custom-hooks']::text[],false,124),
('react','hooks','react-hooks-125','Why would you wrap an object or array in useMemo before passing it as a prop?','Without useMemo, a new object or array literal is created on every render, giving it a new reference each time — so a child wrapped in React.memo would still re-render because its prop "changed" by reference even though its contents are identical. Memoizing the object keeps the same reference across renders as long as its dependencies haven''t changed, letting a memoized child correctly skip re-rendering.',null,'const options = useMemo(() => ({ page, pageSize }), [page, pageSize]);
<MemoizedList options={options} />','jsx','medium',ARRAY['react','hooks','usememo','performance']::text[],false,125),
('react','hooks','react-hooks-126','What''s a common mistake when using useCallback?','A common mistake is omitting a value the callback actually closes over from its dependency array, which "freezes" the callback with a stale version of that value — functionally the same stale-closure bug as with useEffect. Another is wrapping every handler in useCallback reflexively even when nothing downstream benefits from a stable reference, adding overhead without a real payoff.',null,'const onSave = useCallback(() => save(id), []); // missing ''id'' -> always saves the first id','jsx','medium',ARRAY['react','hooks','usecallback']::text[],true,126),
('react','hooks','react-hooks-127','Why must hooks always be called in the same order on every render?','React tracks each hook call by its position within a component using an internal list associated with that component''s instance, not by name — so if a hook is skipped on one render due to a condition or early return but called on the next, every subsequent hook''s stored state gets misaligned with the wrong call. Always calling hooks unconditionally at the top level keeps that internal list stable between renders.',null,null,null,'hard',ARRAY['react','hooks']::text[],true,127),
('react','hooks','react-hooks-128','How do you replicate componentDidMount''s behavior using hooks?','Use useEffect with an empty dependency array — since the effect runs once after the first render and never again unless the component unmounts and remounts, it behaves equivalently to componentDidMount for run-once setup logic like an initial data fetch.',null,'useEffect(() => {
  fetchInitialData();
}, []);','jsx','easy',ARRAY['react','hooks','useeffect','lifecycle']::text[],false,128),
('react','hooks','react-hooks-129','How do you replicate componentDidUpdate using hooks?','List the specific props or state you want to react to in useEffect''s dependency array — the effect then runs after every render where one of those values changed, similar to checking prevProps inside componentDidUpdate. Unlike componentDidUpdate, the effect also runs after the very first render unless you explicitly guard against that with a ref-based check.',null,'useEffect(() => {
  console.log(''userId changed to'', userId);
}, [userId]);','jsx','medium',ARRAY['react','hooks','useeffect','lifecycle']::text[],false,129),
('react','hooks','react-hooks-130','How do you replicate componentWillUnmount using hooks?','Return a cleanup function from useEffect — React calls it right before the component unmounts, and also before the effect re-runs due to a dependency change, so unsubscribing, clearing timers, or cancelling requests belongs inside that returned function.',null,'useEffect(() => {
  const id = setInterval(tick, 1000);
  return () => clearInterval(id); // like componentWillUnmount
}, []);','jsx','easy',ARRAY['react','hooks','useeffect','lifecycle']::text[],false,130),
('react','hooks','react-hooks-131','How did automatic state batching change between React 17 and React 18?','In React 17, multiple setState calls were only batched into a single re-render inside React event handlers — calls inside promises, setTimeout, or native event listeners each triggered a separate re-render. React 18''s automatic batching extends that behavior everywhere by default, so multiple state updates anywhere are batched into one re-render unless explicitly opted out with flushSync.',null,'setTimeout(() => {
  setA(1);
  setB(2); // React 18: one re-render. React 17: two re-renders.
}, 0);','jsx','hard',ARRAY['react','hooks','usestate','performance']::text[],false,131),
('react','hooks','react-hooks-132','Can the function you pass directly to useEffect be async?','No — useEffect expects its callback to return either nothing or a cleanup function, but an async function always returns a Promise, which React can''t use as a cleanup function and will warn about. Instead, define an async function inside the effect and call it immediately, or use .then() directly.',null,'useEffect(() => {
  async function load() { setData(await fetchData()); }
  load();
}, []);','jsx','easy',ARRAY['react','hooks','useeffect','async']::text[],false,132),
('react','hooks','react-hooks-133','What is the standard pattern for subscribing to a browser event inside useEffect?','Add the listener inside the effect body and return a cleanup function that removes the exact same listener reference, so the subscription is properly torn down when dependencies change or the component unmounts — forgetting the cleanup is a common source of duplicate listeners and memory leaks.',null,'useEffect(() => {
  const onScroll = () => setY(window.scrollY);
  window.addEventListener(''scroll'', onScroll);
  return () => window.removeEventListener(''scroll'', onScroll);
}, []);','jsx','medium',ARRAY['react','hooks','useeffect']::text[],false,133),
('react','hooks','react-hooks-134','When is wrapping a value in useMemo not worth it?','If the computation is cheap, like a simple arithmetic expression or string concatenation, the overhead of tracking dependencies and comparing them on every render can outweigh the cost of just recomputing the value directly. useMemo pays off for genuinely expensive computations or when referential stability is needed downstream, not as a reflexive wrapper around every derived value.',null,null,null,'medium',ARRAY['react','hooks','usememo','performance']::text[],false,134),
('react','hooks','react-hooks-135','When does wrapping a function in useCallback provide no real benefit?','If the function isn''t passed to a memoized child component or used as a dependency elsewhere, memoizing its reference doesn''t prevent any actual re-render or recomputation — it just adds the overhead of the dependency check for no payoff. useCallback is worth it specifically when a stable reference is required downstream, not as a default habit on every handler.',null,null,null,'medium',ARRAY['react','hooks','usecallback','performance']::text[],false,135),
('react','hooks','react-hooks-136','How do you access a prop or state''s previous value using useRef?','Store the current value in a ref inside a useEffect that runs after every render, so by the time the next render happens, the ref still holds the value from the render before — a common "usePrevious" custom hook pattern.',null,'function usePrevious(value) {
  const ref = useRef();
  useEffect(() => { ref.current = value; });
  return ref.current;
}','jsx','medium',ARRAY['react','hooks','useref','custom-hooks']::text[],false,136),
('react','hooks','react-hooks-137','How would you measure a DOM element''s size using useRef?','Attach the ref to the element via the ref attribute, then read its dimensions with methods like getBoundingClientRect() — typically inside a useLayoutEffect so the measurement happens synchronously after the DOM updates but before the browser paints, avoiding a visible jump.',null,'const boxRef = useRef(null);
useLayoutEffect(() => {
  const { width } = boxRef.current.getBoundingClientRect();
  setWidth(width);
}, []);','jsx','medium',ARRAY['react','hooks','useref','uselayouteffect']::text[],false,137),
('react','hooks','react-hooks-138','What''s a common pitfall with a context''s default value?','If a component calls useContext without ever being wrapped by a matching Provider, it silently receives the default value passed to createContext instead of an error, which can mask a missing Provider and cause confusing bugs. A common mitigation is to default the context to null and throw a clear error from a wrapper hook if no Provider was found.',null,'function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error(''useAuth must be used within AuthProvider'');
  return ctx;
}','jsx','medium',ARRAY['react','hooks','usecontext']::text[],false,138),
('react','hooks','react-hooks-139','What is the third argument to useReducer used for?','The optional third argument is an init function that lazily computes the initial state from the second argument, which is useful when the initial state is expensive to compute or needs to be derived from props — similar in spirit to useState''s lazy initializer function.',null,'function init(initialCount) { return { count: initialCount }; }
const [state, dispatch] = useReducer(reducer, initialCount, init);','jsx','medium',ARRAY['react','hooks','usereducer']::text[],false,139),
('react','hooks','react-hooks-140','What''s a common convention for structuring useReducer actions?','Actions are typically plain objects with a type string field describing what happened, often an event name like ''user/loaded'', plus an optional payload field carrying any data the reducer needs — mirroring the Flux/Redux action shape even outside of Redux itself.',null,'dispatch({ type: ''user/loaded'', payload: user });','jsx','easy',ARRAY['react','hooks','usereducer']::text[],false,140),
('react','hooks','react-hooks-141','Does the dispatch function returned by useReducer change between renders?','No — React guarantees that the dispatch function''s identity is stable for the lifetime of the component, so it''s safe to omit from dependency arrays and to pass down to deeply nested components without causing extra re-renders.',null,null,null,'easy',ARRAY['react','hooks','usereducer']::text[],false,141),
('react','hooks','react-hooks-142','Should a custom hook return an array or an object?','Return an array, like useState does, when there are only one or two values and callers will likely want to rename them freely via destructuring. Return an object when there are several values, since named destructuring is more self-documenting and doesn''t depend on a fixed positional order.',null,'const [value, setValue] = useToggle(false); // array: order matters, free naming
const { data, loading, error } = useFetch(url); // object: self-documenting','jsx','easy',ARRAY['react','hooks','custom-hooks']::text[],false,142),
('react','hooks','react-hooks-143','If a component has multiple useEffect calls, in what order do they run?','They run in the order they''re declared in the component, top to bottom, after the render has committed to the DOM — and their cleanup functions likewise run in that same declared order before the effects re-run or the component unmounts.',null,null,null,'medium',ARRAY['react','hooks','useeffect']::text[],false,143),
('react','hooks','react-hooks-144','Why would you specifically choose useLayoutEffect for a DOM measurement instead of useEffect?','Because useEffect runs after the browser paints, any state update triggered by a measurement made there causes a visible flash of the un-adjusted layout before the corrected one appears. useLayoutEffect runs synchronously before the paint, so a measurement-driven adjustment is applied before the user ever sees the wrong frame.',null,null,null,'medium',ARRAY['react','hooks','uselayouteffect']::text[],false,144),
('react','hooks','react-hooks-145','Why does React warn about useLayoutEffect during server-side rendering?','useLayoutEffect never runs on the server since there''s no DOM or paint step to synchronize with, so React warns that its effect is being skipped, which can cause a mismatch between the server-rendered markup and what the client expects before hydration. The common workaround is a small hook that falls back to useEffect when running in a non-browser environment.',null,'const useIsomorphicLayoutEffect = typeof window !== ''undefined'' ? useLayoutEffect : useEffect;','jsx','hard',ARRAY['react','hooks','uselayouteffect','ssr']::text[],false,145),
('react','hooks','react-hooks-146','What does forwardRef do?','forwardRef lets a functional component accept a ref from its parent and forward it to a specific child element, usually a DOM node, inside it, since function components don''t receive refs as a regular prop by default. It''s commonly used to let a parent focus or measure an underlying input rendered by a reusable component.',null,'const FancyInput = forwardRef((props, ref) => <input ref={ref} className="fancy" {...props} />);','jsx','easy',ARRAY['react','hooks','forwardref']::text[],false,146),
('react','hooks','react-hooks-147','How does eslint-plugin-react-hooks help enforce the rules of hooks?','Its rules-of-hooks rule statically analyzes the code and flags hook calls that appear inside conditionals, loops, or nested functions, or in a non-component/non-hook function, catching violations at lint time before they cause runtime state-mismatch bugs. It complements, but doesn''t replace, the exhaustive-deps rule, which separately checks dependency arrays.',null,null,null,'easy',ARRAY['react','hooks','eslint']::text[],false,147),
('react','hooks','react-hooks-148','What does a renderHook-style testing utility provide?','It mounts a custom hook inside a hidden test component and returns a result object whose .current property reflects the hook''s latest return value, plus helpers to trigger re-renders and wrap state updates in act() — letting you assert on a hook''s behavior directly without writing a throwaway UI component yourself.',null,null,null,'medium',ARRAY['react','hooks','testing']::text[],false,148),
('react','hooks','react-hooks-149','Why does React warn "Cannot update a component while rendering a different component"?','Calling a state setter directly in the body of a render function, rather than in an effect or event handler, can trigger a synchronous re-render of another component while the current one is still rendering, leading to inconsistent state and potential infinite loops. The fix is almost always to move that setState call into a useEffect or an event handler instead.',null,null,null,'medium',ARRAY['react','hooks','usestate']::text[],false,149),
('react','hooks','react-hooks-150','How can a ref be used to always call the latest version of a prop function from inside a stable callback?','Store the latest function in a ref, updating it on every render, then have the stable callback (for example useCallback with empty deps) read and invoke ref.current instead of closing over the function directly — this avoids re-creating the stable callback just to pick up a new function reference, while still always calling the freshest version.',null,'const onSaveRef = useRef(onSave);
useEffect(() => { onSaveRef.current = onSave; });
const stableSave = useCallback((data) => onSaveRef.current(data), []);','jsx','hard',ARRAY['react','hooks','useref','usecallback']::text[],false,150),
('react','performance','react-performance-101','How do you use the React DevTools Profiler to diagnose a performance problem?','The Profiler tab records a session while you interact with the app, then shows a flame graph of every commit with how long each component took to render and why it rendered (props changed, state changed, parent re-rendered, etc.). You look for components that render often or take disproportionately long, then work backward to find the state update or prop change triggering them. It''s the standard first step before reaching for memoization, since it tells you where the actual cost is instead of guessing.',null,null,null,'medium',ARRAY['react','performance','devtools']::text[],true,101),
('react','performance','react-performance-102','How would you identify which prop or state change caused a slow re-render?','The DevTools Profiler can highlight the reason for each render ("why did this render") when that setting is enabled, showing which props or state changed. For a manual check, a useEffect that logs the changed props/state on every render, or a small custom hook that diffs the previous and current props, can pinpoint the culprit without any extra tooling.',null,'function useWhyDidYouUpdate(name, props) {
  const prev = useRef(props);
  useEffect(() => {
    const changed = Object.entries(props).filter(([k, v]) => prev.current[k] !== v);
    if (changed.length) console.log(name, ''changed:'', changed);
    prev.current = props;
  });
}','jsx','medium',ARRAY['react','performance','debugging']::text[],false,102),
('react','performance','react-performance-103','Give an example of using useMemo to avoid recomputing an expensive value on every render.','useMemo caches the result of a computation and only recalculates it when the values in its dependency array change, instead of on every render. It''s most useful for genuinely expensive work like sorting or filtering a large array, not trivial arithmetic where the memoization overhead can outweigh the savings.',null,'const sortedUsers = useMemo(
  () => [...users].sort((a, b) => b.score - a.score),
  [users]
);','jsx','medium',ARRAY['react','performance','usememo']::text[],true,103),
('react','performance','react-performance-104','How does useCallback prevent a memoized child component from re-rendering unnecessarily?','Without useCallback, a function defined inside a component body is a new reference on every render, which breaks React.memo''s shallow prop comparison on any child that receives it as a prop. useCallback returns the same function reference across renders as long as its dependencies haven''t changed, so a memoized child receiving it as a prop can correctly skip re-rendering.',null,'const handleSelect = useCallback((id) => setSelectedId(id), []);
return <MemoizedList items={items} onSelect={handleSelect} />;','jsx','medium',ARRAY['react','performance','usecallback']::text[],false,104),
('react','performance','react-performance-105','How can changing a component''s key be used to reset its internal state and remount it?','React uses the key prop to decide whether to reuse or discard a component instance between renders. Changing the key forces React to unmount the old instance (discarding all its internal state and effects) and mount a fresh one, which is a simple way to fully reset a complex form or widget instead of manually clearing every piece of state.',null,'<UserForm key={selectedUserId} userId={selectedUserId} />','jsx','medium',ARRAY['react','performance','key']::text[],false,105),
('react','performance','react-performance-106','Why does passing a new object or array literal as a prop on every render defeat React.memo?','React.memo does a shallow comparison of props, and object/array literals created inline (e.g. style={{ color: ''red'' }}) produce a brand-new reference every render even if the contents are identical. That means the shallow comparison always reports "changed," so the memoized child re-renders anyway — the fix is to hoist the literal outside the component or wrap it in useMemo.',null,'// Bad: new object every render
<Chart options={{ responsive: true }} />

// Better: stable reference
const chartOptions = useMemo(() => ({ responsive: true }), []);
<Chart options={chartOptions} />','jsx','medium',ARRAY['react','performance','memo']::text[],false,106),
('react','performance','react-performance-107','Are inline arrow functions in JSX actually a performance problem?','In most apps, no — creating a new function on every render is cheap, and modern JS engines handle it fine. It only becomes a real problem when that function is passed as a prop to a component wrapped in React.memo, because the new reference breaks the memoization and causes an otherwise-avoidable re-render; in that specific case, useCallback is worth reaching for.',null,null,null,'easy',ARRAY['react','performance']::text[],false,107),
('react','performance','react-performance-108','How would you lazy-load an image that''s below the fold in a React app?','The simplest approach is the native loading="lazy" attribute on an <img> tag, which defers loading until the image is near the viewport with no JavaScript required. For more control (like showing a placeholder or triggering earlier), an IntersectionObserver-based custom hook can toggle the image''s src only once it''s about to enter view.',null,'<img src={photo.url} loading="lazy" alt={photo.alt} />','jsx','easy',ARRAY['react','performance','images']::text[],false,108),
('react','performance','react-performance-109','What is route-based code splitting and how does it differ from lazy-loading a single component?','Route-based code splitting applies React.lazy at the routing layer so each page''s JS bundle is only downloaded when the user actually navigates to that route, rather than as part of the initial bundle. It differs from lazy-loading one component (like a modal) in scale and intent: it''s a deliberate architectural strategy to keep the initial load small, applied consistently across every top-level route rather than to a single heavy widget.',null,'const Dashboard = lazy(() => import(''./pages/Dashboard''));
const Settings = lazy(() => import(''./pages/Settings''));

<Routes>
  <Route path="/dashboard" element={<Dashboard />} />
  <Route path="/settings" element={<Settings />} />
</Routes>','jsx','medium',ARRAY['react','performance','code-splitting']::text[],false,109),
('react','performance','react-performance-110','How does tree-shaking reduce bundle size, and what can prevent it from working?','Tree-shaking is a build-time step where the bundler analyzes ES module imports/exports and removes code that''s never actually used, relying on the static (not dynamic) nature of ES module syntax to prove what''s safe to drop. It''s defeated by importing an entire library''s default export (e.g. import _ from ''lodash'' instead of import debounce from ''lodash/debounce''), by libraries shipped only as CommonJS, or by side-effectful module code the bundler can''t prove is safe to remove.',null,null,null,'medium',ARRAY['react','performance','bundling']::text[],false,110),
('react','performance','react-performance-111','Why should selectors reading from a global store be memoized?','A selector that derives a new array or object from store state (e.g. filtering a list) returns a new reference every time it runs, which can make consuming components think the data changed even when the underlying source didn''t, triggering unnecessary re-renders. Memoizing the selector (e.g. with reselect-style caching) ensures it only recomputes and returns a new reference when its actual inputs change.',null,'const selectActiveUsers = createSelector(
  (state) => state.users,
  (users) => users.filter((u) => u.active)
);','jsx','medium',ARRAY['react','performance','state-management']::text[],false,111),
('react','performance','react-performance-112','How can prop drilling contribute to unnecessary re-renders across a wide component tree?','When a value is passed down through several intermediate components just to reach a deeply nested one, every intermediate component re-renders whenever that value changes, even if it never uses the value itself. Lifting the value into Context or a store lets only the components that actually consume it re-render, rather than the whole chain in between.',null,null,null,'easy',ARRAY['react','performance','prop-drilling']::text[],false,112),
('react','performance','react-performance-113','Why can a Context value cause every consumer to re-render even if only part of the value changed?','Context consumers re-render whenever the Provider''s value prop changes by reference, regardless of which specific field inside that value actually changed. If the value is a single object containing many unrelated pieces of state, updating any one of them creates a new object and re-renders every consumer, even ones that only cared about a field that didn''t change.',null,'// One consumer only needs `theme`, but re-renders when `user` changes too
const { theme, user } = useContext(AppContext);','jsx','medium',ARRAY['react','performance','context']::text[],false,113),
('react','performance','react-performance-114','How would you debounce a search input''s onChange handler in a React component?','Keep the input''s displayed value in local state so typing feels instant, but wrap the expensive operation (an API call or a heavy filter) in a debounced function via useMemo or useEffect with a timeout, so it only fires once the user pauses typing. useDeferredValue in React 18 offers a related, built-in alternative for deferring a derived render without manually managing timers.',null,'const [query, setQuery] = useState('''');
useEffect(() => {
  const id = setTimeout(() => fetchResults(query), 300);
  return () => clearTimeout(id);
}, [query]);','jsx','medium',ARRAY['react','performance','debounce']::text[],true,114),
('react','performance','react-performance-115','What are the trade-offs of using react-window or react-virtualized for large lists?','Both libraries render only the rows currently visible in the viewport (plus a small buffer), dramatically cutting DOM node count and improving scroll performance for lists with thousands of items. The trade-off is added complexity: rows typically need a fixed or measurable height, browser find-in-page and some accessibility patterns need extra handling, and the API adds a layer of indirection compared to a plain .map().',null,null,null,'medium',ARRAY['react','performance','virtualization']::text[],false,115),
('react','performance','react-performance-116','How can reading layout properties like offsetHeight inside a useEffect cause layout thrashing?','Reading a layout property forces the browser to synchronously recalculate layout if any pending DOM writes haven''t been flushed yet. Interleaving reads and writes across multiple effects (read, write, read, write) forces this recalculation repeatedly in the same frame instead of once, which can visibly slow down updates — batching all reads before all writes, or using useLayoutEffect deliberately and sparingly, avoids the thrashing.',null,null,null,'hard',ARRAY['react','performance','dom']::text[],false,116),
('react','performance','react-performance-117','What performance benefit does React 18''s automatic batching provide?','Before React 18, multiple setState calls inside a promise callback, setTimeout, or native event handler each triggered a separate re-render. React 18 batches all state updates within a single tick automatically regardless of where they occur, so several setState calls in an async handler now produce just one re-render instead of several.',null,'function handleClick() {
  fetchData().then(() => {
    setLoading(false); // batched
    setData(result);   // batched — only one re-render total
  });
}','jsx','medium',ARRAY['react','performance','react-18']::text[],false,117),
('react','performance','react-performance-118','What does "concurrent rendering" mean in React 18+?','Concurrent rendering lets React prepare (render) multiple versions of the UI without committing them, and interrupt, pause, or abandon a render in progress if something more urgent (like user input) comes in. This is what enables features like useTransition and Suspense to keep an app responsive during expensive updates, in contrast to React''s older synchronous renderer which always ran a render to completion once started.',null,null,null,'hard',ARRAY['react','performance','concurrent-rendering']::text[],true,118),
('react','performance','react-performance-119','What problem does useTransition solve?','useTransition lets you mark a state update as non-urgent, so React can render it in the background and keep the UI responsive to more urgent updates (like typing) instead of blocking the main thread. A common use case is filtering a large list as the user types: the input stays instantly responsive while the (potentially slow) filtered list update happens as a lower-priority transition.',null,'const [isPending, startTransition] = useTransition();

function handleChange(e) {
  setQuery(e.target.value); // urgent
  startTransition(() => {
    setFilteredList(filterItems(e.target.value)); // non-urgent
  });
}','jsx','medium',ARRAY['react','performance','usetransition']::text[],true,119),
('react','performance','react-performance-120','What does useDeferredValue do and how does it differ from debouncing?','useDeferredValue returns a version of a value that "lags behind" the real value during expensive renders, letting React prioritize more urgent updates first and catch up when it has spare time. Unlike debouncing, it doesn''t use a fixed timer — React decides when to update the deferred value based on actual rendering capacity, so it adapts to the device''s performance instead of an arbitrary delay.',null,'const deferredQuery = useDeferredValue(query);
const results = useMemo(() => search(deferredQuery), [deferredQuery]);','jsx','medium',ARRAY['react','performance','usedeferredvalue']::text[],false,120),
('react','performance','react-performance-121','Which Web Vitals metrics are most relevant to a React app''s perceived performance?','Largest Contentful Paint (LCP) measures how long the main content takes to appear, which is heavily influenced by initial bundle size and data-fetch waterfalls in a React SPA. Interaction to Next Paint (INP) measures how responsive the app feels to clicks and typing, which is directly affected by expensive re-renders and long-running synchronous work on the main thread — exactly what memoization and transitions aim to fix.',null,null,null,'easy',ARRAY['react','performance','web-vitals']::text[],false,121),
('react','performance','react-performance-122','Why might having too many separate Context consumers hurt performance?','Every component that calls useContext subscribes to that Context and re-renders whenever its value changes, so spreading dozens of components across the tree as direct consumers of a frequently-updating Context means dozens of re-renders per update. Reducing the number of direct consumers (by reading the value once near the top and passing down only what''s needed, or splitting the Context) limits the blast radius of each update.',null,null,null,'medium',ARRAY['react','performance','context']::text[],false,122),
('react','performance','react-performance-123','Why would you split one large Context into several smaller ones?','If unrelated pieces of state (like theme and user session) live in one Context object, updating either one re-renders every consumer of the whole Context, including ones that only care about the other piece. Splitting into separate Context providers means a component only re-renders when the specific slice of state it actually reads changes.',null,'// Instead of one AppContext with { theme, user, cart }
const ThemeContext = createContext();
const UserContext = createContext();
const CartContext = createContext();','jsx','medium',ARRAY['react','performance','context']::text[],false,123),
('react','performance','react-performance-124','Can over-memoizing a component ever hurt performance?','Yes — every useMemo, useCallback, or React.memo adds a comparison check that itself costs time and memory, so wrapping cheap components or trivial computations in memoization can end up being slower than just letting them re-render normally. Memoization pays off when the wrapped work is genuinely expensive or the component re-renders very frequently with unchanged props; it shouldn''t be applied by default everywhere.',null,null,null,'medium',ARRAY['react','performance','memoization']::text[],false,124),
('react','performance','react-performance-125','What''s the difference between React''s render phase and commit phase, and why do side effects belong in the commit phase?','The render phase is where React calls your component functions to figure out what should change — it''s meant to be pure and can be paused, aborted, or restarted by React (especially under concurrent rendering), so it must have no side effects. The commit phase is where React actually applies changes to the real DOM and is guaranteed to run to completion, which is why useEffect (and DOM mutations, subscriptions, etc.) runs after commit rather than during render.',null,null,null,'hard',ARRAY['react','performance','internals']::text[],true,125),
('react','performance','react-performance-126','Why can inline style objects in JSX be less performant than CSS classes?','An inline style={{ ... }} object is a new object on every render, which both forces a new style recalculation and (as with any inline object) can break shallow prop comparisons on memoized children. CSS classes are parsed once by the browser and applying/removing them is comparatively cheap, and they also allow the browser to cache computed styles more effectively.',null,'// Less ideal
<div style={{ color: isActive ? ''blue'' : ''gray'' }} />

// Better
<div className={isActive ? ''text-active'' : ''text-inactive''} />','jsx','easy',ARRAY['react','performance','styling']::text[],false,126),
('react','performance','react-performance-127','Why does using array index as a key combined with .map() sometimes cause unnecessary re-renders?','When items are reordered, inserted, or removed, an index-based key stays attached to the same position rather than the same logical item, so React thinks the item at that position simply "changed" and re-renders/reconciles it with new props instead of recognizing it moved. Using a stable, unique identifier from the data itself (like an id) lets React correctly match items across renders and skip unnecessary work for items that didn''t actually change.',null,'// Fragile: index changes when list is reordered
{items.map((item, i) => <Row key={i} {...item} />)}

// Stable
{items.map((item) => <Row key={item.id} {...item} />)}','jsx','medium',ARRAY['react','performance','key']::text[],false,127),
('react','performance','react-performance-128','What strategies exist for optimizing images in a React application?','Serving correctly sized and modern-format images (WebP/AVIF), using loading="lazy" for offscreen images, specifying width/height to avoid layout shift, and using a CDN or image optimization service to generate responsive srcset variants are the main levers. None of these are React-specific, but they matter disproportionately in SPAs since images are often the largest contributor to LCP.',null,null,null,'easy',ARRAY['react','performance','images']::text[],false,128),
('react','performance','react-performance-129','At a high level, how do React Server Components reduce client-side work?','Server Components render on the server and send the result to the client as a lightweight description rather than shipping the component''s JavaScript to the browser at all, which reduces both bundle size and the amount of client-side rendering work. This is distinct from traditional SSR, which still ships the component code to the client for hydration — Server Components never run on the client in the first place.',null,null,null,'hard',ARRAY['react','performance','server-components']::text[],true,129),
('react','performance','react-performance-130','What is a request waterfall in data fetching and how can you avoid one in a React app?','A waterfall happens when a child component''s data fetch only starts after its parent''s fetch has finished and it has rendered, turning what could be parallel requests into a slow sequential chain. Avoiding it means starting independent fetches as early and in parallel as possible — for example, kicking off all needed requests at the top of a route before rendering children, or using Promise.all, rather than letting each nested component trigger its own fetch on mount.',null,'// Waterfall: profile fetch waits, then posts fetch waits
// Better: fire both immediately
const [profile, posts] = await Promise.all([fetchProfile(id), fetchPosts(id)]);','jsx','medium',ARRAY['react','performance','data-fetching']::text[],false,130),
('react','performance','react-performance-131','How can you use the <Profiler> component programmatically instead of just the DevTools Profiler UI?','Wrapping part of the tree in React''s built-in <Profiler> component with an onRender callback lets you capture render timings (actual duration, base duration, phase) in code, which is useful for automated performance regression tests or logging real-user render times in production, not just manual inspection in DevTools.',null,'<Profiler id="Dashboard" onRender={(id, phase, actualDuration) => {
  console.log(id, phase, actualDuration);
}}>
  <Dashboard />
</Profiler>','jsx','medium',ARRAY['react','performance','profiler']::text[],false,131),
('react','performance','react-performance-132','Why might a large component tree benefit from splitting into smaller components even without memoization?','Splitting a large component into smaller ones creates natural re-render boundaries: when state changes inside a small child, only that child (and its own children) re-renders, rather than the entire large component and everything inside it having to re-execute. This structural benefit comes for free from component composition, before any memoization is even introduced.',null,null,null,'easy',ARRAY['react','performance','components']::text[],false,132),
('react','performance','react-performance-133','What is the difference between the shallow comparison used by React.memo and deep equality?','React.memo''s default comparison checks each prop with Object.is (reference equality for objects/arrays/functions, value equality for primitives) one level deep — it does not look inside nested objects to see if their contents match. Deep equality would recursively compare every nested value, which is more accurate but far more expensive to run on every render, which is why React deliberately defaults to the cheaper shallow check.',null,'// Same content, different reference — shallow comparison says "changed"
React.memo(Chart)({ config: { color: ''red'' } });
React.memo(Chart)({ config: { color: ''red'' } });','jsx','medium',ARRAY['react','performance','memo']::text[],false,133),
('react','performance','react-performance-134','How does the useState functional updater form help avoid unnecessary effect dependencies?','Using setCount(c => c + 1) instead of setCount(count + 1) lets a callback update state based on the latest value without needing count itself in its closure or a useEffect dependency array, which avoids re-creating that callback (and re-running effects that depend on it) every time count changes.',null,'const increment = useCallback(() => {
  setCount((c) => c + 1); // no need to list `count` as a dependency
}, []);','jsx','medium',ARRAY['react','performance','usestate']::text[],false,134),
('react','performance','react-performance-135','Why can spreading all props ({...props}) onto a DOM element hurt performance and cause bugs?','Spreading an entire props object onto a native DOM element passes through anything the caller included, including props that aren''t valid HTML attributes, which React will warn about and the browser will ignore or mishandle. It also makes it harder for React (and the developer) to reason about which specific values actually affect rendering, since the element re-renders whenever any prop in that spread object changes, even unrelated ones.',null,'// Risky: passes through arbitrary props, including invalid HTML attrs
function Input(props) { return <input {...props} />; }','jsx','easy',ARRAY['react','performance','props']::text[],false,135),
('react','performance','react-performance-136','What''s the performance cost of creating a new array with .filter().map() on every render for a large list?','For a large array, chaining .filter().map() allocates two new arrays and does two full passes every single render, even if the underlying data hasn''t changed. Wrapping the derived array in useMemo keyed on the actual dependencies (the source array and filter criteria) avoids redoing that work on renders where nothing relevant changed.',null,'const visibleItems = useMemo(
  () => items.filter((i) => i.active).map((i) => ({ ...i, label: i.name.toUpperCase() })),
  [items]
);','jsx','medium',ARRAY['react','performance','usememo']::text[],false,136),
('react','performance','react-performance-137','How would you avoid re-creating a regex or complex object on every render?','If the value never depends on props or state, define it once outside the component (as a module-level constant) instead of inside the render function, so it''s created a single time regardless of how many times the component re-renders. If it does depend on props/state but is expensive to build, useMemo is the right tool instead.',null,'// Outside the component — created once, not per render
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(email) { return EMAIL_REGEX.test(email); }','jsx','easy',ARRAY['react','performance']::text[],false,137),
('react','performance','react-performance-138','What role does the diffing algorithm''s O(n) heuristic play in keeping reconciliation fast?','A fully general tree-diffing algorithm is O(n^3) in the number of nodes, which would be far too slow for UI updates. React''s reconciler instead uses heuristics — comparing elements of the same type at the same tree position, and using keys to match items in a list — reducing the comparison to roughly O(n), trading some theoretical accuracy (it can miss some optimal diffs) for practical speed.',null,null,null,'hard',ARRAY['react','performance','internals']::text[],false,138),
('react','performance','react-performance-139','Why is it recommended to avoid deeply nested Context providers for frequently changing values?','Every level of nested Context adds another subscription point, and if a frequently-updating value sits high in a deeply nested provider tree, every consumer anywhere below it re-renders on each update regardless of how deep it''s nested. For fast-changing values, keeping the state as local as possible, or using a store with fine-grained subscriptions instead of Context, avoids that broad re-render fan-out.',null,null,null,'medium',ARRAY['react','performance','context']::text[],false,139),
('react','performance','react-performance-140','What''s the benefit of colocating state as close as possible to where it''s used ("state colocation")?','Keeping state in the smallest, lowest component that needs it means updates to that state only re-render that component and its children, instead of a higher-up ancestor and its entire subtree. It also makes the codebase easier to reason about, since state that''s only relevant to one small piece of UI doesn''t leak into a larger shared scope.',null,null,null,'easy',ARRAY['react','performance','state']::text[],true,140),
('react','performance','react-performance-141','How can you measure the actual bundle size impact of a dependency before adding it?','Tools like a bundler''s built-in analyzer (e.g. rollup-plugin-visualizer, webpack-bundle-analyzer) or bundlephobia.com show the real minified/gzipped size a package adds, including its own transitive dependencies, before you commit to using it. This catches cases where a convenience library turns out to add far more weight than its usefulness justifies.',null,null,null,'easy',ARRAY['react','performance','bundling']::text[],false,141),
('react','performance','react-performance-142','What''s the difference between prefetching and lazy-loading a route in a React SPA?','Lazy-loading defers downloading a route''s code until the user actually navigates to it, which keeps the initial bundle small but adds a delay the first time that route is visited. Prefetching goes a step further by downloading a lazily-loaded route''s code ahead of time — for example, when the user hovers a link — so that by the time they click, the code is already cached and the navigation feels instant.',null,null,null,'medium',ARRAY['react','performance','code-splitting']::text[],false,142),
('react','performance','react-performance-143','Why might a large useEffect dependency array with unstable references cause performance issues?','If any dependency in the array is a new object, array, or function reference on every render, the effect re-runs on every render regardless of whether anything meaningful actually changed — potentially re-subscribing, re-fetching, or re-computing on every single render. Stabilizing those dependencies with useMemo/useCallback, or restructuring the effect to depend on primitive values instead, fixes the thrashing.',null,'// Runs every render because `options` is a new object each time
useEffect(() => { subscribe(options); }, [options]);','jsx','medium',ARRAY['react','performance','useeffect']::text[],false,143),
('react','performance','react-performance-144','What performance considerations apply when rendering a table with thousands of rows and interactive cells?','Beyond virtualizing the rows themselves, each interactive cell (inputs, buttons, dropdowns) multiplies the DOM node count and event listener overhead, so it''s worth minimizing per-cell complexity and memoizing row components so editing one cell doesn''t re-render the entire table. Sorting, filtering, and aggregation should also happen off the render path (memoized or computed incrementally) rather than being recalculated from scratch on every keystroke or click.',null,null,null,'hard',ARRAY['react','performance','tables']::text[],false,144),
('react','performance','react-performance-145','How does memoizing a component with children still allow the children to re-render when they should?','React.memo only controls whether the wrapped component itself re-executes based on its own props; the children prop is just another prop, and if the parent passing those children re-renders and creates new child elements, the memoized wrapper still receives a "changed" children prop and re-renders, which then lets those children render normally. Memoization only helps when the children passed in are themselves stable across renders (e.g. passed down unchanged from a higher, less-frequently-updating ancestor).',null,null,null,'hard',ARRAY['react','performance','memo']::text[],false,145),
('react','performance','react-performance-146','Why can excessive use of the Context API for frequently updating values be worse than prop drilling?','Prop drilling at least lets intermediate components stay untouched if you thread props manually with care, and tools exist to flag unnecessary passes; Context, by contrast, silently subscribes every consumer in the tree to updates, so a fast-changing Context value can cause far more widespread re-rendering than explicit prop passing would, especially if consumers are spread across many unrelated branches.',null,null,null,'medium',ARRAY['react','performance','context']::text[],false,146),
('react','performance','react-performance-147','What tools can you use to detect memory leaks caused by uncanceled subscriptions in React components?','The browser DevTools Memory tab (taking heap snapshots before/after mounting and unmounting a component repeatedly) can reveal detached DOM nodes or growing listener counts that indicate a leak. React''s Strict Mode also helps surface these bugs in development by intentionally double-invoking effects, which exposes missing cleanup functions that would otherwise leak a subscription, timer, or event listener on unmount.',null,null,null,'medium',ARRAY['react','performance','memory-leaks']::text[],false,147),
('react','performance','react-performance-148','How would you profile and optimize a slow initial page load in a React app, beyond just code splitting?','Beyond splitting the bundle, look at the network waterfall for render-blocking resources, minimize the critical CSS/JS needed for first paint, preload key fonts and above-the-fold images, and check whether server-side rendering or static generation could deliver meaningful content before the JS bundle even finishes downloading. Lighthouse and the Performance tab in DevTools are the standard tools for surfacing exactly which resource or task is dominating the load timeline.',null,null,null,'medium',ARRAY['react','performance','initial-load']::text[],false,148),
('react','performance','react-performance-149','What''s the performance impact of anonymous inline event handlers versus useCallback-wrapped ones in most apps?','For a plain DOM element (a button, an input) the difference is negligible — React doesn''t need a stable reference to attach an event listener efficiently, so an inline arrow function is perfectly fine there. The distinction only matters when that handler is passed down as a prop to a child wrapped in React.memo, where an unstable reference would defeat the memoization; outside of that specific case, reaching for useCallback everywhere is unnecessary overhead.',null,null,null,'easy',ARRAY['react','performance','usecallback']::text[],false,149),
('react','performance','react-performance-150','Why does batching multiple setState calls into one render matter for performance?','Without batching, each setState call would trigger its own full render-and-commit cycle, so an event handler that calls setState three times would re-render the component three times in a row for work that only needed to happen once. Batching collects all the updates that occur within the same tick and applies them together in a single render, which is both faster and avoids showing the UI in a series of inconsistent intermediate states.',null,'function handleSubmit() {
  setLoading(false);
  setError(null);
  setData(result); // all three batched into a single re-render
}','jsx','easy',ARRAY['react','performance','batching']::text[],true,150),
('react','state','react-state-101','Why shouldn''t you store a value in state if it can be computed from existing props or state?','Storing a derivable value in its own state creates two sources of truth that can drift out of sync whenever the underlying data changes but you forget to update the derived copy. It''s simpler and safer to compute it directly during render, optionally memoized with useMemo if expensive, so it''s always consistent with its source data by construction.',null,null,null,'medium',ARRAY['react','state','derived-state']::text[],true,101),
('react','state','react-state-102','What''s the problem with syncing a prop into state using useEffect, and what''s the better alternative?','Copying a prop into local state via useEffect creates a state update that lags one render behind the prop change, causing a visible flash of stale data and an extra unnecessary render. If the component truly needs its own editable copy of the prop, it''s better to derive the initial value directly during the first render, and if the prop can change later and should reset the local copy, use a key prop to remount instead of syncing with an effect.',null,null,null,'hard',ARRAY['react','state','useeffect']::text[],false,102),
('react','state','react-state-103','What does "state colocation" mean in React?','It means keeping a piece of state as close as possible to the components that actually use it, rather than lifting everything to a shared ancestor by default. This limits the render impact of a state change to the smallest necessary part of the tree and keeps components easier to reason about in isolation.',null,null,null,'easy',ARRAY['react','state']::text[],false,103),
('react','state','react-state-104','What signals suggest a component''s state logic should move from useState to useReducer?','Signs include several related pieces of state that always change together, next-state calculations that depend on the previous state in non-obvious ways, or update logic scattered across many event handlers that would benefit from being centralized and unit-testable as a single pure function.',null,null,null,'medium',ARRAY['react','state','usereducer']::text[],false,104),
('react','state','react-state-105','Why must a reducer function passed to useReducer be pure?','React may call a reducer more than once per dispatched action in some cases, such as in development with Strict Mode to help surface side effects, so a reducer that mutates its arguments or performs side effects like network calls could produce inconsistent or duplicated results. A reducer should only compute and return a new state object based on its arguments, with no side effects or mutation.',null,null,null,'medium',ARRAY['react','state','usereducer']::text[],false,105),
('react','state','react-state-106','How do useReducer and Context combine to create a lightweight global state pattern?','A single useReducer call lives in a top-level provider component, and its state and dispatch function are exposed through one or two Context providers, letting any descendant read the shared state or dispatch actions to update it without prop drilling. This mimics the core Redux pattern of a single store, actions, and a reducer using only built-in React APIs, at the cost of Context''s re-render characteristics at larger scale.',null,'const StateContext = createContext(null);
const DispatchContext = createContext(null);
function Provider({ children }) {
  const [state, dispatch] = useReducer(reducer, initialState);
  return (
    <StateContext.Provider value={state}>
      <DispatchContext.Provider value={dispatch}>{children}</DispatchContext.Provider>
    </StateContext.Provider>
  );
}','jsx','hard',ARRAY['react','state','usereducer','context']::text[],false,106),
('react','state','react-state-107','What does it mean to "normalize" state shape, and why does it help?','Normalizing means storing collections as a flat map keyed by ID, similar to a database table, instead of deeply nested arrays of arrays. It makes updating or looking up a single item O(1) and avoids duplicating the same entity in multiple nested places, which is a common source of state getting out of sync.',null,'// nested (harder to update one comment)
{ posts: [{ id: 1, comments: [{ id: 10, text: ''...'' }] }] }

// normalized (easy to update by id)
{ posts: { 1: { id: 1, commentIds: [10] } }, comments: { 10: { id: 10, text: ''...'' } } }','jsx','medium',ARRAY['react','state','normalization']::text[],false,107),
('react','state','react-state-108','How do you update a deeply nested piece of state without mutating it?','Spread every level of the object from the changed property up to the root, creating new objects for each level along the path while reusing the untouched siblings by reference. This is verbose for deeply nested shapes, which is itself a good argument for normalizing state or using a library like Immer to write seemingly-mutable updates that produce immutable results.',null,'setUser(prev => ({
  ...prev,
  address: { ...prev.address, city: ''Austin'' },
}));','jsx','medium',ARRAY['react','state','immutability']::text[],true,108),
('react','state','react-state-109','How do you add, remove, and update an item in an array stored in state?','Add with the spread operator to create a new array including the new item, remove with Array.filter to build a new array excluding the target, and update with Array.map to return a new array where only the matching item is replaced with a modified copy — each produces a brand-new array rather than mutating the original with push or splice, which React needs to detect the change.',null,'setItems(prev => [...prev, newItem]); // add
setItems(prev => prev.filter(i => i.id !== id)); // remove
setItems(prev => prev.map(i => i.id === id ? { ...i, done: true } : i)); // update','jsx','easy',ARRAY['react','state','immutability']::text[],true,109),
('react','state','react-state-110','How can a stale closure cause a race condition when updating state?','If an async callback, like a fetch handler, was created during a render where a variable had an old value, calling a state setter inside it based on that captured variable can overwrite newer state with outdated data once it finally resolves, especially if a more recent render''s callback resolves first. Using functional state updates, or checking a ref or flag that tracks the latest request, avoids acting on outdated captured values.',null,null,null,'hard',ARRAY['react','state','async']::text[],false,110),
('react','state','react-state-111','Why should you prefer setCount(c => c + 1) over setCount(count + 1) in most cases?','The functional form always receives React''s latest pending state value rather than whatever count was when the closure was created, so it''s safe even when multiple updates are queued in the same tick or the handler is called from a stale closure like inside a timer. It removes an entire category of "off by one" state bugs caused by batching.',null,'setCount(c => c + 1);','jsx','easy',ARRAY['react','state','usestate']::text[],true,111),
('react','state','react-state-112','What is "automatic batching" in React 18?','React 18 batches multiple state updates that happen within the same synchronous block of code, including inside promises, timeouts, and native event handlers and not just React''s own event handlers as in React 17, into a single re-render for better performance. It can be opted out of for a specific update using flushSync when an immediate, unbatched render is genuinely required.',null,null,null,'medium',ARRAY['react','state','performance']::text[],false,112),
('react','state','react-state-113','At a high level, when would you reach for a dedicated state management library instead of just Context?','Once an app has a lot of frequently-changing shared state, many independent consumers that shouldn''t all re-render together, or needs like time-travel debugging and middleware, dedicated libraries such as Redux Toolkit, Zustand, Jotai, or Recoil offer more efficient selective subscriptions and tooling than plain Context, which re-renders every consumer on any value change by default.',null,null,null,'medium',ARRAY['react','state','state-management']::text[],false,113),
('react','state','react-state-114','Why can Context cause more re-renders than expected, and how do you mitigate it?','Every component that calls useContext for a given Context re-renders whenever that Context''s value changes, even if the component only cares about one field of a larger value object, and a new object literal passed as the value on every render defeats memoization entirely. Mitigations include memoizing the value with useMemo, splitting one large context into several smaller, more narrowly-scoped ones, or using a selector-based library for fine-grained subscriptions.',null,'const value = useMemo(() => ({ user, theme }), [user, theme]);
<AppContext.Provider value={value}>{children}</AppContext.Provider>','jsx','hard',ARRAY['react','state','context','performance']::text[],true,114),
('react','state','react-state-115','How do you decide between passing a prop, using Context, or reaching for an external store?','Use props when only one or two levels of the tree need the data, since it''s the most explicit and easiest to trace. Reach for Context when several components at varying depths need read access to relatively stable, infrequently-changing data. Reach for an external store or library when state changes frequently, is needed widely, and re-render performance or cross-cutting features like persistence or middleware matter.',null,null,null,'medium',ARRAY['react','state','context']::text[],false,115),
('react','state','react-state-116','What''s the difference between "server state" and "client state," and why does the distinction matter?','Client state is data that only ever lives in the browser, like a modal''s open/closed flag or a form draft, fully owned by the app. Server state is a client-side cache of data that actually lives on a server and can go stale, requiring concerns like refetching, caching, and synchronization that plain useState or useReducer weren''t designed for, which is why libraries like React Query or SWR exist specifically to manage it.',null,null,null,'medium',ARRAY['react','state','data-fetching']::text[],false,116),
('react','state','react-state-117','What are the main tradeoffs between controlled state, uncontrolled refs, and a form library for managing form state?','Fully controlled state, with every field backed by useState, gives full control and easy validation but can cause a re-render on every keystroke across a large form. Uncontrolled inputs with refs avoid that re-render cost by reading values only on submit, at the expense of harder real-time validation. Form libraries like React Hook Form aim for the best of both by using uncontrolled inputs internally while still exposing a controlled-feeling API with built-in validation and minimal re-renders.',null,null,null,'hard',ARRAY['react','state','forms']::text[],false,117),
('react','state','react-state-118','In what sense is the URL a form of application state?','Values encoded in the path or query string, like a selected tab, page number, or filter, represent state just like a useState value would, but with the added benefit of being shareable, bookmarkable, and preserved across a refresh — which is why pagination and filters commonly live in the URL instead of component state.',null,null,null,'easy',ARRAY['react','state','routing']::text[],false,118),
('react','state','react-state-119','What''s a simple pattern for persisting a piece of state to localStorage?','Initialize state lazily by reading from localStorage on the first render, then use a useEffect that writes the current value to localStorage whenever it changes, commonly wrapped into a reusable useLocalStorage custom hook.',null,'const [value, setValue] = useState(() => JSON.parse(localStorage.getItem(key)) ?? initial);
useEffect(() => { localStorage.setItem(key, JSON.stringify(value)); }, [key, value]);','jsx','easy',ARRAY['react','state','localstorage']::text[],false,119),
('react','state','react-state-120','How can changing a component''s key prop be used to reset its internal state?','React treats a component with a different key as an entirely new element, unmounting the old instance and discarding its state, then mounting a fresh one — so changing a form component''s key when switching between editing different records resets all of its internal state instantly without manual reset logic.',null,'<UserForm key={selectedUserId} user={selectedUser} />','jsx','medium',ARRAY['react','state','keys']::text[],false,120),
('react','state','react-state-121','What does the "single source of truth" principle mean for state design?','Each piece of data should have exactly one place it''s stored and considered authoritative — every other place that needs it should read or derive from that one source rather than keeping its own separate copy, which is what keeps duplicated state from silently drifting out of sync.',null,null,null,'easy',ARRAY['react','state']::text[],false,121),
('react','state','react-state-122','What is a "waterfall" of state updates, and why is it a performance concern?','It''s when fetching or computing one piece of state depends on first fetching another, which depends on a third, causing sequential renders and network round-trips instead of parallel ones — for example, fetching a user, then waiting for that to fetch their permissions, then waiting for that to fetch their dashboard data. Restructuring to kick off independent requests in parallel, or colocating data needs, avoids the compounding latency.',null,null,null,'hard',ARRAY['react','state','performance','data-fetching']::text[],false,122),
('react','state','react-state-123','What is an optimistic UI update?','It''s updating local state to reflect the expected result of an action, like marking a todo as done, immediately, before the server has actually confirmed it, so the UI feels instant, and rolling the state back if the request later fails, rather than waiting for a round-trip before showing any change.',null,null,null,'medium',ARRAY['react','state','data-fetching']::text[],false,123),
('react','state','react-state-124','Why might you pass a function to useState instead of an object literal directly, even for state that isn''t expensive to compute?','Passing a function guarantees the initializer only runs once on mount, which matters when constructing the initial object involves calling something with side effects, like Date.now() or a random ID generator, that shouldn''t re-run on every render even though its result is discarded after the first.',null,'const [id] = useState(() => crypto.randomUUID());','jsx','easy',ARRAY['react','state','usestate']::text[],false,124),
('react','state','react-state-125','How do you share state across different pages or routes in a single-page app?','Lift the state above the router, for example in a top-level provider, so it persists across navigations instead of being recreated per route, use Context or an external store to make it accessible from any route, or encode it in the URL itself if it should also survive a full page refresh.',null,null,null,'medium',ARRAY['react','state','routing']::text[],false,125),
('react','state','react-state-126','What is a "state machine" approach to modeling UI state, and what problem does it solve?','Instead of tracking independent booleans like isLoading, isError, and isSuccess, which can combine into invalid states like both being true at once, a state machine defines one explicit status value that can only be one of a fixed set of named states with defined transitions between them, making impossible states actually impossible to represent.',null,'type Status = ''idle'' | ''loading'' | ''success'' | ''error'';
const [status, setStatus] = useState(''idle'');','tsx','medium',ARRAY['react','state','state-machines']::text[],false,126),
('react','state','react-state-127','Why is tracking isLoading, isError, and hasData as three separate booleans risky?','Nothing prevents them from ending up in a combination that shouldn''t be possible, like isLoading and isError both true at once, and the component has to guess which one "wins" when rendering — a single status enum makes only one state representable at a time and removes that ambiguity entirely.',null,null,null,'medium',ARRAY['react','state','state-machines']::text[],false,127),
('react','state','react-state-128','What is a "selector" in the context of external state stores, and why does it help performance?','A selector is a small function that reads and derives just the specific slice of a larger store''s state a component needs, and most store libraries only re-render components whose selected slice actually changed — so a component selecting just one field won''t re-render when unrelated parts of the store update, unlike a component that reads the whole store object.',null,null,null,'hard',ARRAY['react','state','state-management','performance']::text[],false,128),
('react','state','react-state-129','How can component composition reduce the need for prop drilling?','Instead of passing a value down through several layers just so a deeply nested component can use it, a parent can render the deeply nested component directly and pass it in as children or another element prop at the top level — the intermediate components never need to know about the value at all since they just render whatever element they were given.',null,'function Layout({ sidebar, content }) {
  return <div><aside>{sidebar}</aside><main>{content}</main></div>;
}
// caller renders <Layout sidebar={<UserPanel user={user} />} content={...} />','jsx','medium',ARRAY['react','state','composition']::text[],false,129),
('react','state','react-state-130','Why might you split one large Context into several smaller ones?','Since every consumer of a Context re-renders whenever its value changes, bundling unrelated data like theme, user, and notifications into one context means a change to any of them re-renders everything that reads any of them. Splitting into separate contexts per concern lets a component subscribe only to the slice it actually needs.',null,'<ThemeContext.Provider value={theme}>
  <UserContext.Provider value={user}>
    {children}
  </UserContext.Provider>
</ThemeContext.Provider>','jsx','medium',ARRAY['react','state','context','performance']::text[],false,130),
('react','state','react-state-131','Why does an effect depending on an object or array from state sometimes run more often than expected?','If that object or array is recreated as a new reference on every render, even with identical contents, an effect depending on it sees a "changed" dependency on every render and re-runs every time, since dependency comparison in React is by reference, not deep equality. Memoizing the object or array with useMemo, or depending on its primitive fields individually, fixes it.',null,null,null,'medium',ARRAY['react','state','useeffect']::text[],false,131),
('react','state','react-state-132','How do you immutably update a single item inside an array of objects by its id?','Map over the array, returning a new object for the matching item with the changed fields spread in, and passing every other item through unchanged, then set that new array as state.',null,'setTodos(prev => prev.map(t => t.id === id ? { ...t, done: true } : t));','jsx','easy',ARRAY['react','state','immutability']::text[],false,132),
('react','state','react-state-133','What''s the correct way to toggle a boolean piece of state?','Use the functional updater form, flipping the previous value, rather than referencing a possibly-stale captured variable — this works correctly even if the toggle is called multiple times in quick succession.',null,'setIsOpen(prev => !prev);','jsx','easy',ARRAY['react','state','usestate']::text[],false,133),
('react','state','react-state-134','Should a form''s fields be tracked as one state object or as separate useState calls per field?','A single object usually scales better for forms with many fields since one generic onChange handler can update any field by key, whereas separate useState calls require a separate handler, or handler factory, per field but avoid needing to spread the whole object on every keystroke.',null,'const [form, setForm] = useState({ name: '''', email: '''' });
function handleChange(e) {
  setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
}','jsx','medium',ARRAY['react','state','forms']::text[],false,134),
('react','state','react-state-135','How does a controlled input''s value relate to component state?','The input''s displayed value is always driven by a state variable, and every keystroke fires onChange, which updates that state — meaning React, not the DOM, is the single source of truth for what''s currently in the field at all times.',null,null,null,'easy',ARRAY['react','state','forms']::text[],false,135),
('react','state','react-state-136','How would you debounce a state update that drives an expensive operation, like a search API call?','Keep the raw input value in state as-is for instant UI feedback, but derive a second, debounced value that''s updated only after the user pauses typing for a delay using a small useEffect with setTimeout and clearTimeout, and trigger the expensive operation off that debounced value instead of the raw one.',null,'useEffect(() => {
  const id = setTimeout(() => setDebounced(query), 300);
  return () => clearTimeout(id);
}, [query]);','jsx','medium',ARRAY['react','state','performance']::text[],false,136),
('react','state','react-state-137','How can you keep a piece of state in sync across multiple open browser tabs?','Persist the value to localStorage, and in each tab listen for the browser''s native storage event, which fires in other tabs, not the one that made the change, whenever localStorage is modified — updating local state from that event keeps every open tab reflecting the same value.',null,'useEffect(() => {
  function onStorage(e) {
    if (e.key === ''theme'') setTheme(e.newValue);
  }
  window.addEventListener(''storage'', onStorage);
  return () => window.removeEventListener(''storage'', onStorage);
}, []);','jsx','hard',ARRAY['react','state','localstorage']::text[],false,137),
('react','state','react-state-138','What are the tradeoffs between localStorage, sessionStorage, and cookies for persisting state?','localStorage persists indefinitely across tabs and browser restarts but isn''t sent to the server and has no built-in expiry. sessionStorage is scoped to a single tab and cleared when it closes, useful for per-session drafts. Cookies are automatically sent with every request, useful for auth, but have a small size limit and add overhead to every network request if overused.',null,null,null,'medium',ARRAY['react','state','localstorage']::text[],false,138),
('react','state','react-state-139','Why is storing both an items array and a separate itemCount in state usually a mistake?','itemCount can always be derived as items.length, so keeping it as separate state means every place that adds or removes an item must remember to update both, and any place that forgets creates a silently incorrect count — deriving it on the fly avoids that entire class of bugs.',null,'const itemCount = items.length; // derive, don''t store separately','jsx','easy',ARRAY['react','state','derived-state']::text[],false,139),
('react','state','react-state-140','What does the "single writer" principle mean for shared state?','Only one clearly defined place, such as a specific reducer, store action, or component, should be responsible for actually changing a given piece of shared state — other parts of the app can read it or request a change through that single path, but shouldn''t mutate it directly, which keeps changes traceable and prevents conflicting updates from different places.',null,null,null,'medium',ARRAY['react','state','state-management']::text[],false,140),
('react','state','react-state-141','Is it ever appropriate to pass a setState function itself down to a child as a prop?','Yes — for simple cases, passing the setter directly is simpler than wrapping it in a named callback prop, and since a setState function''s identity from useState is stable, it doesn''t cause extra re-renders. Wrapping it in a more descriptive callback becomes worthwhile once the child needs more than a raw setter, like validation before updating.',null,'<Toggle open={open} setOpen={setOpen} />','jsx','easy',ARRAY['react','state','usestate']::text[],false,141),
('react','state','react-state-142','How does using a reducer help keep related state changes atomic?','A single dispatched action can update multiple related fields together inside one reducer call, avoiding the situation with multiple separate setState calls where, due to batching or a re-render triggered mid-sequence, a component could theoretically be read in a state where only some of several related updates have landed.',null,'case ''FORM_SUBMIT_SUCCESS'':
  return { ...state, status: ''success'', data: action.payload, error: null };','jsx','medium',ARRAY['react','state','usereducer']::text[],false,142),
('react','state','react-state-143','What''s a clean way to represent the state of an async operation like a fetch?','Model it as a single status field with a fixed set of values such as idle, loading, success, and error, alongside the data and error fields, rather than several independent booleans — so the UI can render one clear switch or if-chain based on status instead of untangling combinations of isLoading, isError, and hasData.',null,'const [state, setState] = useState({ status: ''idle'', data: null, error: null });','jsx','medium',ARRAY['react','state','data-fetching']::text[],false,143),
('react','state','react-state-144','What''s the risk of one large component owning most of an app''s state directly?','It becomes a bottleneck where any state change re-renders the whole subtree unless carefully optimized, it''s hard to reason about which piece of state affects which part of the UI, and it discourages reusing the smaller pieces elsewhere — breaking state up and colocating it closer to where it''s used keeps things more maintainable.',null,null,null,'medium',ARRAY['react','state','composition']::text[],false,144),
('react','state','react-state-145','How do you test a reducer''s state transitions?','Since a reducer is a pure function of state and action producing a new state, you can call it directly in a test with a given starting state and action, and assert on the returned state — no component rendering or React testing utilities are needed at all.',null,null,null,'easy',ARRAY['react','state','testing','usereducer']::text[],false,145),
('react','state','react-state-146','Why doesn''t a state variable reflect its new value immediately after calling its setter?','Calling a state setter schedules an update for the next render rather than mutating the variable in place — the variable inside the current function''s closure still holds the old value until that component re-executes on the next render, which is why reading it on the very next line still shows the previous value.',null,'setCount(count + 1);
console.log(count); // still logs the OLD value','jsx','easy',ARRAY['react','state','usestate']::text[],true,146),
('react','state','react-state-147','If you need to act on a state value right after updating it, what should you do instead of reading the state variable on the next line?','Either compute the new value in a local variable and use that directly, or move the logic that depends on the new value into a useEffect that runs after the update has actually been applied and the component has re-rendered.',null,'const next = count + 1;
setCount(next);
doSomethingWith(next); // use the local variable, not ''count''','jsx','medium',ARRAY['react','state','usestate']::text[],false,147),
('react','state','react-state-148','What''s a simple way to reset a component''s state back to its initial values?','Store the initial state as a constant, or a function that produces it, and call the same setter again with that constant — with useReducer, dispatching a dedicated reset action that returns the original initial state works well for resetting several fields at once.',null,'const initialState = { name: '''', email: '''' };
setForm(initialState); // reset','jsx','easy',ARRAY['react','state','forms']::text[],false,148),
('react','state','react-state-149','If two pieces of state must always stay consistent with each other, what''s the better approach than updating both in sync?','Store only one of them as actual state, and compute the other from it during render, using useMemo if the computation is costly — that way there''s no possibility of them drifting apart, since the derived value can never be set to an inconsistent value on its own.',null,null,null,'medium',ARRAY['react','state','derived-state']::text[],false,149),
('react','state','react-state-150','Is passing a prop through one or two intermediate components always a problem worth solving with Context?','No — passing a prop through a shallow, well-understood chain of one or two levels is often clearer and easier to trace than introducing Context, which adds an indirection that can make it harder to see where a value actually comes from. Context earns its complexity once the chain gets deep or the same value is needed from many unrelated branches of the tree.',null,null,null,'easy',ARRAY['react','state','context']::text[],false,150)
) as v(language_slug, topic_slug, slug, question, answer, example, code, code_language, difficulty, tags, is_frequently_asked, display_order)
join public.languages l on l.slug = v.language_slug
join public.topics t on t.language_id = l.id and t.slug = v.topic_slug
on conflict (slug) do update set
  question = excluded.question,
  answer = excluded.answer,
  example = excluded.example,
  code = excluded.code,
  code_language = excluded.code_language,
  difficulty = excluded.difficulty,
  tags = excluded.tags,
  is_frequently_asked = excluded.is_frequently_asked,
  display_order = excluded.display_order,
  topic_id = excluded.topic_id,
  language_id = excluded.language_id;
